INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90061','fiesta','Festa Major de Sant Esteve','Patronal. Se celebra en Septiembre. Celebración de arraigo estrictamente local en un municipio de baja demografía del Pallars Jussà, centrada en actos litúrgicos tradicionales, comidas populares y bailes vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27015','fiesta','Festa Major de Sant Vicenç y Aplec de la Mare de Déu de la Pertusa','Patronal / Romería. Se celebra en Enero y Julio. Festejos locales que combinan el patrimonio litúrgico tradicional con la espectacular romería a la ermita románica colgada sobre el embalse de Canelles, atrayendo concurrencia comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90611','fiesta','Fira del Torró i la Xocolata de Pedra d''Agramunt y Festa Major de la Mare de Déu dels Socors','Gastronómica / Feria de Sector / Patronal. Se celebra en Septiembre (Festa Major) y Octubre (Fira). Declarada Fiesta de Interés Turístico por la Generalitat. Gran hito gastronómico de rango autonómico que exalta la elaboración artesanal del turrón con Indicación Geográfica Protegida, atrayendo a miles de visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90612','fiesta','Festa Major de Sant Just y Aplec de les Peces','Patronal / Romería. Se celebra en Julio y Agosto. Festejos del Alt Urgell que reúnen a los núcleos del término mediante la romería tradicional a la ermita de la Mare de Déu de les Peces, acompañados de música de acordeón pirenaico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90902','fiesta','Festa Major de Cosme i Damià','Patronal. Se celebra en Septiembre. Festejos de arraigo local tradicionales en las Garrigues, caracterizados por los pasacalles populares, el tradicional repique de campanas y las verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90613','fiesta','Festa Major de Sant Salvador','Patronal. Se celebra en Agosto. Festejos veraniegos de carácter local potenciados por la población del llano de Lleida, articulados sobre verbenas lúdicas, actividades infantiles y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90614','fiesta','Festa Major de la Mare de Déu de l''Assumpció','Patronal / Etnográfica. Se celebra en Agosto. Celebración tradicional en la Noguera que cuenta con pasacalles de gigantes comarcales, bailes de sardanas en la plaza mayor y gran implicación lúdica de sus peñas juveniles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90615','fiesta','Festa Major de Sant Pere del Mel i Sant Roc','Patronal. Se celebra en Agosto. Pequeña celebración veraniega de marcado carácter vecinal sustentada en el regreso estival de familias, con comidas comunitarias al aire libre y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90616','fiesta','Festa Major de Tardor (Sant Ramon) i d''Estiu','Patronal / Cultural / Feria Tradicional. Se celebra en Agosto y Diciembre. Festejos de rango comarcal consolidados con un potente programa lúdico en el Segrià, con correfocs de diablos locales, masiva participación en las peñas y ferias del sector agrícola.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90617','fiesta','Festa Major de Sant Miquel','Patronal. Se celebra en Septiembre. Festejos locales que complementan las misas tradicionales y pasacalles folclóricos con competiciones deportivas locales y sesiones de orquesta muy concurridas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90616','fiesta','Festa Major de Sant Pere y Festa del Préssec','Patronal / Gastronómica. Se celebra en Junio (Sant Pere) y Octubre (Préssec). Festejos tradicionales que promueven los productos agrícolas del llano mediante la feria dedicada a su afamado melocotón de Alfarràs, con folclore local y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90618','fiesta','Festa Major de Sant Salvador','Patronal. Se celebra en Agosto. Celebración de escala estrictamente local en una zona de baja demografía, basada en ritos litúrgicos tradicionales, juegos infantiles y cenas populares de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25019','fiesta','Festa de l''Aigua i Festa Major de la Mercè','Etnográfica / Cultural / Patronal. Se celebra en Marzo (Aigua) y Septiembre (Mercè). Su histórica Festa de l''Aigua posee rango comarcal de alta popularidad, conmemorando la llegada del agua del Canal de Aragón y Cataluña con espectaculares desfiles de carrozas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25020','fiesta','Festa Major de Sant Miquel','Patronal. Se celebra en Septiembre. Festejos tradicionales en el extremo sur del Segrià, caracterizados por el reencuentro vecinal, campeonatos de cartas tradicionales y bailes públicos nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25021','fiesta','Festa Major de Sant Roc','Patronal / Etnográfica. Se celebra en Agosto. Festejos de arraigo local tradicionales que integran pasacalles de su colla de gigantes, correfocs de diablos de la comarca, sardanas y verbenas estivales multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25022','fiesta','Festa Major de Sant Feliu','Patronal. Se celebra en Septiembre. Pequeñas fiestas de arraigo puramente local con ritos religiosos tradicionales en su iglesia histórica y comidas de hermandad adaptadas a su reducida población.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25023','fiesta','Festa Major de Sant Bartomeu y Circ Picat','Patronal / Cultural / Festival Teatral. Se celebra en Agosto. Festejos muy dinamizados por el festival Circ Picat, hito cultural que atrae a numeroso público regional para presenciar espectáculos de circo callejero tradicionales y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25024','fiesta','Festa Major d''Isil y Baixada de Falles d''Isil','Etnográfica / Antorchas / Mitológica. Se celebra en Junio (Noche de San Juan). Declarada Patrimonio Cultural Inmaterial de la Humanidad por la UNESCO. Espectacular y ancestral ritual pirenaico donde los jóvenes descienden de la montaña con monumentales troncos encendidos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25027','fiesta','Tres Tombs d''Anglesola y Festa Major de Santa Creu','Etnográfica / Tradicional / Patronal. Se celebra en Abril (Tres Tombs) y Septiembre (Festa Major). Declarada Fiesta de Interés Turístico por la Generalitat. Hito absoluto de las fiestas de arrieros en el interior de Lleida, famosa por su masivo desfile de carros tradicionales tirados por caballerías.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25029','fiesta','Festa Major de Sant Jaume y Fira de Santa Caterina','Patronal / Gastronómica / Feria Tradicional. Se celebra en Julio (Sant Jaume) y Noviembre (Fira). Festejos de relevancia comarcal en las Garrigues; su feria tradicional destaca por la promoción artesanal de su afamado aceite de oliva virgen extra con DOP y el mercado de aceitunas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25031','fiesta','Festa Major de Sant Joan d''Arres de Sus','Patronal. Se celebra en Agosto. Mínima expresión festiva de carácter estrictamente familiar en la Val d''Aran debido a la bajísima demografía del núcleo, limitada a cantos litúrgicos tradicionales y un almuerzo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25032','fiesta','Trobada amb els Acordionistes del Pirineu i Festa Major de Santa Coloma','Cultural / Folclórica / Patronal. Se celebra en Julio. Hito folclórico de rango y trascendencia internacional. Considerado el festival de música tradicional y de acordeón diatónico más antiguo e importante del Pirineo, congregando a miles de personas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25033','fiesta','Festa Major de Sant Miquel','Patronal / Etnográfica. Se celebra en Septiembre. Festejos tradicionales del Segrià que dinamizan la población con pasacalles populares, el Ball de Diables local y cenas comunitarias de hermandad al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25034','fiesta','Festa Major de Sant Bartomeu *','Patronal / Cultural *. Se celebra en Agosto *. Celebración con gran arraigo comarcal en la Noguera, caracterizada por un amplio programa que incluye castellers tradicionales, pasacalles de gigantes y cabezudos y verbenas estivales masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25036','fiesta','Festa Major de Sant Julià','Patronal. Se celebra en Enero. Mínimos festejos rurales de invierno en un municipio de baja demografía, centrados en actos religiosos tradicionales y una comida compartida entre los vecinos de la localidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90619','fiesta','Festa Major de Gerri de la Sal','Patronal / Etnográfica. Se celebra en Agosto. Destacan por la conservación del histórico Ball de Moriscos de Gerri de la Sal, hito etnográfico pirenaico de alta raigambre folclórica bailado frente al antiguo monasterio medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25040','fiesta','Festes de Sant Crist de Balaguer','Patronal / Etnográfica / Cultural. Se celebra en Noviembre. Grandes fiestas de la capital de la Noguera, muy populares por sus solemnes procesiones, las tradicionales e históricas trobades de gegants, bailes de sardanas multitudinarios y macroconciertos públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25041','fiesta','Festa de la Poma de Barbens y Festa Major del Roser','Gastronómica / Feria Tradicional / Patronal. Se celebra en Octubre. Festejos de arraigo tradicional en el Pla d''Urgell orientados a la promoción de su cultivo histórico frutal mediante la Feria de la Manzana, sumando folclore local y comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25043','fiesta','Baixada de Falles de Taüll, Boí, Erill la Vall i Barruera','Etnográfica / Antorchas / Patrimonio Humanidad. Se celebra en Junio y Julio. Declaradas Patrimonio Cultural Inmaterial de la Humanidad por la UNESCO. Ritual milenario de fuego purificador que atrae masivo turismo de todo el mundo hacia sus iglesias románicas fortificadas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25047','fiesta','Festa Major de Sant Pere y de la Mare de Déu d''Almatà','Patronal. Se celebra en Septiembre. Festejos tradicionales de la comarca de la Noguera, caracterizados por pasacalles musicales con gigantes, competiciones lúdicas locales y bailes populares nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90620','fiesta','Festa Major de Sant Miquel','Patronal / Cultural. Se celebra en Septiembre. Festejos tradicionales del llano con pasacalles de gigantes de la zona, competiciones de cartas tradicionales, espectáculos infantiles y orquestas populares en el pabellón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25049','fiesta','Festa Major de Sant Josep','Patronal. Se celebra en Mayo. Pequeña celebración de primavera de marcado ambiente vecinal adaptada a la baja demografía, limitada a misas tradicionales y comidas comunitarias en la plaza del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25050','fiesta','Festa de la Mare de Déu dels Dolors de Bellpuig','Religiosa / Etnográfica / Procesión. Se celebra en Marzo / Abril (Viernes de Dolor). Declarada Fiesta de Interés Turístico por la Generalitat. Hito religioso de enorme empaque regional, célebre por su solemne y silenciosa procesión penitencial de gran valor histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25051','fiesta','Fira de Sant Llorenç (Fira de Formatges Artesans del Pirineu)','Gastronómica / Feria de Sector. Se celebra en Agosto. Gran cita del verano en la Cerdanya ilerdense dedicada a la muestra y degustación de quesos artesanales del Pirineo, arropada por mercados tradicionales y folclore pirenaico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25052','fiesta','Els Firals de Bellvís (Festa de l''Anella) y Festa Major de la Mare de Déu de les Sogues','Recreación Histórica / Etnográfica / Patronal. Se celebra en Julio (Els Firals) y Octubre (Patronal). Gran recreación a nivel provincial que moviliza al pueblo vistiéndolo al estilo del siglo XVII para escenificar leyendas locales históricas y antiguos oficios tradicionales artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25053','fiesta','Festa Major de Sant Joan Bautista','Patronal. Se celebra en Junio. Festejos locales tradicionales del Segrià orientados a las actividades familiares de verano, con tradicionales misas solemnes, comidas populares y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25055','fiesta','Festa Major de Sant Llobí','Patronal. Se celebra en Septiembre. Pequeñas fiestas de arraigo puramente local en el Solsonès oriental, estructuradas sobre actos religiosos tradicionales y cenas de hermandad para los vecinos residentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25059','fiesta','Fiestas de San Roque y Procesiones de Semana Santa de Bossòst','Religiosa / Etnográfica / Patronal. Se celebra en Abril (Semana Santa) y Agosto (San Roque). De enorme relevancia en la Val d''Aran por conservar las únicas procesiones tradicionales vivas de Semana Santa de la zona, atrayendo masiva afluencia del pirineo galo y local). ¿Deseas continuar con el Siguiente Bloque de la provincia de Lleida (Letras de la C a la J.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25060','fiesta','Festa Major de Sant Joan y de la Mare de Déu del Roser','Patronal. Se celebra en Junio y Septiembre. Festejos rurales de arraigo estrictamente local en la comarca de la Noguera, condicionados por su baja demografía, sustentados en comidas populares y verbenas lúdicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25061','fiesta','Festa Major de Sant Serni de Cabó','Patronal. Se celebra en Noviembre. Mínima expresión festiva debido a la baja demografía del valle en el Alt Urgell, limitada a ritos religiosos tradicionales y un encuentro vecinal de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25062','fiesta','Festa Major de Camarasa i de Sant Llorenç de Montgai','Patronal. Se celebra en Agosto. Festejos tradicionales de marcado carácter veraniego e infantil junto al entorno de la Noguera Pallaresa, basados en comidas populares de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25063','fiesta','Festa Major de Sant Joan de Canejan','Patronal. Se celebra en Agosto. Festejos tradicionales de alta montaña y marcado carácter familiar en el Bajo Aran, basados en comidas populares y música tradicional de acordeón pirenaico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25904','fiesta','Aplec de Mur y Festa Major de Guàrdia de Noguera','Romería / Etnográfica / Patronal. Se celebra en Mayo (Aplec) y Agosto (Festa Major). Su histórico Aplec en la colegiata fortificada medieval posee gran relevancia comarcal e identidad en el Pallars Jussà, atrayendo a numerosos peregrinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25064','fiesta','Festa Major de Sant Andreu','Patronal. Se celebra en Noviembre. Pequeña celebración vecinal con núcleos de población muy dispersos en el Solsonès, vertebrada en torno a la santa misa tradicional y un vermut popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25067','fiesta','Festa Major de la de la Mare de Déu de Montserrat','Patronal / Enológica. Se celebra en Septiembre. Festejos de arraigo local tradicionales en la comarca de las Garrigues, caracterizados por los pasacalles populares, bailes de sardanas de plaza y verbenas de noche.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25068','fiesta','Festa Major de Sant Joan Bautista','Patronal. Se celebra en Agosto. Celebración trasladada de época para asegurar la concurrencia de la población residencial del Pla d''Urgell, basada en torneos lúdicos y sesiones de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25070','fiesta','Festa Major de Sant Sebastià y Festa del Bandoler','Recreación Histórica / Etnográfica / Patronal. Se celebra en Enero (Sebastià) y Mayo (Bandoler). Su Fiesta del Bandolero posee un gran arraigo provincial, recreando con fidelidad las andanzas de los bandoleros del siglo XV en Urgell con mercados tradicionales y trabucos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25071','fiesta','Festa Major de Sant Aniol y de Anserall','Patronal. Se celebra en Agosto. Mínimos festejos rurales en una de las zonas menos pobladas del Alt Urgell, limitados a actos religiosos tradicionales y cenas vecinales en las faldas del Cadí.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25072','fiesta','Aquelarre de Cervera y Festa Major del Sant Crist','Etnográfica / Pirotécnica / Cultural. Se celebra en Agosto (Aquelarre) y Septiembre (Festa Major). Declarada Fiesta de Interés Turístico por la Generalitat. Hito pirotécnico y esotérico masivo global del interior catalán, célebre por la espectacular "Encesa" y correfocs multitudinarios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25073','fiesta','Festa Major de Sant Miquel','Patronal / Gastronómica. Se celebra en Septiembre. Festejos de arraigo tradicional vinculados al cultivo del aceite de oliva virgen extra con DOP, con pasacalles musicales con gigantes y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25074','fiesta','Trobada de Grups de Recreació Medieval i Festa Major de Sant Roc','Recreación Histórica / Patronal. Se celebra en Mayo (Medieval) y Agosto (Sant Roc). Su encuentro medieval a la sombra del castillo posee gran relevancia provincial, transformando la villa con campamentos de época, torneos tradicionales de caballeros y artesanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25075','fiesta','Festa Major de Sant Serni','Patronal. Se celebra en Agosto. Pequeña celebración de verano en el entorno rural del Solsonès, sustentada en ritos religiosos tradicionales, juegos infantiles y comidas vecinales de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25077','fiesta','Festa dels Raiers de Coll de Nargó y Festa Major de Sant Climent','Etnográfica / Acuática / Patrimonio Humanidad. Se celebra en Agosto. Declarada Patrimonio Cultural Inmaterial de la Humanidad por la UNESCO. Hito histórico y etnográfico masivo que recrea el antiguo descenso de maderos amarrados por el río Segre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25161','fiesta','Festa Major del Pont de Claverol','Patronal. Se celebra en Agosto. Festejos locales tradicionales del Pallars Jussà orientados a las actividades familiares de verano, con tradicionales misas solemnes y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25078','fiesta','Festa Major de Santa Quitèria y de Sant Jaume','Patronal. Se celebra en Mayo y Julio. Festejos tradicionales de carácter familiar en la comarca del Segrià, consistentes en pasacalles musicales con gigantes, correfocs de diablos locales y cenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25079','fiesta','Festa Major del Sant Crist de Cubells','Patronal / Etnográfica. Se celebra en Septiembre. Celebración de la Noguera con tradicionales pasacalles, pasacalles pirotécnicos locales, bailes de sardanas de plaza y una activa participación vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25081','fiesta','Festa Major de la de la Mare de Déu de la Candelera','Patronal. Se celebra en Agosto. Festejos locales en las Garrigues orientadas al regreso de veraneantes estivales a la sombra de su castillo histórico, con comidas populares y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27005','fiesta','Festa Major d''Esterri d''Àneu y Esbaiola''t','Patronal / Cultural / Festival Teatral. Se celebra en Agosto (Festa Major) y Julio (Esbaiola''t). Su festival de teatro familiar al aire libre Esbaiola''t posee rango comarcal y provincial de alta popularidad, transformando los Pirineos con artes escénicas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25088','fiesta','Festa Major de Sant Vicenç de Estamariu','Patronal. Se celebra en Enero y Agosto. Pequeñas fiestas estivales de marcado ambiente familiar adaptadas a la baja demografía del Alt Urgell, limitadas a misas tradicionales y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25089','fiesta','Festa Major de Farrera y de Burg','Patronal. Se celebra en Agosto. Festejos veraniegos mínimos distribuidos entre los caseríos y pequeños núcleos dispersos de la Coma de Burg en el Pallars Sobirà, centrados en comidas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25908','fiesta','Festa Major d''Alinyà y de Fígols','Patronal. Se celebra en Agosto. Festejos unificados de montaña que dinamizan los pequeños caseríos del término en torno al regreso de familias, con tradicionales misas solemnes y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25093','fiesta','Festa Major de Sant Sebastià y de la Mare de Déu del Roser','Patronal. Se celebra en Septiembre. Celebración de escala estrictamente local en el llano del Pla d''Urgell, vertebrada sobre comidas vecinales al aire libre y sesiones de orquesta nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25094','fiesta','Festa Major de la Mare de Déu de Salgar','Romería / Patronal. Se celebra en Septiembre. Festejos locales que giran en torno a la concurrida romería tradicional al espectacular santuario excavado en la roca de Salgar, aunando fe y tradición comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25097','fiesta','Fira Herois de Fulleda y Festa Major del Roser *','Recreación Histórica / Patronal *. Se celebra en Agosto (Herois) y Septiembre (Festa Major) *. Festejos tradicionales de las Garrigues orientales destacados por la feria que recrea pasajes históricos de la Guerra de la Independencia y la figura de Agustina de Aragón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25098','fiesta','Festa Major de Sant Pere de Gavet','Patronal. Se celebra en Agosto. Pequeña festividad local del Pallars Jussà que congrega a los habitantes en torno a una misa solemne tradicional, comidas populares de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25912','fiesta','Festa Major del Pla de la Font y de Gimenells','Patronal. Se celebra en Mayo y Octubre. Festejos de este municipio de colonización agrícola del Segrià, caracterizados por el desfile de carrozas populares, competiciones lúdicas locales y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25099','fiesta','Festa Major de Sant Salvador','Patronal / Cultural. Se celebra en Agosto. Festejos patronales tradicionales del Pla d''Urgell, caracterizados por el desfile de gigantes comarcales, pasacalles musicales con agrupaciones y orquestas de plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25100','fiesta','Festa Major de la Mare de Déu del Castell','Patronal / Etnográfica. Se celebra en Agosto. Festejos tradicionales al pie del Pedraforca de gran valor identitario, célebres por la conservación del Ball de les Cosses, una joya del folclore musical pirenaico catalogada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25101','fiesta','Fira de l''Oli de la Granadella y Festa Major del Sant Crist de la Gràcia','Gastronómica / Feria de Sector / Patronal. Se celebra en Septiembre (Festa Major) y Noviembre (Fira). Su fira dedicada al aceite de oliva virgen extra de la primera prensada posee un notable arraigo provincial, atrayendo a numeroso público gastronómico y mercados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25102','fiesta','Festa Major de Sant Jaume','Patronal / Taurina. Se celebra en Julio. Festejos tradicionales en la confluencia del Segre y el Cinca, caracterizados por sus tradicionales vaquillas populares en plaza portátil, jotas y cenas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25109','fiesta','Mercat Medieval de Guimerà y Festa Major de Sant Sebastià','Recreación Histórica / Feria Tradicional / Patronal. Se celebra en Agosto (Mercat) y Enero (Sebastià). Su mercado medieval medieval posee rango comarcal de alta popularidad, transformando por completo su casco histórico fortificado protegido con muestras de antiguos oficios artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25110','fiesta','Mercat Romà de Guissona y Festa Major de la Mare de Déu del Claustre','Recreación Histórica / Etnográfica / Patronal. Se celebra en Julio (Mercat Romà) y Septiembre (Festa Major). Declarado de gran relevancia etnográfica provincial. Espectacular recreación histórica de la antigua Iesso que transforma la Segarra con legiones, termas y luchas de gladiadores masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25111','fiesta','Festa Major de la de la Mare de Déu de Valls','Romería / Patronal. Se celebra en Septiembre. Mínimos festejos vecinales en una zona de alta montaña del Solsonès, limitados a la romería al santuario tradicional de la comarca y encuentros familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25115','fiesta','Festa Major d''Isona','Patronal. Se celebra en Agosto. Festejos locales tradicionales del Pallars Jussà orientados a las actividades de verano, con tradicionales misas solemnes, comidas de hermandad y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25910','fiesta','Festa Major de Tuixén (Festa de les Trementinaires)','Etnográfica / Feria Tradicional / Patronal. Se celebra en Mayo (Trementinaires) y Agosto (Festa Major). De enorme relevancia etnográfica provincial por la Festa de les Trementinaires, hito tradicional que rinde homenaje a las mujeres curanderas del Pirineo con hierbas medicinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25118','fiesta','Festa Major de Sant Joan y el Ball de Diables de Juncosa','Patronal / Etnográfica. Se celebra en Junio. Festejos de arraigo local tradicionales en las Garrigues, caracterizados por los pasacalles populares, pasacalles pirotécnicos con fuego local y bailes de sardanas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25119','fiesta','Concurs de Cassoles de Tros de Juneda y Festa Major de las Santes Creus','Gastronómica / Etnográfica / Patronal. Se celebra en Junio (Cassoles) y Agosto (Festa Major). Hito gastronómico de gran renombre provincial célebre por su multitudinario concurso de cazuelas de campo tradicionales cocinadas con leña en pleno parque comunal). ¿Deseas continuar con el Siguiente Bloque de la provincia de Lleida (Letras de la L a la P.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25121','fiesta','Crèma deth Haro de Les','Etnográfica / Antorchas / Patrimonio Humanidad. Se celebra en Junio (Noche de San Juan). Declarada Patrimonio Cultural Inmaterial de la Humanidad por la UNESCO. Impresionante rito milenario aranesa donde se quema un gran tronco de abeto purificador en la plaza del pueblo entre danzas folclóricas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25122','fiesta','Festa Major de la Mare de Déu dels Dolors y Pessebre Vivent de Linyola','Patronal / Teatral / Etnográfica. Se celebra en Mayo (Festa Major) y Diciembre/ Enero (Pessebre). Festejos de notable peso comarcal en el Pla d''Urgell, destacados por la gran afluencia provincial hacia su pesebre viviente con escenas tradicionales de antiguos oficios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25123','fiesta','Festa Major de Lladorre y Aplec de Tabescan','Patronal / Romería. Se celebra en Agosto. Festejos tradicionales de alta montaña en el Valle de Cardós, caracterizados por la procesión litúrgica, música tradicional de acordeón pirenaico y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25124','fiesta','Festa Major de Lladurs','Patronal. Se celebra en Julio. Mínima expresión festiva de carácter estrictamente vecinal y de dispersión rural en el Solsonès, limitada a una misa solemne y un vermut popular comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25125','fiesta','Festa Major de la Mare de Déu de Loreto','Patronal. Se celebra en Agosto. Festejos de escala estrictamente local orientados al reencuentro de familias veraneantes en el Segrià, con juegos infantiles tradicionales y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25126','fiesta','Festa Major de Santa Anna y Concurs de Gos d''Atura de Llavorsí','Patronal / Etnográfica / Tradicional. Se celebra en Julio (Festa Major) y Agosto (Gos d''Atura). Su concurso de perros pastores posee un gran arraigo e impacto provincial en el Pallars Sobirà, atrayendo a numeroso público ganadero y turístico a los Pirineos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27008','fiesta','Festes de Sant Anastasi (Festa Major de Maig) i de Sant Miquel (Festa de Tardor)','Patronal / Etnográfica / Cultural. Se celebra en Mayo y Septiembre. Declarada Fiesta de Interés Turístico de rango nacional por su colosal despliegue. Célebre por el desfile de los históricos gigantes monumentales, los bailes moros y cristianos y la multitudinaria batalla de flores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25127','fiesta','Festa Major de Sant Pere de Lles','Patronal. Se celebra en Junio. Festejos tradicionales de montaña adaptados a su entorno rural pirenaico, centrados en el regreso estival de familias, comidas vecinales de hermandad y música de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25129','fiesta','Festa Major de Llobera y de Peracamps','Patronal. Se celebra en Septiembre. Pequeña celebración vecinal con núcleos residenciales dispersos en el Solsonès meridional, estructurada sobre la santa misa tradicional y bailes populares lúdicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90903','fiesta','Fira de l''Verd i de l''Oli de Maials y Festa Major de Sant Miquel','Gastronómica / Feria de Sector / Patronal. Se celebra en Noviembre (Fira) y Septiembre (Festa Major). Su feria dedicada al aceite de oliva virgen extra de la primera prensada posee un notable arraigo comarcal en el Segrià, atrayendo mercados de productos locales y catas artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25130','fiesta','Festa Major de Sant Macari','Patronal. Se celebra en Enero y Agosto. Festejos locales trasladados de época estival para favorecer la concurrencia en la comarca del Urgell, basados en pasacalles populares, juegos infantiles y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25131','fiesta','Festa Major de Sant Bartomeu','Patronal. Se celebra en Agosto. Festejos patronales tradicionales del Segrià al límite con Aragón, articulados sobre verbenas nocturnas al aire libre, comidas populares de hermandad y actos litúrgicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90621','fiesta','Festa Major de Sant Salvador de Massoteres','Patronal. Se celebra en Agosto. Pequeñas fiestas de arraigo puramente local en la comarca de la Segarra, basadas en ritos religiosos tradicionales en el templo parroquial y música en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25134','fiesta','Festa Major de Sant Vicenç','Patronal. Se celebra en Septiembre. Festejos tradicionales del llano de la Noguera con pasacalles musicales con gigantes comarcales, campeonatos de cartas tradicionales, comidas populares y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25135','fiesta','Festa Major de Sant Miquel','Patronal. Se celebra en Septiembre. Festejos locales del Pla d''Urgell, caracterizados por el desfile de gigantes, pasacalles lúdicos, bailes de sardanas de plaza y una activa participación vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27009','fiesta','Festa Major de Mollerussa y Concurs de Vestits de Paper','Cultural / Pasarela Tradicional / Patronal. Se celebra en Mayo (Festa Major) y Diciembre (Vestits de Paper). Su monumental certamen nacional de trajes de papel es un hito de rango autonómico de extraordinaria singularidad y maestría artesanal, atrayendo masiva cobertura mediática.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25136','fiesta','Festa Major de la Molsosa y de Prades','Patronal. Se celebra en Septiembre. Mínimos festejos rurales condicionados por la baja demografía en el Solsonès oriental, limitados a la liturgia tradicional en la iglesia histórica y encuentros vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25139','fiesta','Festa Major de Martinet de Cerdanya','Patronal. Se celebra en Julio. Celebración de montaña que dinamiza los núcleos del término en torno al regreso de veraneantes, con comidas de hermandad, pasacalles infantiles y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25140','fiesta','Festa Major de Castellbò y Mercado Medieval','Recreación Histórica / Patronal. Se celebra en Agosto. Festejos del Alt Urgell que destacan por el mercado tradicional medieval en su casco histórico, conmemorando el pasado de su vizcondado con desfiles y artesanos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25138','fiesta','Fira de la Màgia al Carrer de Montgai (Montgai Màgic) y Festa Major de la Mare de Déu de l''Assumpció','Cultural / Festival Teatral / Patronal. Se celebra en Agosto (Festa Major) y Octubre (Màgic). Hito cultural a nivel provincial de gran dinamismo; el Montgai Màgic transforma por completo el pueblo de la Noguera con cientos de magos tradicionales y espectáculos callejeros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25142','fiesta','Festa Major de la Mare de Déu de la Bassa','Patronal. Se celebra en Septiembre. Festejos patronales tradicionales del Segrià centrados en actividades vecinales familiares, con procesiones litúrgicas tradicionales, comidas populares y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25142','fiesta','Festa Major de Sant Salvador de Vilagrasseta','Patronal. Se celebra en Agosto. Festejos rurales mínimos en una comarca de baja densidad de población como la Segarra, basados en comidas familiares y ritos religiosos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25143','fiesta','Festa Major de Sant Joan Bautista','Patronal. Se celebra en Agosto. Pequeña festividad veraniega de marcado carácter vecinal orientada estrictamente a la población flotante y local del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25145','fiesta','Festa Major de Sant Jaume y de la Mare de Déu del Roser','Patronal. Se celebra en Julio y Septiembre. Celebración de escala estrictamente local en el Valle del Corb, vertebrada sobre comidas populares de hermandad vecinal, ritos litúrgicos tradicionales y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90622','fiesta','Festa Major de Salardú, Arties i Vielha (Romiatge d''Arties)','Patronal / Etnográfica / Romería *. Se celebra en Junio (Romiatge) y Agosto/Septiembre (Fiestas) *. Gran relevancia etnográfica en la Val d''Aran por el Romiatge d''Arties, hito tradicional que une el fervor mariano con espectaculares bailes tradicionales araneses de alta raigambre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25146','fiesta','Festa Major de Navès y de la Mare de Déu de les Peces','Patronal / Romería. Se celebra en Septiembre. Pequeñas fiestas estivales con romería tradicional a las ermitas rurales del Solsonès, combinando el fervor tradicional con comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25149','fiesta','Festa Major d''Oliana y la Fira de Tots Sants','Patronal / Feria Comercial Tradicional. Se celebra en Agosto (Festa Major) y Noviembre (Fira). Festejos de arraigo comarcal en el Alt Urgell meridional; su feria tradicional de origen medieval destaca provincialmente por sus muestras de artesanía y mercados agrícolas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25150','fiesta','Festa Major de Sant Serni de Clariana','Patronal. Se celebra en Agosto. Mínimos festejos de carácter vecinal debido a la escasa población residente, limitados a actos litúrgicos tradicionales y un vermut popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25151','fiesta','Festa Major de Sant Esteve d''Olius','Patronal / Romería. Se celebra en Agosto. Festejos que combinan la liturgia tradicional en torno a su célebre cripta románica fortificada y cementerio modernista con comidas vecinales e infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25155','fiesta','Fira de Sant Andreu de Organyà y Festa Major de la Mare de Déu de l''Assumpció','Feria Tradicional / Cultural / Patronal. Se celebra en Agosto (Festa Major) y Noviembre (Fira). Posee una gran relevancia histórica y cultural por su Fira de Sant Andreu vinculada a las Homilías de Organyà, hito tradicional del origen de la lengua catalana arropado por mercados artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25156','fiesta','Trobada de Campaners d''Os de Balaguer y Festa Major de la Mare de Déu de l''Aguda','Etnográfica / Encuentro Tradicional / Patronal. Se celebra en Abril (Campaners) y Septiembre (Festa Major). De enorme relevancia etnográfica provincial por su Encuentro de Campaneros, hito único que recupera de forma masiva los toques tradicionales de campana como lenguaje inmaterial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25164','fiesta','Festa Major de Sant Joan y GarGar Festival de Murales','Patronal / Cultural / Festival Urbano. Se celebra en Mayo (GarGar) y Agosto (Festa Major). Festejos impulsados a nivel provincial e internacional por el festival GarGar de arte urbano tradicional, que congrega a miles de personas en este pueblo de la Noguera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25165','fiesta','Festa Major de la Mare de Déu del Roser','Patronal. Se celebra en Septiembre. Festejos tradicionales serranos del Alt Urgell con procesiones litúrgicas tradicionales, pasacalles musicales con agrupaciones locales y comidas de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25166','fiesta','Festa Major de Sant Miquel de Pinell','Patronal. Se celebra en Septiembre. Mínimos festejos rurales distribuidos entre las masías y pequeños caseríos dispersos del Solsonès occidental, centrados en comidas familiares tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25167','fiesta','Aplec del Santuari de Pinós y Festa Major de Sant Vicenç','Romería / Etnográfica / Patronal. Se celebra en Mayo (Aplec) y Agosto (Festa Major). Concurrida festividad tradicional en pleno centro geográfico de Cataluña, que atrae a peregrinos de toda la comarca para bailes de sardanas de plaza y reparto de caridad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25168','fiesta','Festa Major de Sant Joan Bautista','Patronal. Se celebra en Agosto. Celebración de carácter tradicional y vecinal en el Pla d''Urgell, estructurada en torno a ritos religiosos tradicionales, comidas populares de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25169','fiesta','Festa Major de la Mare de Déu de la Lluna','Patronal / Enológica. Se celebra en Octubre. Festejos de arraigo tradicional en las Garrigues orientales, vinculados a la recogida de la uva de la DO Costers del Segre, con pasacalles y verbenas lúdicas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25171','fiesta','Festa de les Falles de la Pobla de Segur y Fiesta de los Raiers','Etnográfica / Antorchas / Patrimonio Humanidad. Se celebra en Junio (Falles) y Julio (Raiers). Declarada Patrimonio Cultural Inmaterial de la Humanidad por la UNESCO. Espectacular bajada de fallas milenarias donde las parejas descienden con antorchas encendidas de madera de pino por la montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25030','fiesta','Festa Major de Aristot y del Pont de Bar','Patronal / Enológica. Se celebra en Agosto. Festejos rurales de alta montaña en el estrecho del Segre, vinculados históricamente a la viticultura heroica del Alt Urgell, con comidas familiares mínimas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25173','fiesta','Festa de Sant Sebastià y Baixada de Falles del Pont de Suert','Etnográfica / Antorchas / Patrimonio Humanidad. Se celebra en Enero (Sebastià) y Junio (Falles). Declarada Patrimonio Cultural Inmaterial de la Humanidad por la UNESCO. Máximo exponente tradicional y festivo de la Alta Ribagorça con su milenaria bajada nocturna de troncos encendidos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25172','fiesta','Festa del Ranxo de Ponts y Festa Major de Sant Pere','Gastronómica / Etnográfica / Patronal. Se celebra en Febrero (Ranxo) y Septiembre (Festa Major). Declarada Fiesta de Interés Turístico por la Generalitat. Hito de la gastronomía de carnaval donde se cocinan toneladas de una monumental escudella tradicional en calderas de cobre en plena calle.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25174','fiesta','Festa Major de Sant Pere Advíncula','Patronal. Se celebra en Agosto. Pequeños festejos tradicionales de verano en el Segrià septentrional, basados en ritos litúrgicos tradicionales, juegos infantiles y sesiones de orquesta nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90623','fiesta','Festa Major de Sant Serni de Prats','Patronal. Se celebra en Noviembre. Festejos de ámbito local de baja densidad demográfica en la Cerdanya ilerdense, centrados en ritos tradicionales religiosos y comidas populares vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25176','fiesta','Fira gastronòmica De Prop de Preixana y Festa Major de Sant Llorenç','Gastronómica / Feria Tradicional / Patronal. Se celebra en Agosto (Festa Major) y Diciembre (De Prop). Festejos con notable raigambre en el Urgell meridional; su mercado de productos alimentarios de proximidad atrae provincialmente a numeroso público gourmet.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25177','fiesta','Festa Major de Preixens, Ventoses i Pradell','Patronal. Se celebra en Agosto. Festejos tradicionales que unifican las costumbres de los núcleos del término a orillas del río Sió, caracterizados por verbenas de plaza y juegos populares locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25179','fiesta','Festa Major de Sant Esteve de Prullans','Patronal. Se celebra en Agosto. Festejos estivales en el mirador de la Cerdanya potenciados por el turismo familiar rural, con tradicionales pasacalles, comidas populares al aire libre y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25180','fiesta','Festa Major de Sant Roc','Patronal. Se celebra en Agosto *. Celebración de escala estrictamente local en el llano de las Garrigues, vertebrada sobre comidas populares de hermandad vecinal, música tradicional y actividades infantiles). ¿Deseas continuar con el Siguiente Bloque de la provincia de Lleida (Letras de la Q a la Z.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25183','fiesta','Festa Major de la Mare de Déu de Valldeflors y Festival de Música de Rialp','Patronal / Cultural / Festival Musical. Se celebra en Agosto. Festejos de notable peso comarcal en el Pallars Sobirà, potenciados por su prestigioso festival de música que atrae público de toda la provincia, combinándose con verbenas y pasacalles tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25905','fiesta','Festa Major de Sant Antolí','Patronal. Se celebra en Septiembre. Festejos tradicionales que unifican las costumbres vecinales de los numerosos núcleos dispersos de este término de la Segarra, basados en verbenas locales, comidas populares y misas solemnes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25185','fiesta','Festa Major de El Pla de Sant Tirs','Patronal. Se celebra en Agosto. Celebración de carácter veraniego e infantil en el Alt Urgell que congrega a los habitantes de la ribera del Segre en torno a bailes de plaza, comidas de hermandad y competiciones lúdicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25186','fiesta','Aplec del Miracle i Festa Major de Riner','Romería / Etnográfica / Patronal. Se celebra en Agosto y Septiembre. Hito tradicional de gran arraigo en el Solsonès, vertebrado alrededor del majestuoso Santuario del Miracle, atrayendo a numerosos peregrinos por su valor espiritual, sus cantos y sus ferias de artesanía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25189','fiesta','Festa Major de Sant Cugat','Patronal / Cultural. Se celebra en Julio. Festejos locales de carácter familiar con notable dinamismo en el Segrià, caracterizados por pasacalles de gigantes de la comarca, correfocs de diablos locales, torneos de cartas tradicionales y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25190','fiesta','Fira de l''Arbre i de Sant Serni y Festa Major de Salàs','Feria Tradicional / Etnográfica / Patronal. Se celebra en Octubre (Fira) y Noviembre (Patronal). Festejos que destacan provincialmente por la singular puesta en valor de sus históricas tiendas-museo recuperadas y su secular feria agrícola, conformando un hito cultural muy popular en el Pallars Jussà.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25191','fiesta','Festa Major de la Mare de Déu del Pla','Patronal / Histórica. Se celebra en Septiembre. Celebración de la Segarra septentrional a la sombra de su castillo medieval, estructurada en torno a pasacalles populares, bailes de sardanas de plaza, comidas de hermandad y música de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25192','fiesta','Festa Major de Sant Guim y de la Mare de Déu de l''Agustina','Patronal / Cultural. Se celebra en Agosto. Festejos patronales tradicionales del interior de la alta Segarra, caracterizados por el desfile de gigantes de la comarca, competiciones lúdicas locales y animadas sesiones de orquestas en el pabellón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25197','fiesta','Pessebre Vivent de Sant Guim de la Plana','Teatral / Etnográfica / Tradicional. Se celebra en Diciembre y Enero. Gran valor etnográfico provincial por su pesebre viviente especializado en la escenificación masiva de oficios tradicionales extintos, transformando este pequeño núcleo de la Segarra con miles de visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25193','fiesta','Festa Major de Sant Llorenç y del Sant Crist','Patronal / Etnográfica. Se celebra en Agosto. Festejos de gran personalidad en el valle de Lord, célebres por la conservación de sus danzas folclóricas tradicionales y pasacalles por su casco histórico amurallado, atrayendo masiva concurrencia comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25902','fiesta','Festa Major de Sant Martí de Maldà','Patronal. Se celebra en Noviembre. Celebración otoñal de escala estrictamente local en el Valle del Corb, sustentada en ritos religiosos tradicionales, comidas comunitarias de hermandad y bailes de sociedad en el local local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25194','fiesta','Festa Major de Sant Ramon Nonat','Patronal / Romería / Religiosa. Se celebra en Agosto. Gran santuario de rango comarcal y provincial de la Segarra que congrega a miles de peregrinos de toda la provincia por la tradicional bendición de carruajes, caballos y vehículos frente al monasterio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25201','fiesta','Festa Major de Sarroca de Bellera','Patronal. Se celebra en Agosto. Pequeñas fiestas estivales de marcado ambiente familiar adaptadas a los pequeños núcleos dispersos de este término rural en el Pallars Jussà, con comidas vecinales y ritos tradicionales mínimos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25200','fiesta','Festa Major de Sant Joan y de las Santes Creus','Patronal. Se celebra en Agosto. Celebración veraniega de carácter local en el llano de Lleida, basada en el regreso estival de familias, comidas de hermandad al aire libre, orquestas públicas y juegos para niños.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25202','fiesta','Festa Major de Senterada','Patronal. Se celebra en Agosto. Festejos de ámbito puramente local y de carácter familiar en el acceso al valle de Flamisell, condicionados por la baja demografía, con verbenas de plaza y campeonatos de guiñote.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25204','fiesta','Festa Major de la Mare de Déu d''Aitona','Patronal / Cultural. Se celebra en Septiembre. Festejos del Bajo Segre con notable arraigo que combinan pasacalles folclóricos de gigantes locales con correfocs de diablos de la comarca, comidas de hermandad y sesiones de orquesta masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90624','fiesta','Festa Major de Sant Bartomeu','Patronal. Se celebra en Agosto. Celebración trasladada de época para asegurar la concurrencia de la población en el llano del Pla d''Urgell, fundamentada en comidas populares, torneos lúdicos y música de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25207','fiesta','Festa Major de Solsona y el Carnaval de Solsona','Patronal / Carnaval / Etnográfica / Gigantes. Se celebra en Febrero (Carnaval) y Septiembre (Festa Major). Declaradas Fiestas de Interés Turístico por la Generalitat. Hitos etnográficos absolutos de enorme calado regional, célebres por la pureza de sus balls de gegants tradicionales y el singular colgado del burro en carnaval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25208','fiesta','Festa Major de Vilamur','Patronal. Se celebra en Agosto. Pequeña festividad local del Pallars Sobirà que congrega a los habitantes de los caseríos de montaña en torno a una misa solemne tradicional, comidas populares de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25209','fiesta','Festa Major de Sort y de Sant Feliu','Patronal / Cultural / Etnográfica. Se celebra en Agosto. Grandes fiestas mayores de la capital del Pallars Sobirà, famosas por sus tradicionales bailes folclóricos araneses y pirenaicos, competiciones de deportes fluviales, un potente tejido asociativo y conciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25210','fiesta','Festa Major de Sant Llorenç','Patronal. Se celebra en Agosto. Festejos patronales tradicionales del Bajo Segre con amplia participación de peñas juveniles, pasacalles de gigantes de la zona, cantos folclóricos de parrandas y verbenas de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25211','fiesta','Festa Major del Roser','Patronal. Se celebra en Octubre. Celebración de escala estrictamente local en el llano del Segrià, vertebrada sobre comidas vecinales al aire libre, actividades infantiles locales y sesiones de orquesta nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25212','fiesta','Festa Major de la de la Mare de Déu de la Concepció','Patronal. Se celebra en Diciembre. Mínimos festejos de invierno de carácter vecinal debido a la escasa población residente, limitados a actos litúrgicos tradicionales, campeonatos de naipes y un vermut popular comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25215','fiesta','Festa Major de Sant Martí de Talarn','Patronal / Histórica. Se celebra en Agosto *. Festejos veraniegos alrededor de su monumental casco histórico medieval, caracterizados por el regreso estival de familias asociadas al municipio, verbenas de plaza mayor y juegos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27013','fiesta','Fira de Teatre al Carrer de Tàrrega (FiraTàrrega) y Festes de Maig','Cultural / Festival Teatral / Urbana / Etnográfica. Se celebra en Septiembre (FiraTàrrega) y Mayo (Festes). FiraTàrrega posee rango e impacto masivo internacional absoluto, consolidada como uno de los festivales de artes escénicas de calle más importantes de Europa, atrayendo a decenas de miles de personas globales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25219','fiesta','Festa Major de Sant Salvador de Tarroja','Patronal. Se celebra en Agosto. Festejos rurales mínimos en la cuenca del río Sió de la Segarra, basados en ritos religiosos tradicionales en su templo, comidas familiares y pequeñas orquestas lúdicas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25220','fiesta','Festa Major de Sant Joan y del Sant Crist de Térmens','Patronal. Se celebra en Septiembre. Festejos tradicionales de la comarca de la Noguera, caracterizados por pasacalles de gigantes de la zona, competiciones lúdicas locales y bailes populares nocturnos en el ferial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25221','fiesta','Festa Major de Sant Feliu de Tírvia','Patronal. Se celebra en Agosto. Pequeña celebración de verano en el entorno rural y empedrado del Pallars Sobirà, sustentada en ritos religiosos tradicionales, juegos infantiles y comidas vecinales de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25222','fiesta','Festa Major de Sant Pere de Tiurana','Patronal / Cultural. Se celebra en Agosto. Festejos veraniegos que reviven el patrimonio e identidad de este núcleo de la Noguera, con tradicionales pasacalles, comidas populares al aire libre y espectáculos lúdicos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25223','fiesta','Festa del Brut i la Bruta (Carnaval de Torà) i Festa Major de Sant Gil','Etnográfica / Carnaval Tradicional / Patronal. Se celebra en Febrero (Brut i Bruta) y Septiembre (Festa Major). Destaca provincialmente por la singular Fiesta del Brut i la Bruta, joya del carnaval tradicional de la Segarra con desfiles satíricos, gigantes con brazos móviles artesanales y gran arraigo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25228','fiesta','Festa Major de Sant Gregori','Patronal / Cultural. Se celebra en Mayo y Septiembre. Festejos de ámbito metropolitano en las inmediaciones de Lleida capital, con pasacalles de gigantes locales, correfocs de diablos, conciertos públicos y alta participación juvenil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90625','fiesta','Festa Major de Palou, Torrefeta i Florejacs','Patronal / Histórica. Se celebra en Agosto. Festejos que unifican las tradiciones de los pequeños núcleos y castillos señoriales integrados en el término de la Segarra, con verbenas al aire libre y comidas populares de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25230','fiesta','Festa Major de Sant Roc','Patronal / Etnográfica. Se celebra en Agosto. Celebración del Pla d''Urgell con tradicionales pasacalles, pasacalles pirotécnicos de diablos de la zona, bailes de sardanas de plaza y una activa participación de peñas juveniles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25231','fiesta','Festa Major del Sant Crist de Torrelameu','Patronal. Se celebra en Septiembre. Festejos tradicionales junto a la Noguera Ribagorçana, caracterizados por pasacalles musicales locales, campeonatos de guiñote y comidas comunitarias de hermandad al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25232','fiesta','Festa Major de Santa Quitèria','Patronal / Cultural. Se celebra en Mayo. Festejos de rango comarcal tradicionales en el Bajo Segre, caracterizados por el desfile de gigantes de la comarca, encuentros de música de parrandas canarias tradicionales locales y orquestas masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25233','fiesta','Festa Major de Sant Miquel','Patronal. Se celebra en Septiembre. Festejos locales de carácter familiar en el Segrià septentrional, basados en juegos infantiles tradicionales aragoneses, misas tradicionales solemnes y sesiones lúdicas de baile públicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25234','fiesta','Festa Major de la Mare de Déu de Valldeflors d''Estiu y de Sant Bonifaci','Patronal / Etnográfica / Cultural. Se celebra en Mayo y Septiembre. Grandes fiestas mayores de la capital del Pallars Jussà, muy populares por sus desfiles de la histórica colla de gigantes tradicionales locales, activos correfocs, conciertos y ferias comerciales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25901','fiesta','Festa Major de Ribera de Cardós','Patronal. Se celebra en Septiembre. Festejos rurales tradicionales del valle pirenaico, orientados a la convivencia comunitaria de los núcleos, con ritos religiosos tradicionales mínimos y música de acordeón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27014','fiesta','Festa Major de Vielha y de la Mare de Déu de Mijaran','Patronal / Etnográfica / Romería. Se celebra en Septiembre. Grandes fiestas mayores de la capital aranesa de rango e impacto regional en los Pirineos, célebres por la espectacular pureza y ejecución de las danzas folclóricas aranesas con trajes de gala y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25244','fiesta','Fira de l''Ametlla de Vilagrassa y Festa Major de San Jaume','Gastronómica / Feria Tradicional / Patronal. Se celebra en Septiembre (Fira) y Julio (Patronal). Festejos con notable raigambre en el Urgell; su fira dedicada a la almendra destaca provincialmente por sus concursos de recolectores artesanales y muestras gastronómicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25245','fiesta','Festa de Sant Joan i Baixada de Falles de Vilaller','Etnográfica / Antorchas / Patrimonio Humanidad. Se celebra en Junio (Noche de San Juan). Declarada Patrimonio Cultural Inmaterial de la Humanidad por la UNESCO. Hito tradicional de primer nivel en la Alta Ribagorça, famoso por la espectacular bajada nocturna de troncos encendidos desde la montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25247','fiesta','Festa Major de Sant Roc de Vilamòs','Patronal / Etnográfica. Se celebra en Agosto. Pese a su baja demografía, sus fiestas en el pueblo más antiguo de la Val d''Aran mantienen viva la identidad local mediante danzas folclóricas aranesas tradicionales y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25254','fiesta','Festa Major de la de la Mare de Déu de Montserrat','Patronal. Se celebra en Agosto. Festejos veraniegos junto al río Segre basados en el reencuentro familiar, comidas de hermandad, tradicionales misas cántabras y verbenas lúdicas familiares en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25249','fiesta','Festa Major de Vilanova, Ribelles i Valldans','Patronal. Se celebra en Agosto. Pequeña celebración de marcado carácter vecinal unificada entre sus núcleos residenciales de la Noguera oriental, con un programa lúdico básico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25250','fiesta','Fira de la de la Perdiu de Vilanova de Meià i Festa Major de Sant Salvador','Feria Tradicional / Etnográfica / Gastronómica. Se celebra en Septiembre (Festa Major) y Noviembre (Fira). Su histórica feria tradicional dedicada a la cría de la perdiz y aves es un hito de origen medieval de enorme arraigo y fama a nivel provincial, congregando a miles de visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25251','fiesta','Festa Major de Sant Sebastià y de la Mare de Déu de la Villa','Patronal. Se celebra en Agosto *. Festejos tradicionales de carácter local en la comarca del Segrià meridional, basados en verbenas de plaza, campeonatos de guiñote y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25252','fiesta','Festa Major de Sant Miquel','Patronal. Se celebra en Septiembre. Festejos tradicionales del llano al lado del estanque de Ivars y Vila-sana con procesión tradicional a la ermita, campeonatos de cartas y orquestas locales nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25255','fiesta','Fira de l''Oli i de la Pedra de Vinaixa y Festa Major de Sant Joan','Gastronómica / Feria Tradicional / Patronal. Se celebra en Marzo (Fira) y Agosto (Festa Major). Festejos tradicionales de las Garrigues que promueven sus industrias seculares de la piedra y el aceite con DOP mediante ferias artesanales de primer nivel regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90062','fiesta','Festa Major de Santes Creus i d''Aiguamúrcia','Patronal / Histórica. Se celebra en Agosto. Festejos de ámbito local en la comarca del Alt Camp que aprovechan el imponente entorno monumental del Real Monasterio de Santes Creus para organizar conciertos, sardanas y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90904','fiesta','Festa Major de Sant Bartomeu i del Bon Viatge','Patronal / Romería. Se celebra en Agosto. Celebración tradicional del Baix Penedès, caracterizada por la procesión a la ermita de San Antonio, pasacalles con elementos de fuego locales y bailes populares para el vecindario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90905','fiesta','Festa Major de Sant Miquel','Patronal. Se celebra en Septiembre. Pequeños festejos de marcado acento vecinal y baja demografía en el Baix Camp, sustentados en ritos religiosos tradicionales, comidas de hermandad y música en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90047','fiesta','Festes Quinquennals d''Alcanar i Festa Major de Sant Miquel','Patronal / Etnográfica / Quinquenal. Se celebra en Octubre (Quinquennales, cada 5 años) y Septiembre (Anual). Declaradas Fiesta de Interés Turístico Nacional por la Generalitat. Hito etnográfico masivo donde el pueblo entero confecciona espectaculares alfombras de serrín teñido y flores secas a lo largo de kilómetros de calles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90731','fiesta','Fira de Bandolers d''Alcover y Festa Major de la Mare de Déu del Remei','Recreación Histórica / Feria Tradicional / Patronal. Se celebra en Octubre. Gran valor etnográfico a nivel provincial; su feria de bandoleros moviliza a la población vistiendo de época del siglo XVII para escenificar las disputas entre robadors y muts con trabucos y mercados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90906','fiesta','Festa Major de Sant Jordi','Patronal. Se celebra en Abril y Septiembre. Festejos tradicionales a orillas del río Ebro en la comarca del Baix Ebre, consistentes en pasacalles musicales, comidas de hermandad y verbenas lúdicas en el polideportivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43904','fiesta','Festa Major de la Mare de Déu de l''Aldea','Patronal / Romería / Taurina. Se celebra en Septiembre. Festejos con notable raigambre en el Delta del Ebro que combinan la romería tradicional a la ermita con los típicos festejos taurinos de bous capllaçats y bous embolats de gran arraigo local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90907','fiesta','Festa Major de Sant Agustí','Patronal / Taurina. Se celebra en Agosto. Festejos de montaña en el Parque Natural dels Ports, marcados por la suelta de vaquillas tradicionales en plaza portátil, comidas de cazadores y bailes populares nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90908','fiesta','Festa Major de Sant Miquel i del Ball de Diables d''Alforja','Patronal / Etnográfica. Se celebra en Septiembre. Celebración del Baix Camp con tradicionales pasacalles que destacan por la fuerza de su Ball de Diables histórico y sus correfocs, sumando bailes de sardanas y cenas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90909','fiesta','Festa Major de Sant Bartomeu','Patronal. Se celebra en Agosto. Celebración puramente vecinal en el Alt Camp, sustentada en ritos litúrgicos tradicionales, juegos infantiles veraniegos y verbenas lúdicas reducidas para los habitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90910','fiesta','Festa Major de Sant Miquel','Patronal. Se celebra en Julio y Septiembre. Festejos patronales tradicionales marcados por el regreso estival de familias, caracterizados por comidas populares, torneos de cartas tradicionales y música en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90048','fiesta','Festa Major de Sant Martí y Festes de la Mare de Déu de la Guia','Patronal / Castellera / Costera. Se celebra en Noviembre (Sant Martí) y Septiembre (Guia). Festejos de rango comarcal muy populares en el Tarragonès, célebres por las actuaciones de los Castellers d''Altafulla, correfocs de diablos por su villa medieval y habaneras junto al mar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90049','fiesta','Festes de la Candelera y Festa de la de la Diada del Atún','Patronal / Marinera / Gastronómica. Se celebra en Febrero (Candelera) y Mayo (Atún). Festejos costeros de gran peso comarcal en el Baix Ebre, famosos por la procesión marinera de la Candelera, la multitudinaria degustación de atún rojo del Mediterráneo y verbenas masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43906','fiesta','Festa Major de San Joan i de la de la Fira de l''Ostra','Patronal / Marinera / Gastronómica. Se celebra en Junio (San Joan) y Mayo (Ostra). Grandes festejos de verano en la entrada del Delta del Ebro, destacados por su feria gastronómica de la ostra que atrae a numeroso público, combinada con encierros de vaquillas y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43014','fiesta','Festa Major d''Amposta i Festa del Mercat a la Plaça','Patronal / Recreación Histórica / Taurina. Se celebra en Mayo (Mercat) y Agosto (Festa Major). Su Fiesta del Mercado en la Plaza está declarada de gran relevancia etnográfica autonómica, recreando masivamente la vida del Delta de principios del siglo XX con trajes de época y música tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43015','fiesta','Festa Major de Sant Pau','Patronal. Se celebra en Enero y Octubre. Festejos rurales mínimos condicionados por la baja demografía en las montañas de Prades, centrados en comidas familiares tradicionales y ritos religiosos en su iglesia histórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43018','fiesta','Festa de la de la Mel d''Arnes y Festa Major de Santa Magdalena','Gastronómica / Feria Tradicional / Patronal. Se celebra en Junio (Mel) y Julio (Festa Major). Festejos tradicionales de la Terra Alta orientados a la promoción artesanal de su miel local de montaña, sumando pasacalles, jotas tradicionales y comidas vecinales de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43019','fiesta','Festa de Sant Antoni d''Ascó','Patronal / Etnográfica / Tradicional. Se celebra en Enero. Declarada Fiesta de Interés Turístico por la Generalitat. Hito etnográfico de la Ribera d''Ebre caracterizado por encender monumentales hogueras, la tradicional Festa de la Clotxa y las históricas carreras de caballos de origen medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90911','fiesta','Festa Major de Santa Eulàlia y el Ball de Gitanes de Banyeres','Patronal / Etnográfica. Se celebra en Julio. Festejos del Baix Penedès que destacan por la conservación y espectacular ejecución de su tradicional Ball de Gitanes, un elemento folclórico histórico recuperado por el vecindario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90912','fiesta','Festa Major del Roser y Festa del Vi Novell','Patronal / Enológica. Se celebra en Mayo (Roser) y Noviembre (Vi Novell). Festejos tradicionales de la Conca de Barberà vinculados históricamente a su histórica cooperativa modernista, caracterizados por el descorche del vino nuevo y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43022','fiesta','Festa Major de Sant Miquel','Patronal / Enológica. Se celebra en Agosto. Celebración con gran arraigo en la Terra Alta, caracterizada por un amplio programa que incluye pasacalles de gigantes, jotas tradicionales de la comarca y degustación de vinos de la DO Terra Alta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43023','fiesta','Festa Major de Santa Llúcia','Patronal / Histórica. Se celebra en Diciembre. Festejos invernales marcados por el pasado minero del término, con tradicionales misas solemnes, comidas populares de hermandad en el local social y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90913','fiesta','Festa Major de Sant Jaume *','Patronal *. Se celebra en Julio *. Celebración local en el Baix Penedès orientada al regreso de familias veraneantes, estructurada con actividades infantiles tradicionales, comidas colectivas y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43025','fiesta','Festa Major de la Mare de Déu de Dalt','Patronal / Romería / Etnográfica. Se celebra en Septiembre. Festejos junto al río Ebro que incluyen la concurrida procesión a la ermita románica de la cumbre, aunando fervor local, jotas y pasacalles con gigantes de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43026','fiesta','Festa Major de Sant Jaume y Festa de la de la Fruita Dolça','Patronal / Gastronómica. Se celebra en Julio. Festejos tradicionales de la Ribera d''Ebre que promueven sus cultivos frutales históricos mediante la muestra del melocotón local, sumando comidas populares y orquestas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90914','fiesta','Festa Major de la de la Nativitat de la Mare de Déu','Patronal / Gastronómica. Se celebra en Septiembre. Festejos de escala estrictamente local en el Priorat, basados en comidas populares dedicadas al aceite de oliva virgen extra de la zona y ritos religiosos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43028','fiesta','Festa Major de Santa Maria (Diada Castellera de la Bisbal)','Patronal / Castellera / Etnográfica. Se celebra en Agosto. Hito castellero de enorme renombre provincial; su histórica diada del 15 de agosto reúne de forma masiva a las mejores colles de Cataluña en su mítica calle Mayor sin plaza propiamente dicha.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43029','fiesta','Festa Major de San Roc','Patronal. Se celebra en Agosto. Pequeña celebración veraniega de marcado carácter vecinal adaptada a la baja demografía de la Conca de Barberà, limitada a misas solemnes tradicionales y cenas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43030','fiesta','Festa Major de Santa Magdalena','Patronal. Se celebra en Julio. Celebración local de carácter tradicional y familiar en el Baix Penedès, con tradicionales pasacalles, campeonatos de guiñote y música lúdica nocturna en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43032','fiesta','Festa Major de Sant Blai y de San Llorenç','Patronal / Enológica. Se celebra en Febrero y Agosto. Festejos de arraigo tradicional en la Terra Alta vinculados a la recogida de la uva, caracterizados por el encendido de hogueras invernales, jotas de la comarca y catas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43033','fiesta','Festa Major de Sant Llorenç','Patronal. Se celebra en Agosto. Festejos de carácter local en el Baix Camp orientados a las actividades familiares de verano, con comidas comunitarias de hermandad, juegos infantiles y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43034','fiesta','Festa Major de Sant Jaume y Aplec de Loreto','Patronal / Romería. Se celebra en Julio y Septiembre. Festejos tradicionales del Alt Camp que reúnen a los vecinos en la romería tradicional a la ermita de Loreto, combinando fervor rural, sardanas y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43035','fiesta','Festa Major de la de la Mare de Déu de les Neus','Patronal / Gastronómica. Se celebra en Agosto. Festejos locales en el Priorat septentrional orientados al regreso de veraneantes estivales, con degustaciones de aceite local de cooperativa y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43036','fiesta','Festa Major del Sant Crist y de la Santa Creu','Patronal. Se celebra en Mayo y Septiembre. Celebración de escala estrictamente local en el Alt Camp, vertebrada sobre misas solemnes tradicionales, actividades infantiles y sesiones de orquesta nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43037','fiesta','Festa Major de la Santa Creu i de Sant Pere (Festes del Mar)','Patronal / Costera / Cultural. Se celebra en Junio y Julio. Festejos costeros de gran peso comarcal en el Baix Penedès, célebres por los pasacalles marineros junto a su castillo medieval, cantadas de habaneras en la arena y conciertos multitudinarios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43038','fiesta','Festes de la Mare de Déu del Camí y Festa Major de Sant Pere','Patronal / Marinera / Cultural / Castellera. Se celebra en Junio (Sant Pere) y Septiembre (Mare de Déu). Festejos de rango e impacto comarcal masivo en el Baix Camp, caracterizados por la espectacular procesión marítima, regatas de llaguts tradicionales, castellers y macroconciertos públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43039','fiesta','Festa Major de la de la Mare de Déu de Barrulles','Patronal / Romería. Se celebra en Agosto. Pequeñas fiestas estivales de marcado ambiente familiar adaptadas a los pequeños núcleos de las montañas de Prades, con romería a la ermita y comidas vecinales tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43040','fiesta','Festa Major de Sant Abdó i Sant Senén','Patronal / Enológica. Se celebra en Julio. Festejos tradicionales del Priorat meridional vinculados a su célebre producción vitivinícola, con pasacalles populares, catas de vinos locales y verbenas lúdicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43041','fiesta','Festa Major de Santa Magdalena','Patronal. Se celebra en Julio. Pequeños festejos tradicionales de verano en la frontera con Aragón, basados en ritos litúrgicos tradicionales, jotas de la Terra Alta y comidas vecinales compartidas al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43042','fiesta','Festa Major de Santa Anna i de San Joaquim','Patronal. Se celebra en Julio. Festejos de carácter local muy vinculados a la cercanía con Reus, estructurados con pasacalles infantiles, comidas populares de hermandad y sesiones de baile públicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43043','fiesta','Festa Major de San Feliu (Diada Castellera del Catllar)','Patronal / Castellera / Cultural. Se celebra en Agosto. Hito tradicional de gran relevancia provincial en el Tarragonès; su diada castellera veraniega al pie del castillo medieval reúne de forma masiva a agrupaciones de primer orden autonómico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43045','fiesta','Festa Major de Sant Llorenç','Patronal. Se celebra en Agosto. Festejos rurales de ámbito estrictamente local a las faldas de la Mola de Colldejou, centrados en la santa misa tradicional, comidas de hermandad y verbenas lúdicas reducidas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43046','fiesta','Festa Major de San Pere y Mercat Vell de Conesa','Patronal / Recreación Histórica. Se celebra en Julio (Mercat Vell) y Agosto (Festa Major). Festejos de la Conca de Barberà que reviven el patrimonio de su magnífico núcleo amurallado protegido mediante ferias de antiguos oficios artesanales y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43047','fiesta','Festa Major de Sant Feliu y de San Sebastià','Patronal / Cultural. Se celebra en Enero y Agosto. Festejos patronales tradicionales del Tarragonès, caracterizados por el desfile de gigantes comarcales, correfocs con agrupaciones de diablos de la zona y orquestas populares en el pabellón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43048','fiesta','Festa Major de la de la Mare de Déu del Poble Vell','Patronal / Histórica. Se celebra en Agosto. Festejos de hondo valor identitario en la Terra Alta que aprovechan el marco patrimonial y conmemorativo de las ruinas del Poble Vell de la Batalla del Ebro para albergar actos culturales y folclore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43049','fiesta','Festa Major de Santa Maria y Festes de Sant Joan de Siurana','Patronal / Etnográfica. Se celebra en Agosto. Festejos de gran sabor tradicional en el Priorat que unifican el término bajo la emblemática estampa de la Sierra de Montsant y el núcleo medieval de Siurana, destacando la ronda de jotas, catas de vino con D.O. y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43050','fiesta','Festa Major de Sant Jaume','Patronal / Costera. Se celebra en Julio. Festejos de rango costero en el Tarragonès potenciados por la alta población flotante estival, caracterizados por pasacalles folclóricos de gigantes locales, correfocs y conciertos al aire libre junto al núcleo histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43051','fiesta','Festa Major de Cunit (Sant Cristòfol) i Festa Major de Sant Sebastià','Patronal / Costera / Cultural. Se celebra en Enero y Julio. Festejos de arraigo comarcal en el Baix Penedès con amplio presupuesto y afluencia, dotados de populosos pasacalles con bailes populares, espectáculos pirotécnicos de fuego y un potente programa de orquestas en la zona marítima.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43901','fiesta','Festes Majors de Deltebre','Patronal / Taurina / Etnográfica. Se celebra en Agosto. Festejos de gran raigambre en el Baix Ebre, célebres por sus tradicionales e históricos espectáculos taurinos como el "bou capllaçat" y "bou embolat", combinados con la exaltación de la cultura del cultivo del arroz del Delta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90915','fiesta','Festa Major de la Mare de Déu del Voltor','Patronal. Se celebra en Octubre. Festejos de otoño de marcado carácter vecinal y familiar en el Baix Camp, articulados en torno a la santa misa tradicional en su iglesia parroquial, campeonatos de guiñote y comidas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43055','fiesta','Festes de Sant Antoni (Encamisada de Falset) i Festa Major de Santa Càndia','Etnográfica / Tradicional / Enológica. Se celebra en Enero (Encamisada) y Agosto (Festa Major). Declarada Fiesta de Interés Turístico por la Generalitat de Catalunya. Hito etnográfico monumental donde los vecinos visten trajes tradicionales y recorren la capital del Priorat montados en caballerías engalanadas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43056','fiesta','Festa Major de Sant Blai y de la Mare de Déu de la Misericòrdia','Patronal / Etnográfica. Se celebra en Febrero (Sant Blai) y Agosto (Misericòrdia). Festejos del Terra Alta de gran valor identitario por la conservación de la tradicional "Festa de la llonganissa" de San Blas, con el reparto de panes bendecidos y el "Ball de Tres de la Fatarella" en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43057','fiesta','Festa Major de Sant Esteve','Patronal. Se celebra en Agosto. Mínima expresión festiva de carácter estrictamente familiar en el Baix Camp debido a la extrema baja demografía del núcleo, limitada a ritos religiosos tradicionales y un vermut popular vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43058','fiesta','Festa Major de Sant Martí','Patronal. Se celebra en Noviembre. Pequeña celebración vecinal con un programa lúdico y religioso mínimo adaptado a la escasa población de este núcleo del Priorat, basado en comidas de hermandad y música local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43059','fiesta','Festa Major de Sant Jaume y Aplec de la Mare de Déu de Fontscaldes','Patronal / Romería. Se celebra en Julio. Festejos tradicionales de la comarca del Alt Camp marcados por el reencuentro veraniego de familias, con misas solemnes tradicionales, bailes de sardanas de plaza y orquestas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43060','fiesta','Festa Major de la Mare de Déu de l''Assumpció','Patronal / Cultural / Acuática. Se celebra en Agosto. Festejos de notable peso comarcal en la Ribera d''Ebre, caracterizados por las singulares y tradicionales carreras de barcas fluviales por el río Ebro, desfiles de su activa colla de gigantes y potentes correfocs.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43061','fiesta','Festa Major de Sant Miquel y Festival Forès Poesia i Música','Patronal / Cultural. Se celebra en Agosto. Festejos veraniegos que dinamizan el mirador de la Conca de Barberà mediante un cuidado certamen cultural que complementa las misas tradicionales y las cenas populares al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43062','fiesta','Festa Major de Sant Bartomeu','Patronal / Taurina. Se celebra en Agosto. Celebración de escala local en el Montsià con tradicionales pasacalles, suelta de vaquillas populares en la plaza del ayuntamiento y comidas comunitarias de hermandad para el vecindario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43063','fiesta','Fira del Terrissaire de la Galera y Festa Major de Sant Llorenç','Feria Tradicional / Etnográfica / Patronal. Se celebra en Mayo (Fira) y Agosto (Festa Major). Su histórica feria de la alfarería posee un gran arraigo y fama a nivel provincial en el Montsià, conmemorando el pasado artesanal del barro con demostraciones técnicas en directo y mercados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43064','fiesta','Festa de la de la Verema de Gandesa i Festes Majors de la Mare de Déu de la Fontcalda','Enológica / Gastronómica / Patronal. Se celebra en Septiembre. Declarada Fiesta de Interés Turístico por la Generalitat. Gran hito enológico de la capital de la Terra Alta que promociona masivamente los vinos artesanales de la D.O. con degustaciones y la "Festa del Vi".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43065','fiesta','Festa Major de la de la Mare de Déu dels Àngels','Patronal. Se celebra en Agosto. Festejos tradicionales de carácter familiar e infantil en la Ribera d''Ebre, consistentes en pasacalles musicales locales, campeonatos de cartas tradicionales aragoneses y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43067','fiesta','Festa Major de Sant Martí','Patronal / Etnográfica. Se celebra en Noviembre. Celebración tradicional a orillas del Ebro con procesión solemne tradicional, pasacalles de su colla de gigantes y cabezudos y una activa participación vecinal en las verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43068','fiesta','Carnaval de Godall y Festa Major del Salvador','Etnográfica / Carnaval Tradicional / Patronal. Se celebra en Febrero (Carnaval) y Agosto (Festa Major). Destaca provincialmente por su Carnaval tradicional en el Montsià, hito etnográfico famoso por la masiva "guerra de la harina" entre los vecinos y los bailes de máscaras tradicionales locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43069','fiesta','Festa Major de Sant Llorenç','Patronal / Enológica. Se celebra en Agosto. Festejos tradicionales veraniegos vinculados a la cultura vitivinícola de la prestigiosa D.O.Q. Priorat, caracterizados por comidas populares de hermandad al aire libre y catas de vino locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43071','fiesta','Festa Major de San Salvador y la Virgen de la Costa','Patronal / Etnográfica / Taurina. Se celebra en Septiembre. Festejos de rango comarcal en la Terra Alta que combinan los pasacalles populares y las jotas con tradicionales espectáculos de vaquillas populares en su monumental y protegida plaza porticada). Hemos completado el Bloque 2 de la provincia de Tarragona, abarcando de forma exhaustiva todos los municipios hasta la letra I de forma rigurosa y sin omitir ningún dato patrimonial. ¿Deseas continuar con el Bloque 3 de la provincia de Tarragona (Municipios de la J a la P)?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43072','fiesta','Festa Major de Sant Miquel','Patronal / Enológica. Se celebra en Septiembre. Festejos patronales y de vendimia en el Priorat, caracterizados por ritos litúrgicos tradicionales, catas de vinos locales y verbenas lúdicas familiares en la plaza del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43073','fiesta','Festa Major de Sant Joan y del Roser','Patronal. Se celebra en Agosto. Pequeña celebración veraniega de marcado carácter vecinal en la Conca de Barberà, sustentada en el reencuentro de familias vinculadas al pueblo, juegos infantiles y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90916','fiesta','Festa Major de Sant Llorenç','Patronal / Etnográfica / Castellera. Se celebra en Agosto. Destaca provincialmente en el Baix Penedès por su histórica diada castellera de alta raigambre, acompañada de la ejecución de bailes populares tradicionales, gigantes y potentes correfocs.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90917','fiesta','Festa Major de la Mare de Déu de l''Assumpció','Patronal / Enológica. Se celebra en Agosto. Festejos tradicionales de la comarca del Priorat potenciados por la población veraniega, articulados sobre verbenas lúdicas al aire libre, catas populares de vino artesanal y pasacalles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90918','fiesta','Festa Major de Sant Miquel Arcàngel','Patronal / Etnográfica. Se celebra en Septiembre. Festejos locales marcados por el turismo activo de montaña en el Parque Natural de Montsant, con tradicionales misas solemnes, comidas populares de hermandad y música de orquesta regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43077','fiesta','Festa Major de Sant Marc y Fira de les Fibres Vegetals','Feria Tradicional / Etnográfica / Patronal. Se celebra en Abril (Sant Marc) y Agosto (Fira). Su feria internacional del trabajo artesanal de las fibras vegetales posee un gran arraigo e impacto provincial en el Montsià, atrayendo a numeroso público por sus demostraciones de cestería tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43078','fiesta','Festa Major de la Mare de Déu del Roser','Patronal / Taurina. Se celebra en Agosto. Festejos de fuerte arraigo local en el Montsià, caracterizados por los tradicionales encierros y espectáculos de vaquillas populares en plaza portátil, bailes de jotas locales y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43079','fiesta','Festa Major de Sant Ramon de Penyafort','Patronal. Se celebra en Agosto. Celebración trasladada de época para asegurar la concurrencia de la población residencial en el Baix Penedès, basada en torneos lúdicos tradicionales, pasacalles infantiles y sesiones de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43080','fiesta','Festa Major de Santa Magdalena','Patronal. Se celebra en Julio. Celebración de escala estrictamente local en la comarca del Alt Camp, vertebrada sobre comidas vecinales al aire libre, ritos litúrgicos tradicionales, música y actividades lúdicas infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43081','fiesta','Festa Major de Sant Roc','Patronal / Etnográfica. Se celebra en Agosto. Festejos veraniegos de carácter local en el Baix Camp, consistentes en pasacalles musicales con gigantes comarcales, espectáculos pirotécnicos de diablos de la zona y cenas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43083','fiesta','Festa Major de Sant Isidre y de Santa Úrsula','Patronal. Se celebra en Mayo y Octubre. Mínimos festejos rurales de carácter vecinal en el Alt Camp debido a la baja demografía, limitados a la santa misa tradicional en su iglesia histórica y comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43084','fiesta','Festa Major de Sant Donat i Sant Salvador y Fira de Terrissa','Patronal / Feria Tradicional / Etnográfica. Se celebra en Agosto (Festa Major) y Octubre (Fira). Su histórica feria de la alfarería posee un gran arraigo y fama a nivel provincial, transformando la Ribera d''Ebre a la sombra de su castillo templario con demostraciones de alfares tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43095','fiesta','Festa Major de Sant Abdó i Sant Senén (Festes del Graner)','Patronal / Cultural / Etnográfica. Se celebra en Julio. Festejos de rango comarcal consolidados con un potente programa lúdico en el Tarragonès, con la tradicional "Zeuzera" (bestia de fuego), correfocs masivos, castellers y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43096','fiesta','Festa Major de la Nativitat de la Mare de Déu','Patronal / Romería. Se celebra en Septiembre. Festejos de montaña en el Priorat que incluyen la romería tradicional a la Cartuja de Escaladei, combinando fervor rural, catas de vinos con D.O.Q. y música tradicional de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43097','fiesta','Festa Major de la Mare de Déu de les Neus','Patronal. Se celebra en Agosto. Celebración puramente vecinal en la cuenca del Gaià, sustentada en ritos religiosos tradicionales, pasacalles de gigantes de la comarca, juegos infantiles y cenas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43098','fiesta','Festa Major de Sant Joan y del Vint-iquatre','Patronal / Enológica. Se celebra en Agosto y Noviembre. Festejos locales en el Alt Camp vinculados a la cooperativa modernista de vino y cava, con tradicionales misas solemnes, comidas populares al aire libre y verbenas de plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90919','fiesta','Festa Major de Passanant, Belltall y Glorieta','Patronal / Gastronómica. Se celebra en Agosto. Festejos que unifican las tradiciones de los núcleos del término en la Conca de Barberà, destacando la tradicional muestra gastronómica del ajo de Belltall y cenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43102','fiesta','Festa Major de Sant Roc','Patronal / Romería / Taurina. Se celebra en Agosto. Festejos de gran sabor tradicional en el Baix Ebre que incluyen la concurrida romería a la ermita de San Roque, vaquillas populares por el casco urbano y bailes de jotas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43103','fiesta','Festa Major de Sant Pere y de San Sebastián','Patronal. Se celebra en Enero y Junio. Festejos de carácter familiar en el Tarragonès septentrional, consistentes en pasacalles de gigantes de la comarca, campeonatos de cartas tradicionales, comidas populares y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43104','fiesta','Fira de Sant Antoni (Fira de la Mel) i Festa Major de Sant Antoni Abat','Feria de Sector / Gastronómica / Patronal. Se celebra en Enero (Fira) y Agosto (Festa Major). Su fira multisectorial dedicada a la apicultura y el aceite de oliva posee un notable arraigo provincial en el Baix Ebre, atrayendo a numeroso público gastronómico y mercados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43106','fiesta','Festa Major de Sant Llorenç','Patronal / Etnográfica / Enológica. Se celebra en Agosto. Celebración de la Terra Alta de gran valor identitario vinculada al marco arquitectónico de su "Catedral del Vi" modernista, con jotas tradicionales locales, pasacalles de gigantes y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43107','fiesta','Festa Major del Salvador','Patronal / Enológica. Se celebra en Agosto *. Festejos tradicionales de la cuenca vitivinícola a orillas del río Anguera, caracterizados por pasacalles de la cooperativa local, catas de vino y verbenas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43109','fiesta','Festa Major de Sant Joan y de la Mare de Déu del Lledó','Patronal / Cultural. Se celebra en Junio y Diciembre. Festejos en el Tarragonès que unifican un amplio presupuesto industrial con pasacalles tradicionales de gigantes locales, activos correfocs, conciertos masivos y comidas colectivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43111','fiesta','Festa Major de Santa Maria y Pessebre Vivent de la Pobla de Montornès','Patronal / Teatral / Etnográfica. Se celebra en Septiembre (Festa Major) y Diciembre/Enero (Pessebre). Festejos de notable peso comarcal, destacados por la gran afluencia provincial hacia su pesebre viviente histórico que escenifica de forma tradicional antiguos oficios artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43110','fiesta','Festa Major de Sant Antoni y San Roque','Patronal / Enológica. Se celebra en Enero y Agosto. Festejos locales tradicionales de la Terra Alta junto al embalse de Ribarroja, basados en el cultivo del vino de la DO, con tradicionales misas solemnes, comidas de hermandad y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43112','fiesta','Festa Major de Sant Pere y Festa del Vi de Poboleda','Patronal / Enológica / Gastronómica. Se celebra en Agosto y Septiembre. Su fira y fiesta del vino dedicada a la vendimia antigua a la prensa tradicional posee un notable arraigo provincial en el Priorat, atrayendo a numeroso público gourmet y catas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90920','fiesta','Festa Major de Santa Magdalena','Patronal. Se celebra en Julio. Festejos de escala estrictamente local en el valle alto del Gaià, vertebrados sobre comidas populares de hermandad vecinal, ritos litúrgicos tradicionales, pasacalles y música de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43141','fiesta','Festa Major de Pontils, Viladeperdius y Biure','Patronal. Se celebra en Agosto. Festejos rurales mínimos distribuidos entre los caseríos y pequeños núcleos dispersos de la alta Conca de Barberà, centrados en comidas familiares y ritos religiosos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43114','fiesta','Festa Major de Sant Joan Evangelista y Trobada de Músics de Porrera','Patronal / Enológica / Cultural. Se celebra en Noviembre. Festejos tradicionales de gran arraigo identitario en el corazón del Priorat, célebres por su alta tradición literaria, musical, catas artesanales de vinos con D.O.Q. y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43115','fiesta','Festa Major de Sant Bartomeu','Patronal. Se celebra en Agosto. Festejos veraniegos que dinamizan el acceso al Priorat, caracterizados por el regreso estival de familias vinculadas al pueblo, comidas populares al aire libre y música de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43116','fiesta','Festa de la de la Cava de Prades (Festa del Cava de la Font) y Festa Major de Santa Maria','Gastronómica / Enológica / Patronal / Etnográfica. Se celebra en Julio (Festa del Cava) y Septiembre (Festa Major). Hito enológico y festivo de gran renombre provincial desarrollado en la "Vila Vermella" del Baix Camp, célebre porque de su histórica fuente renacentista mana cava artesanal durante toda la noche.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43117','fiesta','Festa de l''Aiguardent de Prat de Comte i Festa Major de Sant Bartomeu','Etnográfica / Destilación Tradicional / Patronal. Se celebra en Agosto (Festa Major) y Octubre (Aiguardent). De enorme relevancia etnográfica provincial por su Fiesta del Aguardiente, hito tradicional que abre los portales de la Terra Alta para destilar de forma artesanal en alambiques históricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43118','fiesta','Festa Major de Santa Marina','Patronal / Romería / Etnográfica. Se celebra en Julio. Concurrida festividad tradicional en la Sierra de Llaberia, que atrae a peregrinos de la comarca del Baix Camp hacia el santuario de la virgen entre leyendas de los mitológicos perros vampiro ("dips").','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43119','fiesta','Festa Major de la Mare de Déu de l''Hospital','Patronal. Se celebra en Agosto. Celebración de carácter tradicional y vecinal en el Alt Camp, estructurada en torno a ritos religiosos tradicionales, comidas populares de hermandad, gigantes y música de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43120','fiesta','Festa Major de Querol, Esblada y Valldosera','Patronal / Histórica. Se celebra en Agosto. Pequeñas fiestas estivales con núcleos residenciales dispersos en las montañas del Alt Camp, basadas en el regreso estival, tradicionales misas y cenas comunitarias al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43121','fiesta','Fira Ramadera de Rasquera y Festa Major de Sant Domènec','Feria Ganadera Tradicional / Etnográfica / Patronal. Se celebra en Mayo (Fira) y Agosto (Festa Major). Su fira ganadera tradicional dedicada a la cabra blanca de Rasquera posee rango comarcal y provincial de alta popularidad, siendo de las pocas ferias de pastores vivas en las Terres de l''Ebre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43122','fiesta','Festa Major de la de la Mare de Déu de Loreto','Patronal / Romería. Se celebra en Septiembre. Mínimos festejos de carácter vecinal debido a la escasa población residente en el Tarragonès interior, limitados a la romería al santuario tradicional de la comarca y un vermut popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43123','fiesta','Festes de Sant Pere de Reus (Festa Major) i Festes de la Mare de Déu de la Misericòrdia','Patronal / Etnográfica / Cultural / Fuego. Se celebra en Junio (Sant Pere) y Septiembre (Misericòrdia). Declarada Fiesta de Interés Turístico Nacional. Colosal hito etnográfico masivo global célebre por la impresionante "Tronada de Reus", desfiles monumentales de gigantes históricos, mulasses y balls populars solemnes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43124','fiesta','Festa Major de Sant Bartomeu y Festa del Riu','Patronal / Cultural / Acuática. Se celebra en Agosto. Festejos de fuerte arraigo en el extremo de la Ribera d''Ebre con competiciones tradicionales de remo en el río Ebro, desfiles tradicionales de peñas juveniles y sesiones de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43126','fiesta','Festa Major de Santa Margarida y el Ball de Diables de la Riera','Patronal / Etnográfica. Se celebra en Julio. Festejos de arraigo local tradicionales en la comarca del Tarragonès, caracterizados por los pasacalles populares, el tradicional y activo ball de diables con fuego local y las verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43131','fiesta','Festa Major de Sant Bartomeu i de Sant Salvador','Patronal / Costera / Cultural. Se celebra en Agosto. Festejos costeros de rango comarcal muy populares, potenciados por el marco monumental del arco romano de Berà, dotados de desfiles folclóricos, castellers, correfocs y verbenas masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43132','fiesta','Festa Major de Sant Joan y de San Roque','Patronal. Se celebra en Agosto. Festejos tradicionales del Alt Camp meridional con pasacalles musicales locales, campeonatos de cartas tradicionales aragoneses, comidas comunitarias de hermandad al aire libre y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43133','fiesta','Festes Majors de Roquetes (Sant Gregori)','Patronal / Taurina / Cultural. Se celebra en Julio. Festejos de rango comarcal en el Baix Ebre a las faldas del Parc Natural dels Ports, caracterizados por sus masivos espectáculos taurinos tradicionales, pasacalles folclóricos y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43134','fiesta','Festa Major de San Pedro y de la Virgen de la Natividad','Patronal. Se celebra en Julio. Pequeña festividad veraniega de marcado carácter vecinal orientada estrictamente a la población flotante y local del llano del Alt Camp, con un programa lúdico básico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43135','fiesta','El Ball del Sant Crist de Salomó y Festa Major de Santa Maria','Teatral / Etnográfica / Religiosa. Se celebra en Mayo (El Ball) y Agosto (Festa Major). Declarada Fiesta de Interés Turístico por la Generalitat de Catalunya. Extraordinaria representación teatral y sacra de origen medieval que involucra de forma masiva a los vecinos de la comarca del Tarragonès.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43138','fiesta','Festes Majors de Santa Bàrbara','Patronal / Taurina. Se celebra en Julio. Festejos tradicionales del llano del Montsià, destacados por la activa participación de sus peñas de bous, encierros, suelta de vaquillas populares y verbenas lúdicas en el ferial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43139','fiesta','Festa Major de Santa Coloma i la Fira del Somera','Patronal / Histórica / Feria Tradicional. Se celebra en Agosto. Festejos de relevancia comarcal en la Baixa Segarra, caracterizados por pasacalles folclóricos de gigantes y bestias de fuego, sardanas y mercados tradicionales en su casco histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43140','fiesta','Festa Major de la Mare de Déu del Remei','Patronal. Se celebra en Agosto. Celebración de escala local en el Baix Penedès, vertebrada en torno al marco monumental de su castillo-iglesia románico, con tradicionales misas solemnes y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43142','fiesta','Festa Major de los Sants Metges i Sant Cosme','Patronal / Feria de Sector. Se celebra en Julio y Octubre. Festejos que combinan el patrimonio litúrgico de su ermita con la tradicional puesta en valor de su artesanía del alabastro, sumando pasacalles folclóricos y comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90921','fiesta','Festa Major de Sant Pere de Savallà','Patronal. Se celebra en Agosto. Mínima expresión festiva de carácter estrictamente familiar en la Conca de Barberà debido a la baja demografía, limitada a una misa solemne y un vermut vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43144','fiesta','Festa Major de la Mare de Déu de l''Assumpció i Sant Roc','Patronal. Se celebra en Agosto. Festejos tradicionales que unifican las costumbres de sus diferentes núcleos de población del Tarragonès, consistentes en comidas populares al aire libre y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43146','fiesta','Festa Major de la Mare de Déu de l''Assumpció','Patronal. Se celebra en Agosto. Pequeñas fiestas de marcado ambiente vecinal adaptadas a la escasa población de este núcleo del interior, centradas en ritos litúrgicos tradicionales y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43147','fiesta','Festa Major de Sant Domènec y de la Mare de Déu del Sagrat Cor','Patronal. Se celebra en Agosto. Celebración de la Conca de Barberà con tradicionales pasacalles, desfiles infantiles, bailes de sardanas de plaza y una activa participación vecinal en las orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43148','fiesta','Festes de Santa Tecla de Tarragona','Patronal / Etnográfica / Castellera. Se celebra en Septiembre. Declarada Fiesta de Interés Turístico Internacional. Macrocelebración masiva global, célebre por la Baixada de l''Àliga, el Seguici Popular de bestias y balls, y las históricas e impresionantes diadas castelleras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43149','fiesta','Festa Major de Sant Miquel','Patronal / Taurina. Se celebra en Septiembre. Festejos tradicionales del Baix Ebre, caracterizados por pasacalles de gigantes de la comarca, espectáculos taurinos de vaquillas populares en la plaza y cenas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43150','fiesta','Festa Major de Sant Jaume i Fira de Tivissa','Patronal / Feria Tradicional. Se celebra en Julio. Festejos de gran sabor tradicional en la Ribera d''Ebre que destacan por sus pasacalles por su casco antiguo amurallado, ferias de artesanía artesanal y animadas verbenas lúdicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43153','fiesta','Festa Major de Santa Rosalia i del Quadre de Santa Rosalia','Patronal / Costera / Castellera. Se celebra en Julio y Septiembre. Grandes fiestas costeras del Tarragonès, muy populares por sus diadas castelleras de nivel provincial, correfocs masivos de diablos locales, desfiles y conciertos públicos en la playa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43154','fiesta','Festa Major de Sant Miquel','Patronal / Enológica. Se celebra en Septiembre. Celebración de escala estrictamente local en el corazón del vino con tradicionales misas solemnes, comidas populares de hermandad vecinal y catas de vino con D.O.Q. Priorat.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43155','fiesta','Festa del Renaixement de Tortosa i Festes de la Cinta','Recreación Histórica / Patronal / Etnográfica. Se celebra en Julio (Renaixement) y Septiembre (La Cinta). La Festa del Renaixement está declarada Fiesta de Interés Turístico Nacional. Espectacular transformación urbana del siglo XVI con campamentos medievales, desfiles masivos de época y tabernas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43156','fiesta','Festes Majors d''Ulldecona (Ball de Mantons) y Pasió d''Ulldecona','Patronal / Etnográfica / Teatral. Se celebra en Marzo / Abril (La Passió) y Agosto (Festes). La representación teatral de La Passió posee un gran empaque y trascendencia regional; sus fiestas mayores destacan de forma monumental por el tradicional y masivo Ball de Mantons.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43157','fiesta','Festa de la de la Truita amb Sussa de Ulldemolins y Festa Major de Sant Jaume','Gastronómica / Feria Tradicional / Patronal. Se celebra en Julio. Festejos del Priorat con notable raigambre provincial, célebres por el histórico certamen y degustación masiva de este plato tradicional guisado local, arropado por folclore aragonés.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43158','fiesta','Festa Major de Sant Antoni Abat','Patronal. Se celebra en Agosto. Festejos de ámbito local desplazados al mes estival para asegurar el reencuentro, basados en ritos religiosos tradicionales en su iglesia histórica y verbenas reducidas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43159','fiesta','Festa Major de la Mare de Déu del Albi','Patronal / Cultural. Se celebra en Agosto. Festejos tradicionales de la comarca de la Conca de Barberà potenciados por su histórico entorno de aguas termales, con verbenas de plaza y juegos tradicionales locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43160','fiesta','Festa Major de Sant Llorenç y del Roser','Patronal. Se celebra en Agosto. Celebración de la llanura del Alt Camp con tradicionales pasacalles de gigantes de la comarca, bailes de sardanas de plaza y comidas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43161','fiesta','Festes de la Decennal de la Mare de Déu de la Candela y Festa Major de Sant Joan','Patronal / Etnográfica / Decenal / Castelleras. Se celebra en Junio (Sant Joan) y Febrero (Cada 10 años). Declarada Fiesta de Interés Turístico Nacional. Considerada la "cuna de los castells", destaca por la monumental rivalidad de las Colles Xiquets de Valls y las espectaculares e históricas fiestas decenales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43162','fiesta','Festa Major de l''Hospitalet de l''Infant (Sant Roc) y de Vandellòs (Sant Cosme)','Patronal / Costera. Se celebra en Agosto y Septiembre. Festejos de rango comarcal muy consolidados, con un potente programa lúdico que une las tradiciones del interior con las actividades lúdicas marítimas, fuegos y orquestas masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42005','fiesta','Festa Major de Santa Anna y Fira de Santa Teresa *','Patronal / Etnográfica / Castellera *. Se celebra en Julio (Santa Anna) y Octubre (Fira) *. Festejos de enorme peso y trascendencia en el Baix Penedès, célebres por las espectaculares diadas de la Colla Joves Nens del Vendrell, correfocs de primer nivel y su secular feria tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43164','fiesta','Festa Major de Sant Miquel','Patronal. Se celebra en Septiembre. Mínimos festejos de carácter vecinal debido a la reducida población residente, limitados a actos litúrgicos tradicionales en su casco histórico y un vermut popular comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43170','fiesta','Festa Major de Sant Llorenç y Fira de Vila-rodona','Patronal / Feria Tradicional. Se celebra en Agosto (Festa Major) y Noviembre (Fira). Festejos tradicionales del Alt Camp que combinan pasacalles folclóricos de gigantes de la comarca con su histórica feria agrícola de campo y mercados artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43166','fiesta','Festa Major de Sant Martí y del Roser','Patronal. Se celebra en Noviembre. Festejos patronales tradicionales de la comarca del Tarragonès, caracterizados por el desfile de gigantes, competiciones lúdicas locales y bailes populares nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43168','fiesta','Festa de la de la Castanya de Vilanova de Prades i Festa Major de Sant Salvador','Gastronómica / Feria Tradicional / Patronal. Se celebra en Agosto (Festa Major) y Octubre (Castanya). Festejos de montaña en el entorno de Poblet que destacan por su feria tradicional dedicada a la castaña, atrayendo provincialmente a numeroso público gastronómico y mercados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43167','fiesta','Festa Major de Sant Agustí','Patronal. Se celebra en Agosto. Celebración de ámbito estrictamente local en el Baix Camp, estructurada en torno a pasacalles populares, juegos infantiles tradicionales aragoneses y comidas vecinales de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43169','fiesta','Festa Major de la Nativitat de la Mare de Déu','Patronal. Se celebra en Septiembre. Festejos estivales a los pies de la Sierra de la Mussara, con procesión solemne tradicional, comidas populares de hermandad al aire libre y música de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42016','fiesta','Festa Major de Sant Antoni (Fiesta de los Caballos) y Festa Major de Sant Esteve','Patronal / Etnográfica / Hípica. Se celebra en Enero (Sant Antoni) y Agosto (Sant Esteve). Declarada Fiesta de Interés Turístico por la Generalitat. Hito hípico y folclórico de rango autonómico de gran renombre provincial, célebre por sus históricas y masivas carreras de caballos tradicionales en el coso local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43172','fiesta','Festa Major de Sant Martí','Patronal. Se celebra en Noviembre. Pequeñas fiestas de marcado ambiente familiar en el paso del río Francolí de la Conca de Barberà, con ritos tradicionales religiosos y verbenas lúdicas en el pabellón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43176','fiesta','Fiestas Quinquenales de la Mare de Déu dels Torrents i Festa Major de San Salvador','Patronal / Quinquenal / Etnográfica. Se celebra en Agosto (Anual) y Septiembre (Cada 5 años). Sus fiestas quinquenales poseen un gran arraigo provincial, muy vinculadas al monumental Real Monasterio de Santa María de Poblet, engalanando las calles medievales con alfombras y arcos artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43177','fiesta','Festa Major de Sant Llorenç','Patronal / Etnográfica. Se celebra en Agosto. Festejos tradicionales de la Ribera d''Ebre que destacan por la ronda de jotas, pasacalles musicales locales de gigantes de la comarca y comidas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90922','fiesta','Festes Majors de Sant Jaume','Patronal / Taurina. Se celebra en Julio. Festejos tradicionales del Baix Ebre a orillas del río, caracterizados por sus tradicionales vaquillas populares en plaza portátil, espectáculos taurinos de calle, jotas y cenas de hermandad vecinal). Hemos completado de forma exhaustiva al 100% todos los municipios de la provincia de Tarragona, finalizando así la totalidad de la Comunidad Autónoma de Cataluña. Si quieres continuar en este chat o preparar los datos para una nueva sesión, la siguiente Comunidad Autónoma en estricto orden alfabético es La Rioja. ¿Procedemos a preparar el bloque de municipios correspondientes de la A hasta la I?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90673','fiesta','Fiestas en Honor a San Esteban Protomártir y Jornada de Puertas Abiertas en las Bodegas','Patronal / Enológica. Se celebra en Agosto y Septiembre. Festejos de fuerte arraigo en la Rioja Alta; su jornada enológica atrae a numeroso público provincial para visitar sus bodegas centenarias, lagares rupestres y catar vinos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90265','fiesta','Fiestas de San Roque y Santa María de la Antigua','Patronal / Histórica. Se celebra en Agosto. Festejos tradicionales junto a su imponente castillo medieval de Aguas Mansas, caracterizados por pasacalles de la banda local, partidos de pelota mano, jotas riojanas y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90266','fiesta','Fiestas de la Virgen de los Remedios y de San Pedro Apóstol','Patronal / Romería. Se celebra en Mayo y Agosto. Celebración tradicional en la Rioja Baja que incluye la romería a la ermita de los Remedios, combinando ritos religiosos tradicionales, comidas vecinales de hermandad y verbenas lúdicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90923','fiesta','Fiestas de San Cristóbal','Patronal. Se celebra en Julio. Mínima expresión festiva de carácter estrictamente familiar en el Alto Leza debido a la baja demografía, limitada a la santa misa, comidas populares compartidas y música de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90267','fiesta','Fiestas de Santiago Apóstol y de San Prudencio','Patronal / Etnográfica. Se celebra en Abril y Julio. Festejos de notable peso comarcal en el valle del Iregua, destacados por el tradicional reparto de las "habas de San Prudencio", procesiones solemnes tradicionales y verbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90268','fiesta','Fiestas de la Virgen de la Antigua y de San Martín','Patronal. Se celebra en Septiembre y Noviembre. Festejos de arraigo local tradicionales muy ligados a su cercanía con la capital, caracterizados por pasacalles musicales, grandes cenas populares en las calles y alta participación de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90924','fiesta','Fiestas de Santiago Apóstol y San Roque','Patronal. Se celebra en Julio. Festejos veraniegos de marcado ambiente vecinal en el valle del Tuerto, sustentados en el regreso estival de familias, campeonatos de cartas tradicionales y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90925','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Septiembre. Pequeña celebración de ámbito estrictamente local con un programa lúdico y religioso mínimo adaptado a la reducida población residente en el municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90269','fiesta','Fiestas en Honor a San Roque y San Ezequiel Moreno','Patronal / Taurina / Etnográfica. Se celebra en Agosto. Grandes fiestas mayores de la comarca con enorme arraigo en la Rioja Baja, célebres por sus tradicionales encierros de toros, suelta de vaquillas, la monumental quema del "Chupinazo" y el recinto de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90926','fiesta','Fiestas de la Virgen del Valle','Patronal / Romería. Se celebra en Julio. Festejos serranos que reúnen a los vecinos en la romería tradicional a la ermita de la virgen, seguidos de comidas comunitarias de hermandad al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90927','fiesta','Fiestas de San Pedro y de la Virgen de la Concepción','Patronal / Romería. Se celebra en Junio y Agosto. Festejos de retorno estival en la comarca de Haro, caracterizados por la concurrida romería a la ermita de Santa María de Oreca, orquestas de plaza y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90270','fiesta','Fiestas de la Magdalena (Danza de los Zancos de Anguiano)','Etnográfica / Folclórica / Patronal. Se celebra en Julio y Septiembre. Declarada Fiesta de Interés Turístico del rango regional/autonómico. Hito etnográfico absoluto de España donde los danzantes se tiran sobre zancos de madera por una empinada cuesta empedrada girando sobre sí mismos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90928','fiesta','Fiestas de la Virgen del Carmen','Patronal. Se celebra en Agosto. Festejos tradicionales de carácter familiar en el valle del Najerilla, consistentes en pasacalles, campeonatos de naipes locales y sesiones lúdicas de baile nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90929','fiesta','Fiestas de San Onofre','Patronal. Se celebra en Junio. Mínimos festejos de carácter vecinal debido a la escasa población residente, limitados a ritos litúrgicos tradicionales y un vermut popular comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90930','fiesta','Procesión del Humo y Fiestas de la Virgen de las Nieves','Etnográfica / Religiosa / Patronal. Se celebra en Noviembre (Procesión del Humo) y Agosto (Nieves). Declarada Fiesta de Interés Turístico Regional. Singular hito tradicional de la Rioja Baja donde los cofrades procesionan quemando romero negro en hogueras, inundando las calles de un denso humo protector.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90271','fiesta','Fiestas de San Cosme y San Damián (El Robo de los Santos)','Patronal / Etnográfica / Taurina. Se celebra en Septiembre. Declarada Fiesta de Interés Turístico de rango regional. Célebre por el hito etnográfico de "El Robo de los Santos", donde navarros y arnedanos simulan disputarse las imágenes, sumando una feria taurina de gran prestigio nacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90931','fiesta','Fiestas de San Justo y San Pastor','Patronal. Se celebra en Agosto. Festejos locales del llano de la comarca, vertebrados sobre comidas populares de hermandad vecinal, partidos de pelota tradicionales locales y sesiones lúdicas de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26020','fiesta','Fiestas de la Virgen de la Antigua y de San Ecce Homo','Patronal. Se celebra en Agosto y Septiembre. Celebración de la Rioja Baja con tradicionales pasacalles, fuegos artificiales, bailes públicos y comidas vecinales de hermandad respaldadas por el vecindario comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26021','fiesta','Fiestas de San Adrián y Santa Natalia y las Jornadas del Champiñón','Patronal / Gastronómica / Feria de Sector. Se celebra en Septiembre (Patronal) y Octubre/ Noviembre (Jornadas). Festejos con notable raigambre provincial; sus jornadas gastronómicas dedicadas a la seta y el champiñón destacan por sus degustaciones multitudinarias y la implicación sectorial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26022','fiesta','Fiestas de la Virgen de Valvanera y de San Pedro','Patronal. Se celebra en Julio y Septiembre. Festejos locales en pleno Camino de Santiago, orientados al regreso de veraneantes estivales, con comidas populares, partidos de pelota mano y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26023','fiesta','Fiestas de la Virgen de Valvanera y de San Roque','Patronal / Enológica. Se celebra en Agosto y Septiembre. Festejos tradicionales del valle del Cárdenas vinculados al cultivo vitivinícola de la zona, caracterizados por la ronda de jotas, degustaciones populares y verbenas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26024','fiesta','Fiestas en Honor a San Formerio','Patronal / Etnográfica. Se celebra en Agosto y Septiembre. Festejos de arraigo local tradicionales destacados por la procesión y traslación de las reliquias del santo en su monumental arqueta gótica, con danzas folclóricas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26025','fiesta','Fiestas de la Virgen de la Magdalena','Patronal. Se celebra en Julio. Pequeñas fiestas de arraigo puramente local al pie del valle del Oja con ritos religiosos tradicionales, campeonatos de cartas tradicionales y orquestas reducidas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26026','fiesta','Fiestas de San Isidro y de San Bartolomé','Patronal / Gastronómica. Se celebra en Mayo y Agosto *. Festejos de rango comarcal de alta popularidad en el Najerilla, célebres por su histórica e inmensa industria chacinera tradicional, con el multitudinario festival del chorizo asado y pelota mano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26027','fiesta','Fiestas de la Virgen de la Asunción y San Millán','Patronal / Romería. Se celebra en Julio y Agosto. Festejos locales muy ligados al entorno monumental de San Millán de la Cogolla, con romerías tradicionales de carretas, jotas riojanas y comidas de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26028','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre. Pequeña celebración vecinal condicionada por la baja demografía en las inmediaciones del Cidacos, centrada en actos litúrgicos tradicionales y comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26029','fiesta','Fiestas de Santa María Magdalena','Patronal. Se celebra en Agosto. Mínima expresión festiva de carácter estrictamente familiar en el municipio con menos habitantes de la comarca, basada en una misa tradicional y vermut vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26030','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Festejos rurales mínimos en una zona de baja densidad de población, limitados a la santa misa tradicional en su ermita histórica y comidas familiares tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26031','fiesta','Fiestas de San Juan Bautista y San Lázaro','Patronal. Se celebra en Junio y Agosto. Pequeña festividad veraniega de marcado carácter vecinal orientada al reencuentro de familias ligadas históricamente al pueblo, con verbenas y comidas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26032','fiesta','Fiesta de la Trashumancia y Fiestas de San Felices','Etnográfica / Ganadera / Patronal. Se celebra en Julio y Agosto. Hito tradicional de gran relevancia serrana; su festival de la trashumancia recrea de forma masiva el esquileo artesanal, el mercado de lana tradicional y las costumbres de los pastores de Cameros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26033','fiesta','Fiestas en Honor a la Virgen de la Vega','Patronal / Enológica. Se celebra en Septiembre. Festejos veraniegos de carácter local a orillas del Ebro, sustentados sobre el cultivo vitivinícola tradicional de la Rioja Alta, con comidas populares y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26034','fiesta','Jornadas Medievales de Briones y Fiestas del Santo Cristo de los Remedios','Recreación Histórica / Etnográfica / Patronal. Se celebra en Junio (Jornadas) y Septiembre (Fiestas). Declarada Fiesta de Interés Turístico de rango regional. Espectacular y multitudinaria recreación histórica donde el pueblo entero se viste de época para revivir la vida del siglo XIV en sus palacios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26035','fiesta','Fiestas de San Sancho','Patronal. Se celebra en Septiembre. Pequeños festejos rurales en el alto valle del Leza de extrema baja demografía, centrados en el reencuentro familiar tradicional y litúrgico básico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26036','fiesta','Semana Santa de Calahorra (Mercaforum) y Fiestas de San Emeterio y San Celedonio','Recreación Histórica / Religiosa / Patronal. Se celebra en Marzo / Abril (Mercaforum) y Agosto (Patronales). Declaradas de Interés Turístico Nacional de forma conjunta. Su monumental mercado romano Mercaforum y la escenificación de la Pasión transforman de forma masiva la capital de la Rioja Baja.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26037','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Festejos estivales en las faldas de la sierra de Moncalvillo, caracterizados por el regreso de familias vinculadas al pueblo, comidas de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26038','fiesta','Fiestas de la Virgen de la Soledad y de San Jaime','Patronal / Etnográfica. Se celebra en Julio y Agosto. Festejos de montaña en el alto Najerilla que conservan su histórico e identitario "Baile de los pañuelos", arropado por comidas vecinales en su plaza porticada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26040','fiesta','Fiestas de la Virgen de la Asunción','Patronal / Cultural. Se celebra en Agosto. Festejos locales muy ligados al entorno monumental del Abadía Cisterciense, con tradicionales misas solemnes, comidas populares y música de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26042','fiesta','Fiestas de San Juan y de la Virgen de la Serna','Patronal / Enológica / Cultural. Se celebra en Junio y Septiembre. Festejos de rango comarcal de alta consolidación en la Rioja Alta, célebres por sus tradicionales e históricos pasacalles, festivales líricos en su convento gótico y degustaciones masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26043','fiesta','Fiestas de la Virgen de la Natividad','Patronal / Etnográfica. Se celebra en Septiembre. Festejos tradicionales de la Rioja Alta destacados por su vistosa procesión con danzas folclóricas locales tradicionales acompañadas de dulzaineros y alta participación de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26044','fiesta','Fiestas de San Juan y de la Virgen de la Oliva','Patronal / Romería. Se celebra en Junio y Agosto. Festejos estivales en las medianías del valle, caracterizados por la concurrida romería tradicional a su ermita, comidas de hermandad vecinal y música al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26045','fiesta','Fiestas de la Virgen del Barrio','Patronal / Romería. Se celebra en Septiembre. Festejos rurales mínimos en una espectacular atalaya fortificada de los Montes Obarenes, limitados al culto religioso tradicional y almuerzos compartidos por baja demografía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26046','fiesta','Fiestas de Santa Daría y de la Virgen del Valle','Patronal / Enológica / Taurina. Se celebra en Septiembre. Grandes fiestas mayores de la comarca con enorme arraigo vitivinícola, famosas por el reparto de los bollos tradicionales de la virgen, catas públicas, tradicionales encierros y comidas masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26047','fiesta','Fiestas de Santa Ana y San Gil (Danza de la Gaita)','Patronal / Etnográfica. Se celebra en Julio y Septiembre. Declarada Fiesta de Interés Turístico Regional. Destaca de forma monumental por la antiquísima Danza de la Gaita, hito etnográfico de la Rioja Baja donde los danzantes visten faldas tradicionales y ejecutan complejas mudanzas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26048','fiesta','Fiestas en Honor a la Virgen del Rosario','Patronal. Se celebra en Octubre. Festejos rurales mínimos condicionados por la baja demografía y la dispersión de sus pequeños núcleos en la Rioja Alta, limitados a actos religiosos y un vermut vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26049','fiesta','Fiestas de San Juan Bautista y de la Virgen del Somero','Patronal / Enológica. Se celebra en Junio y Septiembre. Festejos tradicionales de marcado ambiente estival junto a su puente romano, caracterizados por el tradicional reparto de chocolate, comidas populares de hermandad y degustación de vinos de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26050','fiesta','Fiestas en Honor a la Virgen del Rosario','Patronal. Se celebra en Septiembre. Celebración de escala local muy vinculada al paso del Camino de Santiago, sustentada en ritos litúrgicos tradicionales, campeonatos de cartas y pequeñas orquestas para los vecinos y peregrinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26051','fiesta','Fiestas de Santiago Apóstol y la Virgen de la Esperanza','Patronal / Histórica. Se celebra en Julio y Septiembre. Festejos de fuerte sabor tradicional a la sombra de su castillo medieval, que conmemoran la mítica batalla jacobea mediante misas Solemnes, jotas riojanas y verbenas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26052','fiesta','Fiestas de San Cristóbal','Patronal / Enológica. Se celebra en Julio. Festejos estivales muy vinculados a la producción artesanal de su afamado vino clarete tradicional, con tradicionales pasacalles, comidas populares al aire libre y sesiones de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26053','fiesta','Fiestas de San Sebastián y la Virgen del Rosario','Patronal. Se celebra en Enero y Octubre. Pequeñas fiestas de arraigo puramente local en el valle de Ocón, estructuradas en torno a actos religiosos tradicionales, encendido de hogueras invernales y una comida de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26054','fiesta','Fiestas de la Virgen de la Piedad','Patronal / Taurina. Se celebra en Septiembre. Festejos locales que integran la procesión tradicional de la virgen con espectáculos taurinos de vaquillas populares por las empinadas calles que rodean su monumental castillo fortificado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26055','fiesta','Fiestas de San Martín','Patronal. Se celebra en Noviembre. Pequeña celebración vecinal con un programa lúdico y religioso mínimo adaptado a la escasa población de este núcleo agrícola de la Rioja Alta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26056','fiesta','Fiestas de la Virgen de Tironcillo y de San Miguel','Patronal / Romería / Enológica. Se celebra en Mayo y Septiembre. Festejos de arraigo comarcal que destacan por la concurrida romería tradicional a la ermita de Tironcillo con reparto de caridad, acompañados de jotas riojanas, bodegas abiertas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26057','fiesta','Fiestas en Honor a San Lorenzo','Patronal. Se celebra en Agosto. Festejos trasladados al mes estival para asegurar el reencuentro de familias vinculadas a la localidad, basados en juegos tradicionales infantiles, cenas populares y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26058','fiesta','Fiestas de la Virgen de la Estrella y San Roque','Patronal / Cultural. Se celebra en Agosto. Festejos veraniegos que dinamizan el valle del Cidacos, uniendo los ritos litúrgicos tradicionales con actividades lúdicas y turísticas ligadas a la ruta de los dinosaurios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26059','fiesta','Fiestas de San Cristóbal y San Blas','Patronal / Etnográfica. Se celebra en Febrero y Julio. Celebración con notable dinamismo en el entorno metropolitano de Logroño, caracterizada por la procesión tradicional al santo, degustaciones populares de preñados y verbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26060','fiesta','Fiestas de San Millán y de la Virgen del Rosario','Patronal / Romería. Se celebra en Septiembre. Festejos de escala estrictamente local en el valle de San Millán, muy vinculados a la romería tradicional al Monasterio de Valvanera, combinando fe, comidas de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26061','fiesta','Fiestas de San Lorenzo y las Aleluyas de Ezcaray','Patronal / Etnográfica / Gastronómica. Se celebra en Agosto. Declarada Fiesta de Interés Turístico Regional. Célebre por el singular hito etnográfico del lanzamiento masivo de dinero y pan ("aleluyas") desde los balcones de la iglesia tras la procesión tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26064','fiesta','Fiesta de Los Marchos i Fiestas de San Juan y San Pedro','Etnográfica / Enológica / Patronal. Se celebra en Junio (San Juan) y Diciembre (Los Marchos). Su festividad invernal de "Los Marchos" posee gran relevancia provincial, hito etnográfico donde se encienden cientos de hogueras tradicionales por las calles para purificar las bodegas de vino de la localidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26065','fiesta','Fiestas en Honor a la Virgen de la Asunción','Patronal. Se celebra en Agosto. Mínimos festejos de marcado carácter familiar en los montes Obarenes debido a la baja demografía, limitados a una misa solemne y un vermut popular vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26066','fiesta','Fiestas de San Vicente Mártir','Patronal. Se celebra en Enero y Agosto. Celebración de ámbito estrictamente local en el valle de Ocón, fundamentada en ritos religiosos tradicionales, comidas populares de hermandad y pequeñas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26067','fiesta','Fiestas de la Virgen de la Cuesta','Patronal / Romería. Se celebra en Agosto. Pequeña festividad estival de reunión vecinal en el Camero Nuevo, con romería tradicional a la ermita románica, juegos infantiles y cenas de hermandad al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26068','fiesta','Fiestas de San Martín','Patronal / Enológica. Se celebra en Noviembre. Festejos rurales de marcado ambiente vecinal vinculados a la cultura vinícola de la Rioja Alta, articulados sobre misas solemnes tradicionales y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26069','fiesta','Fiestas de la Virgen de Carrasquedo y de San Juan Bautista','Patronal / Romería / Etnográfica. Se celebra en Mayo y Agosto. Festejos de fuerte arraigo jacobeo en el límite con Burgos, destacados por su concurrida romería tradicional a la ermita en el bosque, el canto de albadas y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26070','fiesta','Fiestas del Humilladero y de San Antón','Patronal / Etnográfica. Se celebra en Septiembre. Celebración de la Rioja Baja que conserva la tradicional ronda de jotas por las calles y ritos vinculados a sus históricos manantiales termales, con cenas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26071','fiesta','Batalla del Vino de Haro','Etnográfica / Enológica / Romería. Se celebra en Junio (Festividad de San Pedro). Declarada Fiesta de Interés Turístico Nacional con gran repercusión internacional masiva global. Colosal batalla incruenta en los riscos de Bilibio donde miles de personas se arrojan litros de vino.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26072','fiesta','Fiestas de Santa Ana y el Salvador','Patronal / Romería. Se celebra en Julio. Festejos locales en el valle del Cidacos que giran en torno a la romería tradicional a la ermita del Salvador colgada de las peñas, sumando comidas populares de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26073','fiesta','Fiestas de San Esteban y la Virgen de la Vega *','Patronal / Etnográfica *. Se celebra en Agosto *. Celebración tradicional en la cuenca del Tirón, caracterizada por pasacalles de música tradicional riojana, campeonatos de cartas y comidas vecinales al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26074','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Festejos patronales tradicionales marcados por el reencuentro veraniego de familias, con misas solemnes tradicionales, actividades infantiles locales y orquestas de plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26075','fiesta','Fiestas de San Martín y la Virgen del Rosario','Patronal. Se celebra en Agosto. Celebración local de la Rioja Alta vertebrada sobre comidas populares de hermandad, partidos de pelota mano tradicional y sesiones de orquesta nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26076','fiesta','Fiestas de San Gregorio','Patronal / Enológica. Se celebra en Mayo y Agosto. Pequeñas fiestas estivales trasladadas de época con un programa lúdico básico adaptado a la baja demografía, con degustación de vinos de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26078','fiesta','Fiestas de San Cristóbal','Patronal. Se celebra en Julio. Pequeña festividad local que congrega a los habitantes en torno a una misa solemne tradicional, comidas populares de hermandad y música de orquesta reducida.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26079','fiesta','Fiestas de San Pantaleón y de la Virgen de la Guía','Patronal / Etnográfica / Pelota. Se celebra en Julio. Festejos de fuerte arraigo en el valle del Najerilla, destacados por sus tradicionales torneos de pelota mano de alta raigambre riojana, pasacalles folclóricos y degustaciones.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26080','fiesta','Fiestas de la Virgen del Villar','Patronal / Taurina. Se celebra en Septiembre. Festejos de la Rioja Baja con notable arraigo comarcal, caracterizados por los encierros tradicionales y suelta de vaquillas populares en su plaza, jotas y cenas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26081','fiesta','Fiestas de San Miguel','Patronal. Se celebra en Agosto. Festejos de alta montaña mínimos condicionados por el declive demográfico en las cuencas serranas, limitados a la liturgia tradicional y encuentro vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26082','fiesta','Fiestas de Santo Domingo de Silos','Patronal / Etnográfica. Se celebra en Agosto. Festejos serranos de gran sabor tradicional en el Camero Viejo, célebres por el tradicional reparto de migas pastoriles y la música folclórica montañesa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26083','fiesta','Fiestas en Honor a San Antón','Patronal. Se celebra en Agosto. Festejos de reencuentro estival en el valle del Jubera que unifican las costumbres de sus pedanías mediante verbenas de plaza y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26084','fiesta','Fiestas de San Pedro y San Marcial','Patronal / Cultural. Se celebra en Junio. Festejos periurbanos que han crecido exponencialmente en paralelo a su explosión demográfica, con un potente programa de conciertos, desfiles folclóricos y ferias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26086','fiesta','Fiestas en Honor a San Bartolomé','Patronal. Se celebra en Agosto. Mínima expresión festiva de carácter estrictamente familiar en la sierra de la Demanda, centrada en una misa tradicional y vermut vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26087','fiesta','Fiestas de la Virgen de los Desamparados y de San Andrés','Patronal / Romería. Se celebra en Mayo y Agosto. Celebración de la Rioja Alta junto al río Tirón, caracterizada por la romería tradicional a la ermita, partidos de pelota mano tradicional y verbenas de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26088','fiesta','Fiestas de San Martín','Patronal. Se celebra en Agosto. Pequeñas fiestas estivales de marcado ambiente familiar e infantil en la entrada al cañón del río Leza, dirigidas estrictamente a la población local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26089','fiesta','Fiestas de San Mateo (Fiestas de la Vendimia Riojana) y San Bernabé','Patronal / Enológica / Etnográfica / Histórica. Se celebra en Junio (San Bernabé) y Septiembre (San Mateo). Declaradas Fiestas de Interés Turístico Nacional de forma conjunta. Macrocelebración de la capital, célebre por el hito etnográfico del pisado de la uva de los primeros racimos y la ofrenda del mosto a la Virgen de Valvanera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90932','fiesta','Fiestas de la Virgen de la Luz y la Fiesta de la Trashumancia','Patronal / Etnográfica / Romería. Se celebra en Julio y Agosto. Su Fiesta de la Trashumancia en la Venta de Piqueras posee gran valor etnográfico provincial, recreando los antiguos ritos y folclore de los pastores serranos trashumantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26094','fiesta','Fiestas en Honor a San Juan','Patronal. Se celebra en Agosto. Pequeña celebración vecinal con un programa lúdico y religioso mínimo adaptado a la escasa población de este núcleo cerealista serrano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26093','fiesta','Fiestas de la Virgen de la de la Muela','Patronal / Romería. Se celebra en Agosto. Festejos marcados por el impresionante marco del pantano que inunda el antiguo pueblo, con romería tradicional a la ermita, comidas populares de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26095','fiesta','Fiestas de San Quirico y Santa Julita','Patronal / Romería. Se celebra en Junio y Agosto. Celebración local junto a las peñas del Anguiano, vertebrada sobre la tradicional subida en romería a la ermita serrana, comidas vecinales y música de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26096','fiesta','Fiestas de la Virgen de la Natividad','Patronal. Se celebra en Septiembre. Festejos tradicionales de carácter familiar en las medianías del Moncalvillo, consistentes en pasacalles musicales locales, reparto de preñados y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26098','fiesta','Fiestas de la Virgen de la Soledad y de San Antón','Patronal / Cultural / Feria Tradicional. Se celebra en Agosto. Festejos tradicionales del alto Cidacos potenciados por sus jornadas del queso artesanal de Cameros, atrayendo provincialmente a numeroso público gastronómico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26099','fiesta','Fiestas de San Esteban y de la Virgen del Cortijo','Patronal / Taurina. Se celebra en Agosto. Festejos de rango comarcal muy consolidados en el valle del Leza, famosos por sus encierros tradicionales, suelta de vaquillas populares en la plaza, jotas y grandes orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26100','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Pequeñas fiestas estivales de marcado ambiente familiar en la sierra de Ausejo, centradas en la hermandad vecinal, parrilladas populares y música de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26101','fiesta','Fiestas de la Virgen del Cerro','Patronal / Romería. Se celebra en Agosto. Pequeña festividad rural que congrega a los habitantes dispersos en torno a la romería a la ermita tradicional de la virgen y comidas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26102','fiesta','Crónicas Najerenses y Fiestas de San Juan y San Pedro (Las Vueltas)','Recreación Histórica / Patronal / Etnográfica / Teatro. Se celebra en Junio (Las Vueltas) y Julio (Crónicas). Declarada Fiesta de Interés Turístico de rango regional. Sus Crónicas Najerenses son un monumental hito de recreación histórica teatral que evoca el esplendor de la corte real navarra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26103','fiesta','Fiesta de los Gallos de Nalda i Fiestas de la Virgen y San Roque','Etnográfica / Tradicional / Patronal. Se celebra en Mayo (Gallos) y Agosto (Fiestas) *. Su histórica Fiesta de los Gallos en primavera posee rango comarcal de alta popularidad, hito etnográfico donde jinetes a caballo compiten en carreras tradicionales de destreza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26104','fiesta','Fiestas en Honor a San Blas','Patronal. Se celebra en Agosto. Festejos trasladados al mes estival debido a la extrema baja demografía del extremo sur riojano, basados en comidas familiares tradicionales y ritos litúrgicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26106','fiesta','Fiestas de la Virgen de la de la Mano y de San Martín','Patronal / Romería. Se celebra en Septiembre. Pequeños festejos tradicionales de alta montaña en el Camero Nuevo, sustentados en la misa solemne tradicional en la iglesia y un almuerzo vecinal de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26107','fiesta','Fiestas de Santiago Apóstol y la Virgen de Castejón','Patronal / Romería. Se celebra en Julio. Festejos tradicionales serranos que incluyen la romería tradicional a la ermita alpina de Castejón, uniendo el fervor pastoril con comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26109','fiesta','Fiestas de la Virgen de la Concepción','Patronal. Se celebra en Agosto. Celebración veraniega de carácter local a orillas del río Tirón, basada en el regreso de familias emigradas, comidas de hermandad al aire libre y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26108','fiesta','Fiesta de la de la Molienda de Ocón i Fiestas de la Virgen de la de la Redonda','Etnográfica / Feria Tradicional / Patronal. Se celebra en Agosto (Molienda). Hito etnográfico a nivel provincial de gran dinamismo; la Fiesta de la Molienda recrea de forma masiva la siega tradicional y el funcionamiento de su histórico molino de viento artesanal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26111','fiesta','Fiestas de Santa Eulalia y de la Virgen del Panteón','Patronal / Enológica. Se celebra en Diciembre (Eulalia) y Agosto (Panteón). Festejos tradicionales de la Rioja Alta muy vinculados a la cultura vitivinícola tradicional y los palacios de su casco histórico, con catas populares de bodegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26112','fiesta','Fiestas de la Virgen del Carmen y de San Martín','Patronal / Etnográfica. Se celebra en Julio (Carmen) y Noviembre (San Martín). Festejos de gran sabor serrano en el Camero Nuevo que destacan por sus espectaculares pasacalles por su casco histórico colgado de las rocas, jotas montañesas y verbenas lúdicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26113','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Mínimos festejos de alta montaña y marcado carácter ganadero en la falda de San Lorenzo, condicionados por la bajísima demografía, con un almuerzo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26114','fiesta','Fiestas de San Roque i Fiesta del de la Nuez de Pedroso','Gastronómica / Feria Tradicional / Patronal. Se celebra en Agosto (San Roque) y Noviembre (Nuez). Festejos serranos destacados por su feria tradicional dedicada a la nuez de Pedroso con denominación de origen protegida, atrayendo provincialmente mercados artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26115','fiesta','Fiestas de la Virgen de los Remedios','Patronal. Se celebra en Agosto. Mínima expresión festiva de marcado carácter estrictamente familiar en el Camero Nuevo debido a la despoblación, limitada a actos litúrgicos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26117','fiesta','Fiestas de San Ponciano i Fiestas de San Antonio','Patronal / Gastronómica / Taurina. Se celebra en Septiembre (San Ponciano). Festejos multitudinarios de rango comarcal, famosos por sus encierros, suelta de vaquillas populares por las calles y la puesta en valor gastronómica de su cultivo tradicional del champiñón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26118','fiesta','Fiesta de las Almazuelas Colgadas de Pradillo i Fiestas de San Antonio','Etnográfica / Feria de Artesanía / Patronal. Se celebra en Agosto (Almazuelas). Hito etnográfico de primer nivel y fama provincial en Cameros, célebre por vestir de forma masiva los balcones de piedra de la villa con espectaculares tapices de tela artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26119','fiesta','Fiestas del Santo Cristo de la Canal','Patronal / Romería. Se celebra en Septiembre. Festejos locales en el valle del Cidacos que giran en torno a la tradicional andadura procesional hacia la ermita de la Canal, con comidas populares de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26120','fiesta','Fiesta del Pan y del Queso de Quel','Etnográfica / Religiosa / Tradicional. Se celebra en Agosto (Festividad del Cristo de la Transfiguración). Declarada Fiesta de Interés Turístico Regional. Antiquísimo e histórico hito etnográfico de la Rioja Baja donde los miembros de la hermandad lanzan miles de raciones de pan artesanal y queso desde una ermita colgada del acantilado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26121','fiesta','Fiestas en Honor a la Virgen de la Asunción','Patronal. Se celebra en Agosto. Pequeña celebración rural que unifica la escasa población de este núcleo del Camero Viejo en torno a una comida compartida entre los vecinos de la localidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26122','fiesta','Fiestas de la Virgen de las Eras','Patronal / Náutica. Se celebra en Agosto. Festejos tradicionales serranos muy dinamizados por las actividades lúdicas veraniegas en el embalse de González Lacasa, sumando procesiones tradicionales y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26123','fiesta','Fiestas de las Santas Justa y Rufina','Patronal. Se celebra en Julio. Celebración de escala estrictamente local en el valle de Ocón, vertebrada sobre comidas populares de hermandad, tradicionales misas y sesiones de orquesta nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26124','fiesta','Fiestas de San Bartolomé y de la Virgen de la de la Cuesta','Patronal / Etnográfica. Se celebra en Agosto. Festejos patronales tradicionales en la entrada al valle del Leza, caracterizados por el pasacalles folclórico de jotas riojanas, partidos de pelota mano tradicional y degustaciones.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26125','fiesta','Fiestas de la Virgen del Carravieso y de San Miguel','Patronal / Gastronómica / Taurina. Se celebra en Agosto (Carravieso) y Septiembre (San Miguel). Festejos de rango comarcal muy populares en la Rioja Baja, célebres por sus tradicionales e históricos encierros taurinos callejeros, toros ensogaos y la puesta en valor de su pera con D.O.P.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26126','fiesta','Fiestas en Honor a San Miguel Arcángel','Patronal. Se celebra en Septiembre. Festejos de arraigo estrictamente local en el valle del Jubera, condicionados por la baja demografía, sustentados en misas solemnes tradicionales, comidas vecinales de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26128','fiesta','Fiestas de la Virgen de Cillas','Patronal / Histórica. Se celebra en Agosto. Festejos tradicionales de la Rioja Alta que visten de gala su imponente patrimonio y castillo medieval, caracterizados por el regreso estival, bailes populares y comidas vecinales al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26129','fiesta','Batalla del Clarete y Fiestas de la Virgen de la Araña','Enológica / Gastronómica / Patronal. Se celebra en Julio (Batalla) y Septiembre (Patronales). Declarada Fiesta de Interés Turístico de La Rioja. Gran hito enológico de rango autonómico de extraordinaria singularidad, donde miles de personas se arrojan miles de litros de vino clarete en el Barrio de las Bodegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26130','fiesta','Fiestas de San Millán y Santa Gertrudis','Patronal / Histórica. Se celebra en Noviembre. Aunque la villa recibe turismo constante ligado a los Monasterios de Yuso y Suso, sus fiestas patronales conservan el sabor tradicional y comarcal con solemnes misas litúrgicas, jotas y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26131','fiesta','Fiestas de San Millán','Patronal. Se celebra en Noviembre. Pequeña celebración rural condicionada por la baja demografía al límite con Burgos, centrada en ritos religiosos tradicionales, comidas de hermandad y un vermut popular vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26132','fiesta','Fiestas de la Virgen de Valvanera y de San Román','Patronal / Romería / Etnográfica. Se celebra en Agosto. Destacan en el Camero Viejo por la conservación de ritos tradicionales de montaña, procesiones tradicionales, campeonatos locales de cartas tradicionales aragoneses y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26139','fiesta','Fiestas en Honor a San Torcuato','Patronal. Se celebra en Mayo. Festejos de escala estrictamente local en el llano de la Rioja Alta, basados en ritos tradicionales religiosos de primavera, actividades infantiles locales y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26142','fiesta','Los Picaos de San Vicente (Semana Santa y Cruces) y Fiestas de la Virgen de los Remedios','Religiosa / Etnográfica / Patronal. Se celebra en Marzo / Abril (Semana Santa), Mayo, Septiembre (Patronales). Declarada Fiesta de Interés Turístico Nacional. Hito etnográfico y penitencial único en España, famoso por el rito de la flagelación pública de los disciplinantes arropados por un fervor masivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26134','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal. Se celebra en Agosto. Festejos locales de carácter tradicional y familiar en el valle del Yalde, consistentes en pasacalles musicales con agrupaciones locales, campeonatos de guiñote y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26135','fiesta','Fiestas en Honor a Santa Engracia','Patronal. Se celebra en Abril. Pequeñas fiestas de arraigo puramente local que unifican las costumbres de sus diferentes aldeas dispersas mediante verbenas de plaza y tradicionales comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26136','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre. Festejos otoñales mínimos condicionados por la baja demografía en la Rioja Baja, limitados a la santa misa tradicional en su iglesia y encuentros vecinales familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26138','fiesta','Fiestas Patronales de Santo Domingo de la Calzada (Fiestas del Milagro)','Patronal / Histórica / Jacobea / Etnográfica. Se celebra en Mayo. Declarada Fiesta de Interés Turístico Nacional. Grandes festejos de enorme arraigo vinculados al Camino de Santiago, célebres por la procesión del Pan del Santo, las "doncellas" y el recuerdo del milagro del gallo y la gallina vivo en la catedral.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26140','fiesta','Fiestas de San Andrés','Patronal. Se celebra en Noviembre. Festejos patronales tradicionales a los pies de la Sierra de la Demanda, con tradicionales procesiones litúrgicas tradicionales, comidas de hermandad vecinal y música de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26141','fiesta','Fiestas de San Jorge','Patronal. Se celebra en Abril. Pequeña celebración de primavera de marcado ambiente vecinal adaptada a la baja demografía, limitada a misas solemnes tradicionales y comidas comunitarias en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26143','fiesta','Fiestas de la Virgen del Monasterio','Patronal. Se celebra en Septiembre. Festejos de arraigo local tradicionales del llano de Moncalvillo, estructurados con comidas vecinales al aire libre, actividades infantiles y sesiones de baile públicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26144','fiesta','Procesión de las Cien Doncellas y Fiestas de la Virgen de la Hermedaña','Etnográfica / Religiosa / Patronal. Se celebra en Mayo (Doncellas) y Septiembre (Patronales). De enorme relevancia etnográfica provincial por la histórica Procesión de las Cien Doncellas, rito tradicional que conmemora de forma masiva el fin del tributo medieval de las doncellas con desfiles vestidos de blanco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26145','fiesta','Fiestas en Honor a San Martín','Patronal. Se celebra en Noviembre. Festejos otoñales tradicionales basados en la hermandad vecinal, ritos litúrgicos tradicionales, campeonatos de cartas tradicionales aragoneses y orquestas en el local polivalente.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26146','fiesta','Fiestas de la Virgen del Cortijo','Patronal / Etnográfica / Romería. Se celebra en Septiembre. Festejos tradicionales del Camero Viejo que destacan por la romería tradicional a la ermita del Cortijo, las jotas y el reparto de chocolate, aunando identidad y reencuentro veraniego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26147','fiesta','Fiestas de la Virgen del Villar','Patronal. Se celebra en Agosto. Mínimos festejos rurales en una zona del río Leza de baja densidad de población, basados en ritos religiosos tradicionales en su templo y comidas de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26148','fiesta','Fiestas de Nuestra Señora de la Asunción y de San Roque','Patronal / Enológica. Se celebra en Agosto. Festejos de arraigo local tradicionales en la comarca vinícola del río Tirón, caracterizados por los pasacalles populares, el tradicional dance aragonés local recuperado y verbenas de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26149','fiesta','Fiestas en Honor a San Cristóbal','Patronal. Se celebra en Julio. Pequeñas fiestas estivales de marcado ambiente familiar adaptadas al entorno de montaña del Alto Najerilla, con verbenas de plaza mayor y comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26150','fiesta','Fiestas de San Roque y de la Virgen de la Natividad','Patronal. Se celebra en Agosto. Festejos tradicionales del valle del Tirón que dinamizan la población con tradicionales pasacalles, campeonatos lúdicos locales y cenas comunitarias de hermandad al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26153','fiesta','Fiestas de San Borombón','Patronal. Se celebra en Julio. Mínima expresión festiva de carácter estrictamente familiar debido a la extrema despoblación de este núcleo montañés, limitada a una misa tradicional y un almuerzo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26151','fiesta','Fiestas de la Virgen de Tómalos y Fiesta de la Solidaridad','Patronal / Romería / Cultural. Se celebra en Septiembre *. Festejos de rango comarcal consolidados con un potente programa lúdico en la capital del Camero Nuevo, con su concurrida romería tradicional a la ermita, jotas y mercados tradicionales artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26152','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Pequeña festividad local del valle del Tuerto que congrega a los habitantes en torno a una misa solemne tradicional, verbenas populares y actividades infantiles locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26154','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre. Festejos rurales mínimos junto al río Ebro condicionados por la bajísima población del municipio, basados en comidas familiares y ritos religiosos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26155','fiesta','Fiestas de la Virgen de la Junquera','Patronal / Histórica. Se celebra en Septiembre. Festejos tradicionales de la Rioja Alta septentrional, caracterizados por sus pasacalles por el trazado colonial, tradicionales misas cántabras solemnes tradicionales y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26157','fiesta','Fiestas de San Bartolomé (Carreras de Caracoles)','Patronal / Etnográfica / Singular. Se celebra en Agosto. Destaca a nivel provincial y regional por el singular e histórico hito tradicional de sus Carreras de Caracoles arrastrando latas, atrayendo a numeroso público y medios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26160','fiesta','Fiestas de la Virgen del Patrocinio','Patronal / Enológica. Se celebra en Septiembre. Festejos patronales tradicionales del valle de Nájera con alta participación comarcal, pasacalles de gigantes de la zona, degustación de vinos de cooperativa y verbenas de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26161','fiesta','Fiestas en Honor a San Pelayo','Patronal. Se celebra en Junio. Pequeños festejos rurales en una de las zonas de menor población del Alhama-Linares, centrados en el reencuentro vecinal y ritos litúrgicos tradicionales mínimos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26162','fiesta','Fiestas de San Andrés y la Virgen de Tres Fuentes','Patronal / Romería. Se celebra en Agosto. Festejos de montaña en el valle de Ojacastro potenciados por el turismo rural veraniego, con concurrida romería tradicional, cenas populares al aire libre y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26164','fiesta','Fiestas de la Virgen de Villa rrica','Patronal / Etnográfica. Se celebra en Agosto. Festejos tradicionales de la alta montaña riojana en las Cuencas del Najerilla, destacados por su folclore pastoril serrano, bailes populares y comidas de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26165','fiesta','Fiestas de San Esteban y de la Virgen del Rosario','Patronal / Etnográfica. Se celebra en Agosto. Celebración tradicional en el valle del Iregua bajo sus colosales peñas monumentales, con pasacalles musicales locales, bailes tradicionales y activa participación de las peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26166','fiesta','Fiestas de la Virgen de los Remedios','Patronal / Enológica. Se celebra en Septiembre. Festejos tradicionales en las faldas de los Montes Obarenes vinculados a la cultura vinícola lindante con Haro, con comidas populares al aire libre y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26167','fiesta','Fiestas de San Peregrín','Patronal. Se celebra en Agosto. Celebración de escala estrictamente local en el valle del Oja, vertebrada sobre comidas populares de hermandad vecinal, ritos litúrgicos tradicionales y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26168','fiesta','Fiestas de Santa Eufemia y de San Asensio','Patronal / Cultural. Se celebra en Septiembre. Festejos de ámbito metropolitano en el área residencial de Logroño con notable dinamismo juvenil, caracterizados por grandes conciertos, pasacalles de gigantes de la zona y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26169','fiesta','Fiestas de la Virgen de los Nogales','Patronal / Romería. Se celebra en Agosto. Festejos estivales a orillas del embalse de González Lacasa, orientados a la reunión familiar y de veraneantes con comidas de hermandad tradicionales y música de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26170','fiesta','Fiestas de la Virgen de la Anunciación','Patronal / Enológica. Se celebra en Septiembre. Festejos de arraigo tradicional en la Rioja Baja, caracterizados por el desfile de carrozas populares, degustaciones de vinos locales de cooperativa y verbenas de noche.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26171','fiesta','Fiestas de San Juan Bautista y San Juanito','Patronal. Se celebra en Junio. Pequeños festejos tradicionales de verano en la cuenca del río Cárdenas, basados en ritos tradicionales litúrgicos, juegos infantiles y sesiones de orquesta nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26172','fiesta','Fiestas en Honor a San Juan','Patronal. Se celebra en Junio. Festejos rurales mínimos en la comarca de Nájera de baja densidad demográfica, basados en ritos religiosos tradicionales, comidas familiares y pequeñas orquestas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26173','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Mínima expresión festiva de carácter estrictamente vecinal y de baja demografía en el Cidacos, limitada a la santa misa tradicional y vermut popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26174','fiesta','Fiestas de Santa Columba','Patronal. Se celebra en Agosto. Festejos que unifican las costumbres de sus tres núcleos residenciales fronterizos con Burgos mediante verbenas de plaza mayor y juegos populares locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26175','fiesta','Fiestas de Santa Áurea','Patronal / Etnográfica. Se celebra en Agosto. Celebración serrana en el Alto Najerilla de gran valor identitario, célebre por los dances tradicionales aragoneses en honor a la santa nativa de la villa, jotas y comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26176','fiesta','Fiestas de San Antón','Patronal. Se celebra en Enero. Pequeña celebración de invierno de marcado carácter vecinal y familiar en la Rioja Alta, centrada en el encendido de hogueras tradicionales y misas Solemnes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26177','fiesta','Fiesta de la Caridad Grande en el Instituto de la Virgen de Lomos de Orios','Romería / Etnográfica / Patronal. Se celebra en Julio (Caridad) y Agosto (Fiestas). Hito tradicional de gran renombre provincial en la alta montaña de los Cameros, célebre por la romería tradicional y el reparto masivo de pan y carne bendecidos desde la ermita.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26180','fiesta','Fiestas de la Virgen de la Asunción y de San Roque (Danzas de Zarratón)','Patronal / Etnográfica. Se celebra en Agosto. Festejos de gran renombre provincial por poseer uno de los grupos de dances tradicionales tradicionales más antiguos de La Rioja, ejecutando mudanzas de palos de altísimo valor folclórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26181','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Mínimos festejos de carácter vecinal debido a la extrema despoblación de este núcleo montañés del Jubera, limitados a actos religiosos solemnes tradicionales y un vermut popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26183','fiesta','Fiestas de San Vitores','Patronal / Romería. Se celebra en Agosto. Pequeñas fiestas de arraigo puramente local al pie de Valdezcaray, estructuradas con romería tradicional, campeonatos de cartas tradicionales aragoneses y cenas de hermandad para el vecindario). Hemos completado al 100% de forma exhaustiva todos los municipios de la provincia de La Rioja, finalizando así por completo la totalidad de esta Comunidad Autónoma uniprovincial. ¿Deseas que avancemos de inmediato abriendo la siguiente Comunidad Autónoma de la lista oficial, que corresponde a la Comunidad Foral de Navarra (comenzando por su primer bloque de municipios de la A hasta la I)?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90704','fiesta','Fiestas en Honor a San Vicente','Patronal. Se celebra en Agosto. Festejos patronales de arraigo estrictamente local en Tierra Estella, caracterizados por el retorno veraniego de familias, comidas populares y verbenas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33001','fiesta','Fiestas de la Virgen del Rosario','Patronal / Etnográfica. Se celebra en Agosto. Festejos locales al pie de la sierra de Urbasa con notable dinamismo, destacando el volteo tradicional de campanas, pasacalles con txistularis y el Baile de la Era tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90705','fiesta','Fiestas de San Pedro','Patronal. Se celebra en Septiembre. Pequeña celebración vecinal condicionada por la baja demografía en el Valle de Aézcoa, vertebrada en torno a la santa misa tradicional y comidas de hermandad en el local social.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90706','fiesta','Fiestas de San Martín','Patronal. Se celebra en Septiembre. Mínimos festejos tradicionales de carácter vecinal y familiar debido a la escasa población del Pirineo navarro, centrados en actos religiosos tradicionales y una comida compartida.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90707','fiesta','Fiestas de San Juan Bautista (celebradas en Muniáin de Aberin)','Patronal. Se celebra en Agosto. Festejos de escala estrictamente local que unifican las tradiciones de sus núcleos poblacionales, con cenas vecinales al aire libre, orquestas de plaza y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90708','fiesta','Fiestas de la Virgen del Rosario (El Lanzamiento de Peras) y Fiestas de Santa María Magdalena','Patronal / Etnográfica / Singular. Se celebra en Julio (Magdalena) y Septiembre (Rosario). Festejos de rango comarcal en la Ribera Alta de Navarra que destacan por el singular e histórico rito etnográfico del lanzamiento masivo de peras desde el balcón del antiguo castillo fortificado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90709','fiesta','Fiestas en Honor a San Andrés','Patronal. Se celebra en Agosto. Celebración trasladada de época veraniega para asegurar la concurrencia en Valdizarbe, basada en torneos lúdicos de cartas tradicionales, comidas de hermandad y sesiones de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90710','fiesta','Fiestas de la Virgen de la Compasión','Patronal / Romería. Se celebra en Septiembre. Festejos locales que giran en torno a la romería tradicional al cercano Santuario de Nuestra Señora de Codés, aunando el fervor comarcal con verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90711','fiesta','Fiestas de San Roque','Patronal / Etnográfica. Se celebra en Agosto. Celebración tradicional con notable dinamismo en la comarca de Sangüesa, caracterizada por las rondas populares por su monumental villa medieval, pasacalles de gigantes y toricos de fuego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90712','fiesta','Fiestas del Valle de Allín','Patronal / Valle. Se celebra en Agosto. Festejos conjuntos que unifican las costumbres tradicionales de los numerosos núcleos dispersos de este término de Tierra Estella, con verbenas rotativas y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90713','fiesta','Fiestas de la Virgen de la Blasa','Patronal / Etnográfica. Se celebra en Agosto. Festejos tradicionales con pasacalles de su colla de gigantes comarcales, encierros infantiles, bailes populares y cenas de hermandad vecinal en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33002','fiesta','Carnaval de Alsasua (Momotxorros) y Fiestas de la Virgen de la Encontrada','Etnográfica / Carnaval Tradicional / Patronal. Se celebra en Febrero (Carnaval) y Septiembre (Fiestas). Declarada Fiesta de Interés Turístico de Navarra. Hito etnográfico absoluto de los carnavales tradicionales de España, célebre por el desfile mitológico de los Momotxorros con cuernos y sangre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90714','fiesta','Fiestas de la Virgen de la Asunción (reunidas en Zudaire)','Patronal / Valle. Se celebra en Agosto. Festejos tradicionales de montaña a las puertas de Urbasa, que combinan las misas solemnes tradicionales con partidos de pelota a mano, música de acordeón y comidas campestres.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90715','fiesta','Fiestas de San Fausto','Patronal. Se celebra en Octubre (trasladadas parcialmente a Agosto). Festejos de escala estrictamente local en el valle de Ega, vertebrados sobre actividades infantiles locales, campeonatos de guiñote y orquestas populares de noche.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90716','fiesta','Fiestas de la Virgen de la Cerca y Mercado Medieval','Patronal / Taurina / Recreación. Se celebra en Septiembre. Festejos con gran rango y arraigo comarcal en la Ribera, célebres por sus tradicionales e históricos encierros taurinos por las calles empinadas, vacas en la plaza y un concurrido mercado medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90717','fiesta','Fiestas de Ansoáin','Patronal / Cultural / Urbana. Se celebra en Septiembre. Festejos del área metropolitana de Pamplona con un potente programa lúdico de notable dinamismo juvenil, caracterizados por pasacalles de su comparsa de gigantes, dantzaris y txoznas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90718','fiesta','Fiestas de Olagüe y del Valle de Anue','Patronal / Valles. Se celebra en Agosto. Pequeña festividad local de montaña que congrega a los habitantes de sus pueblos dispersos en torno a misas Solemnes, bailes populares tradicionales vascos y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90719','fiesta','Fiestas en Honor a la Virgen de la Asunción','Patronal / Enológica. Se celebra en Agosto. Festejos tradicionales vinculados a la cultura vinícola de Valdizarbe, consistentes en pasacalles musicales locales con agrupaciones, catas de vino nuevo y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33003','fiesta','Fiestas de San Miguel y Carnaval de Aoiz (Cascabobos)','Patronal / Etnográfica / Carnaval Tradicional. Se celebra en Febrero (Carnaval) y Agosto (Fiestas). Destaca provincialmente por su carnaval tradicional con los personajes de Cascabobos y Mascaritas, así como sus fiestas mayores con su mítica e histórica danza de la costilla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31020','fiesta','Fiestas de las localidades del Valle de Araitz','Patronal / Valle. Se celebra en Agosto. Festejos rurales de montaña bajo los imponentes Mallos de Aralar, basados en ritos litúrgicos tradicionales, demostraciones de deporte rural vasco —herri kirolak— y comidas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90721','fiesta','Fiestas de la Trinidad de Erroz y del Valle','Patronal / Romería. Se celebra en Junio y Agosto. Festejos unificados de la Sakana oriental que unifican las costumbres de sus pedanías dispersas mediante verbenas de plaza y tradicionales comidas de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31021','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Mínimos festejos de ámbito estrictamente vecinal y de baja demografía en el Valle de Améscoa, limitados a actos religiosos solemnes tradicionales y una merienda popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31023','fiesta','Fiestas del Valle de Aranguren (celebradas en Mutilva)','Patronal / Cultural / Urbana. Se celebra en Septiembre. Festejos que han crecido exponencialmente en paralelo a su expansión demográfica periurbana, dotados de pasacalles de gigantes de la zona, dantzaris, comidas populares y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31024','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Festejos tradicionales de alta montaña en el límite con Guipúzcoa, caracterizados por partidos de pelota en su singular frontón, cantos tradicionales vascos y cenas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90720','fiesta','Fiestas de Nuestra Señora de la Asunción *','Patronal / Etnográfica *. Se celebra en Agosto *. Festejos de las Cinco Villas de la Montaña con gran sabor tradicional, destacados por la exhibición de danzas folclóricas locales, competiciones de herri kirolak y verbenas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31026','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Pequeña celebración veraniega de carácter local y vecinal en los límites con La Rioja, sustentada en ritos litúrgicos tradicionales, juegos de naipes y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31027','fiesta','Fiestas de San Juan (Festa de los Oficios Tradicionales)','Patronal / Etnográfica. Se celebra en Junio. Festejos en la Sakana con notable raigambre, célebres por la hoguera de San Juan, el canto tradicional de coplas vascas, herri kirolak y comidas colectivas basadas en la gastronomía local chacinera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31028','fiesta','Romería de la Virgen de Arce y Fiestas de Nagore','Romería / Patronal. Se celebra en Mayo (Romería) y Septiembre (Fiestas). Festejos de un inmenso valle pirenaico de muy baja densidad de población, centrados en la romería tradicional a la ermita de Arce con cantos y comidas vecinales de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31030','fiesta','Fiestas de San Román','Patronal / Romería. Se celebra en Agosto. Festejos estivales al pie de la Solana de Tierra Estella, consistentes en la romería a la ermita de la Virgen de Unzizu, juegos infantiles tradicionales y orquestas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31031','fiesta','Fiestas de la Asunción de la Virgen','Patronal. Se celebra en Agosto. Celebración de montaña en el valle de Leitzaran, fundamentada en partidos de pelota a mano, pasacalles tradicionales vascos, comidas populares y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31032','fiesta','Fiestas de San Esteban (Encierro del Estrecho)','Patronal / Taurina / Etnográfica. Se celebra en Agosto. Destaca a nivel provincial y regional por el espectacular y arriesgado hito tradicional del "Encierro del Estrecho", donde las vacas corren desbocadas por un angosto tramo de tierra batida.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31033','fiesta','Fiestas de San Andrés','Patronal. Se celebra en Septiembre (trasladadas parcialmente a Verano). Pequeñas fiestas estivales de marcado ambiente familiar adaptadas a la bajísima demografía del Valle de Aézcoa, con ritos religiosos tradicionales mínimos y almuerzo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90722','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Festejos veraniegos en la capital histórica de Aézcoa a orillas del río Irati, orientados a la reunión de veraneantes con comidas comunitarias de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31035','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Mínimos festejos de carácter vecinal estrictamente familiar condicionados por la despoblación en la frontera con Álava, limitados a actos litúrgicos tradicionales y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31036','fiesta','Día de la Tostada (Fiesta del Aceite de Arróniz) y Fiestas de Nuestra Señora de Mendía','Gastronómica / Feria de Sector / Patronal / Romería. Se celebra en Febrero (Tostada) y Septiembre (Patronales). Declarada Fiesta de Interés Turístico de Navarra. Gran hito de la gastronomía de Tierra Estella que exalta la elaboración artesanal del aceite de oliva virgen extra con mercado y degustaciones.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31037','fiesta','Fiestas de San Pedro','Patronal. Se celebra en Junio. Festejos rurales mínimos en la Sakana occidental debido a la reducida población residente, centrados en una misa tradicional y cenas populares compartidas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31038','fiesta','Fiestas de la Virgen de la Jauría y Encuentro de de de Carreras de Layas','Patronal / Histórica / Etnográfica / Singular. Se celebra en Septiembre (Fiestas) y Noviembre (Layas). Festejos de gran empaque provincial; destaca de forma monumental por el espectacular hito tradicional de las Carreras de Layas por las cuestas de su imponente cerco amurallado medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31039','fiesta','Fiestas de San Miguel','Patronal. Se celebra en Septiembre. Pequeña festividad local de Valdizarbe que congrega a los habitantes en torno a una misa solemne tradicional, comidas populares de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31040','fiesta','Fiestas de las pedanías del Valle de Atez','Patronal / Valle. Se celebra en Septiembre. Pequeñas fiestas de marcado ambiente vecinal adaptadas a los pequeños núcleos dispersos del término rural de Ulzama, con un programa lúdico básico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31041','fiesta','Fiestas de San Joaquín y la Virgen del Rosario','Patronal / Cultural / Jacobea. Se celebra en Septiembre. Festejos muy vinculados al histórico Monasterio de Irache y la ruta jacobea, caracterizados por pasacalles de gigantes de la comarca, correfocs de diablos, conciertos y degustaciones.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31042','fiesta','Fiestas de la Virgen del Olmo','Patronal / Taurina / Etnográfica. Se celebra en Septiembre. Festejos de gran arraigo comarcal en la Ribera, renombrados por la espectacularidad de sus encierros de reses bravas por las calles coloniales, grandes orquestas y su activo ambiente de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31043','fiesta','Fiestas de San Arsenio y de Santa Engracia','Patronal / Romería. Se celebra en Agosto. Festejos rurales mínimos distribuidos alrededor de su monasterio histórico románico del siglo X, centrados en el reencuentro veraniego y ritos tradicionales familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90723','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Celebración de escala estrictamente local en el corredor de la Sakana, vertebrada sobre partidos de pelota a mano, pasacalles vascos tradicionales y cenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31045','fiesta','Fiestas de San Bartolomé','Patronal / Etnográfica. Se celebra en Agosto. Festejos de arraigo tradicional en la Valdorba, caracterizados por los pasacalles musicales con gigantes, tradicionales misas cántabras y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31046','fiesta','Fiestas en Honor a San Jorge','Patronal. Se celebra en Agosto (Adelantadas de época). Mínimos festejos de marcado carácter familiar orientados al reencuentro de familias emigradas en un municipio de muy baja densidad demográfica en la comarca de Estella.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31047','fiesta','Semana de la Brujería de Bargota y Fiestas de la Virgen del Poyo','Etnográfica / Recreación Histórica / Patronal. Se celebra en Julio (Brujería) y Septiembre (Patronales). Gran reclamo a nivel provincial sustentado en el misticismo del histórico Brujo Johanes de Bargota, incluyendo la recreación de aquelarres, mercadillos esotéricos medievales y leyendas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31048','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Agosto. Pequeña celebración de verano en el entorno de la Ribera Baja junto a Cascante, sustentada en ritos religiosos tradicionales, juegos infantiles y cenas vecinales de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90724','fiesta','Festa Major de Basaburua / Basaburuko Bestak','Patronal / Etnográfica. Se celebra en Agosto. Festejos de valle de marcado carácter vecinal que unifican la identidad de sus numerosos concejos, destacando los campeonatos de pelota mano, bailes tradicionales y música de txistu.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31050','fiesta','Fiestas de Santiago en Elizondo y Baztandarren Biltzarra','Etnográfica / Cultural / Folclórica. Se celebra en Julio. Declarada Fiesta de Interés Turístico de Navarra. Hito etnográfico masivo del Pirineo que congrega en Elizondo a los quince pueblos del valle con desfiles de carrozas tradicionales, mutildantzak y ferias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31137','fiesta','Bestak de Beintza-Labaien','Patronal. Se celebra en Agosto. Pequeña celebración rural en Malerreka con baja demografía, basada en ritos litúrgicos tradicionales, deporte rural vasco lúdico (herri kirolak) y comidas populares de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31051','fiesta','Fiestas en Honor a San Roque','Patronal. Se celebra en Agosto. Festejos tradicionales de carácter familiar en la Merindad de Olite, consistentes en pasacalles musicales locales, campeonatos de cartas y verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31052','fiesta','Fiestas en Honor a la Virgen de la Asunción','Patronal. Se celebra en Agosto. Celebración de escala estrictamente local en el valle de Echauri, estructurada sobre la santa misa tradicional, juegos infantiles y cenas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31053','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal / Taurina. Se celebra en Agosto. Festejos de fuerte arraigo en la Ribera Alta, caracterizados por sus tradicionales encierros de vaquillas por las calles, jotas navarras, comidas populares y alta participación de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31902','fiesta','Fiestas Patronales de Berrioplano','Patronal / Cultural. Se celebra en Septiembre. Festejos de ámbito periurbano en la comarca de Pamplona que unifican las costumbres de sus concejos con conciertos, pasacalles de gigantes de la comarca y actividades infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31903','fiesta','Fiestas de Berriozar','Patronal / Cultural. Se celebra en Agosto. Festejos de rango comarcal consolidados con un potente programa lúdico en el área metropolitana, dotados de populosos pasacalles de su comparsa de gigantes, correfocs y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31054','fiesta','Fiestas Patronales de Bertizarana (Narbarte, Legasa y Oieregi)','Patronal / Romería. Se celebra en Julio y Agosto. Festejos tradicionales junto al entorno del Parque Natural del Señorío de Bértiz, que unifican las costumbres de sus tres núcleos con música folclórica y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31055','fiesta','Bestak de Betelu','Patronal / Etnográfica. Se celebra en Agosto. Festejos tradicionales en el valle de Araitz potenciados históricamente por su entorno balneario, combinando misas solemnes tradicionales con exhibiciones de pelota mano y música local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31056','fiesta','Fiestas Patronales en Honor a San Pedro','Patronal. Se celebra en Junio. Pequeña celebración vecinal condicionada por la baja demografía en Valdizarbe, vertebrada en torno a actos religiosos tradicionales y comidas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31057','fiesta','Fiestas de Santa Ana y Fiestas en Honor a San Antón','Patronal / Taurina. Se celebra en Enero (San Antón) y Agosto (Santa Ana). Festejos de gran renombre comarcal en la Ribera de Navarra, célebres por sus encierros, suelta de vaquillas populares en la calle y la tradicional hoguera invernal de San Antón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33005','fiesta','Fiestas de San Juan Bautista','Patronal / Jacobea / Etnográfica. Se celebra en Junio. Aunque el enclave recibe turismo jacobeo continuo por su cercanía a Roncesvalles, sus fiestas patronales conservan un hondo valor tradicional con hogueras de San Juan, jotas de la zona y comidas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31061','fiesta','Fiestas de San Andrés','Patronal. Se celebra en Agosto. Mínimas fiestas de marcado carácter familiar orientadas al reencuentro veraniego de familias en una zona de muy baja densidad demográfica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31062','fiesta','Fiestas de San Roque y Fiestas de San Sebastián (Paloteado de Cabanillas)','Patronal / Etnográfica / Taurina. Se celebra en Enero y Agosto. Destaca en la Ribera por la conservación de su espectacular e histórico Paloteado de Cabanillas, un hito etnográfico que combina danzas de palos, dichos críticos populares y versos satíricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31063','fiesta','Fiestas de San Simeón Labrador','Patronal. Se celebra en Septiembre. Pequeña festividad rural que unifica la escasa población de este núcleo en torno a ritos religiosos tradicionales, comidas de hermandad y un vermut popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31064','fiesta','Fiestas en Honor a San Miguel y Día del Tomate','Patronal / Gastronómica / Taurina. Se celebra en Agosto. Festejos de gran arraigo en la Ribera Alta, célebres por la promoción agrícola de su famoso tomate con degustaciones masivas, encierros de vaquillas populares y verbenas lúdicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31065','fiesta','Fiestas de Santa Fe','Patronal / Taurina. Se celebra en Septiembre. Festejos de rango comarcal muy populares en la cuenca del Aragón, caracterizados por sus tradicionales encierros taurinos por las empinadas calles, pasacalles folclóricos y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31066','fiesta','Fiestas en Honor a la Virgen de la Gracia y del Salvador','Patronal / Taurina. Se celebra en Septiembre. Celebración de la Ribera Alta con tradicionales encierros y suelta de reses bravas por el casco urbano, jotas navarras y cenas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31067','fiesta','Fiestas de la Virgen del Rosario','Patronal / Taurina / Romería. Se celebra en Agosto y Septiembre. Festejos locales vinculados al marco histórico del Monasterio de la Oliva, destacados por su concurrida feria taurina, encierros por las calles del pueblo y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31068','fiesta','Fiestas de la Virgen del Romero','Patronal / Etnográfica / Taurina. Se celebra en Septiembre. Festejos con notable arraigo comarcal, célebres por la espectacular bajada de la Virgen desde el santuario columnado, encierros tradicionales y un amplísimo programa lúdico peñista.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31069','fiesta','Fiestas en Honor a las Santes Reliquias','Patronal / Etnográfica. Se celebra en Agosto. Festejos de arraigo local tradicionales en la Merindad de Sangüesa con pasacalles musicales, bailes de gigantes locales y una activa participación vecinal en las cenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31070','fiesta','Fiestas de la Virgen del Amparo','Patronal / Taurina / Cultural. Se celebra en Junio. Festejos de gran dinamismo en este nudo ferroviario histórico de la Ribera, caracterizados por encierros de vaquillas populares en la plaza, pasacalles de gigantes y peñas juveniles masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31071','fiesta','Fiestas de San Martín','Patronal. Se celebra en Septiembre. Mínimos festejos de carácter vecinal estrictamente familiar debido a la bajísima población del municipio, limitada a una misa tradicional y vermut popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31072','fiesta','Fiestas de la Virgen de la Paz (La Traída de los Gigantes)','Patronal / Etnográfica / Taurina. Se celebra en Septiembre *. Grandes fiestas de la Ribera Alta, célebres por el espectacular e histórico rito etnográfico de la "Traída de los Gigantes", encierros taurinos populares de alta raigambre y masivos recintos de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31074','fiesta','Fiestas en Honor a San Román','Patronal / Jacobea. Se celebra en Septiembre. Festejos tradicionales en el Camino de Santiago, destacados por sus pasacalles por la monumental villa medieval, rondas folclóricas de jotas navarras y verbenas de noche.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31075','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre. Pequeñas fiestas de arraigo puramente local en el valle de Echauri con ritos religiosos tradicionales, campeonatos de cartas y orquestas reducidas adaptadas a la baja demografía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90732','fiesta','Fiestas Patronales de Cizur Menor','Patronal / Cultural. Se celebra en Septiembre. Festejos que unifican las tradiciones de los núcleos residenciales de la comarca de Pamplona con un potente programa lúdico para el vecindario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31077','fiesta','Fiestas de San Miguel y la Virgen de la Merced (Semana Santa de Corella)','Religiosa / Etnográfica / Taurina / Patronal. Se celebra en Marzo / Abril (Semana Santa) y Septiembre (Patronales). Su procesión barroca de Semana Santa está declarada de Interés Turístico por su extraordinario valor histórico con pasos vivientes, combinándose en fiestas con una reputada feria taurina.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31078','fiesta','Fiestas de San Miguel (Paloteado de Cortes)','Etnográfica / Danza Tradicional / Patronal. Se celebra en Septiembre. Declarada Fiesta de Interés Turístico de Navarra. Hito etnográfico absoluto de la Ribera, famoso por la magnífica ejecución del histórico Paloteado y baile de cintas con versos populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31079','fiesta','Fiestas de la Virgen de la Piedad','Patronal. Se celebra en Agosto. Pequeña celebración veraniega de carácter vecinal e infantil centrada en comidas comunitarias de hermandad y música nocturna en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31080','fiesta','Feria del Espárrago de Dicastillo y Fiestas de la Virgen de la Nieva','Gastronómica / Feria Tradicional / Patronal. Se celebra en Mayo (Espárrago) y Agosto (Fiestas). Su feria gastronómica primaveral dedicada al espárrago de Navarra con D.O.P. posee rango provincial de alta popularidad, atrayendo mercados de artesanía y catas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31081','fiesta','Bestak de Donamaria','Patronal. Se celebra en Agosto. Festejos tradicionales de montaña en Malerreka a la sombra de su torre defensiva medieval, basados en comidas de hermandad, música tradicionales de txistu y pelota.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31221','fiesta','Fiestas Patronales de San Pedro (Trapatan)','Patronal / Etnográfica / Danza Tradicional. Se celebra en Junio. Festejos de gran personalidad en la comarca de Alto Bidasoa, célebres por la espectacular y solemne ejecución de la mítica danza tradicional del "Trapatan" por parte de los mozos, un elemento folclórico de altísima raigambre regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31083','fiesta','Fiestas de San Vicente','Patronal. Se celebra en Agosto. Pequeñas fiestas estivales en una localidad de baja demografía del valle de Echauri, limitadas a ritos religiosos tradicionales y vermut vecinal comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90933','fiesta','Fiestas Patronales en Honor a la Virgen de la Asunción','Patronal / Etnográfica. Se celebra en Agosto. Festejos de gran arraigo en la comarca de Sakana, caracterizados por el tradicional día de las peñas, exhibiciones de herri kirolak como corte de troncos, dantzas tradicionales y verbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90725','fiesta','Fiestas de San Eulogio y Feria de la Cereza de Etxauri','Gastronómica / Patronal. Se celebra en Junio (Cereza) y Agosto (Fiestas). Festejos que combinan su identidad local con la feria dedicada a su afamada cereza autóctona, atrayendo a numeroso público provincial para degustaciones y mercados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31086','fiesta','Fiestas de Olaz y Sarriguren','Patronal / Cultural / Urbana. Se celebra en Junio y Septiembre. Festejos que han crecido en paralelo a su gran afluencia residencial metropolitana, dotados de conciertos públicos, comparsa de gigantes y activos correfocs de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31087','fiesta','Fiesta del Balneario y Fiestas Patronales','Patronal / Etnográfica. Se celebra en Julio. Festejos locales tradicionales en Malerreka dinamizados por la presencia de su histórico manantial salino, con comidas vecinales, pelota mano y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31089','fiesta','Fiestas en Honor a los Santos Audaz y Garrido','Patronal / Romería. Se celebra en Agosto. Celebración de escala local en Valdizarbe, vertebrada sobre romerías tradicionales a las ermitas del entorno jacobeo, con verbenas nocturnas al aire libre y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31090','fiesta','Bestak de Eratsun','Patronal. Se celebra en Septiembre. Festejos rurales mínimos en las laderas montañosas del norte provincial, basados en ritos religiosos tradicionales en su templo, comidas familiares y música tradicional local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31091','fiesta','Fiestas del Valle de Ergoiena (Lizarraga, Unanu y Dorrao)','Patronal / Etnográfica. Se celebra en Agosto. Festejos tradicionales que unifican las costumbres de sus tres núcleos serranos bajo la sierra de Urbasa, destacando el mantenimiento de sus espectaculares máscaras de carnaval local en actos folclóricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31092','fiesta','Fiestas del Valle de Erro','Patronal / Romería. Se celebra en Agosto. Festejos del Pirineo occidental que reúnen a sus concejos en torno a romerías tradicionales en las praderías del valle, con bailes populares y música de acordeón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31094','fiesta','Fiestas en Honor a San Miguel','Patronal. Se celebra en Septiembre. Pequeña festividad local de la comarca de Sangüesa que congrega a los habitantes en torno a una misa solemne tradicional, comidas populares de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31095','fiesta','Fiestas Patronales del Valle de Salazar','Patronal / Etnográfica. Se celebra en Agosto. Destacan en el Valle de Salazar por la conservación de sus dances pirenaicos tradicionales ejecutados con trajes de gala salacencos, aunando fervor e identidad rural de montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31096','fiesta','Fiestas en Honor a San Vicente Mártir','Patronal. Se celebra en Agosto. Pequeñas fiestas estivales de carácter vecinal desplazadas al mes veraniego para asegurar el reencuentro de familias emigradas a la Rioja Alavesa condicionado por la baja demografía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33007','fiesta','Fiestas de Estella en Honor a San Andrés y la Virgen del Puy','Patronal / Taurina / Etnográfica / Jacobea. Se celebra en Julio / Agosto. Declaradas de gran relevancia etnográfica provincial y regional. Espectaculares e históricas fiestas mayores de enorme arraigo jacobeo, célebres por su Pañuelico, masiva feria taurina de encierros y la Bajada del Puy.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31098','fiesta','Fiestas de Zubiri y del Valle de Esteribar','Patronal / Jacobea. Se celebra en Agosto. Festejos de arraigo tradicional en el corredor del río Arga que dinamizan su capitalidad en Zubiri con conciertos públicos, campeonatos lúdicos de herri kirolak y verbenas de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31099','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Mínimos festejos de ámbito estrictamente vecinal condicionados por la despoblación en Tierra Estella, limitados a actos religiosos tradicionales y cenas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90726','fiesta','Fiestas Patronales de la Asunción y la Tradición de las Palomeras de Etxalar','Patronal / Etnográfica / Cinegética. Se celebra en Agosto (Fiestas) y Octubre/ Noviembre (Palomeras). Festejos de hondo calado tradicional en las Cinco Villas de la Montaña. Destaca a nivel provincial por el milenario hito etnográfico de la caza de palomas con redes, un método único que atrae a numerosos visitantes en otoño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31100','fiesta','Fiestas en Honor a San Martín','Patronal. Se celebra en Agosto. Festejos trasladados al mes estival para asegurar la concurrencia de familias originarias de Améscoa, basados en verbenas de plaza, campeonatos de mus y actos litúrgicos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31101','fiesta','Fiestas Patronales de Oricáin','Patronal. Se celebra en Septiembre. Festejos de escala estrictamente local en el valle, unificando a sus pequeños núcleos en torno a procesiones tradicionales, comidas populares al aire libre y música nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31093','fiesta','Fiestas de San Román','Patronal / Etnográfica. Se celebra en Agosto. Celebración de la capital del Valle de Salazar, de fuerte identidad pirenaica, destacada por sus solemnes bailes tradicionales al son de los txistularis y el reencuentro veraniego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90934','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Pequeña celebración vecinal condicionada por la baja demografía en la comarca de Alto Bidasoa, centrada en comidas comunitarias de hermandad, partidos de pelota a mano y verbenas íntimas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31103','fiesta','Fiestas de San Esteban en Ayesa','Patronal. Se celebra en Septiembre. Mínima expresión festiva de carácter familiar en la comarca de Sangüesa debido a la dispersión y baja población de sus núcleos, limitada a una misa solemne y vermut vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31104','fiesta','Fiestas Patronales de la Virgen de Nieva (El Encierro del Pilón)','Patronal / Taurina / Etnográfica. Se celebra en Agosto. Declarada Fiesta de Interés Turístico de Navarra. Espectacular hito taurino de rango autonómico de extraordinaria singularidad, donde los mozos corren los toros bajando por una empinada e impresionante ladera escarpada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31105','fiesta','Fiestas del Barranco en Honor a la Virgen de la Barda','Patronal / Taurina. Se celebra en Septiembre. Festejos de rango comarcal consolidados en la Ribera Alta, célebres por su activa tradición taurina con encierros, capeas, desfiles de peñas populares y la procesión solemne junto al monasterio cisterciense.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31106','fiesta','Fiestas Patronales de la Virgen del Rosario','Patronal / Taurina. Se celebra en Septiembre. Festejos tradicionales de la Ribera Baja del Ebro con suelta de vaquillas por el casco urbano, cenas populares de hermandad vecinal, pasacalles y orquestas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31107','fiesta','Fiestas en Honor a Santiago Apóstol','Patronal / Taurina. Se celebra en Agosto. Festejos con notable concurrencia en la Ribera Alta, caracterizados por sus populosos encierros de reses bravas por las calles, el tradicional chupinazo de peñas y sesiones masivas de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31109','fiesta','Fiestas Patronales de Cordovilla','Patronal. Se celebra en Junio. Festejos tradicionales de la Cuna de Pamplona potenciados por su cercanía al área metropolitana, con actividades lúdicas infantiles, comidas populares y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31110','fiesta','Fiestas de San Pedro y de la Virgen del Amparo','Patronal / Histórica. Se celebra en Agosto. Festejos veraniegos marcados por el marco monumental de su villa medieval encaramada sobre el río Aragón, combinando ritos litúrgicos tradicionales con cenas vecinales al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31111','fiesta','Fiestas de San Vicente','Patronal. Se celebra en Agosto. Pequeña celebración rural que unifica la escasa población de los pequeños núcleos dispersos del Valle de Salazar, centrada en comidas comunitarias de hermandad y ritos religiosos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90935','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Festejos estivales tradicionales del Valle de Aezkoa basados en el reencuentro de familias veraneantes, comidas populares, música tradicional de acordeón pirenaico y partidos de pelota.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31113','fiesta','Fiestas Patronales de Santiago Apóstol','Patronal / Etnográfica. Se celebra en Julio. Festejos de fuerte arraigo e identidad en el Valle de Roncal, con la conservación de tradiciones serranas e indumentaria típica, música de txistularis y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31114','fiesta','Fiestas de la Virgen de la Blanca','Patronal. Se celebra en Agosto. Celebración tradicional en la Valdorba de carácter local, con solemnes actos religiosos tradicionales, competiciones lúdicas, orquestas de noche en la plaza y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31115','fiesta','Fiestas Patronales de San Juan Bautista','Patronal. Se celebra en Junio. Pequeñas fiestas estivales de marcado ambiente familiar en el Pirineo, con encendido de hogueras tradicionales de San Juan, comidas comunitarias de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31116','fiesta','Fiestas en Honor a la Virgen del Puerto','Patronal. Se celebra en Agosto. Mínimos festejos de carácter vecinal al límite con Álava condicionados por la baja demografía, limitados a actos litúrgicos tradicionales, campeonatos de mus y cenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31117','fiesta','Fiestas de la Virgen de la Asunción (Zaharagi Dantza)','Patronal / Etnográfica / Danza Tradicional. Se celebra en Agosto. Destaca a nivel provincial por el espectacular hito etnográfico de la "Zaharagi Dantza" o danza del odre, donde los carboneros tiznados bailan persiguiendo a los asistentes, una muestra de alto valor folclórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31118','fiesta','Fiestas de San Antonio en Aizpún','Patronal. Se celebra en Junio. Pequeñas fiestas de montaña en el valle, caracterizadas por ritos tradicionales religiosos, juegos infantiles tradicionales de la zona y comidas de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31119','fiesta','Fiestas de San Esteban','Patronal. Se celebra en Agosto. Festejos rurales mínimos en una de las zonas de menor población del Pirineo navarro, basados en ritos religiosos tradicionales, comidas familiares y música tradicional de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31120','fiesta','Fiestas Patronales de Muez','Patronal. Se celebra en Agosto. Festejos veraniegos que unifican las costumbres de las pequeñas localidades dispersas del valle junto al embalse de Alloz, con verbenas de plaza mayor y juegos populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31121','fiesta','Fiestas de la Virgen de la O','Patronal. Se celebra en Agosto *. Mínima expresión festiva de carácter estrictamente vecinal y de baja demografía en Mañeru, limitada a ritos litúrgicos tradicionales y un almuerzo de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31122','fiesta','Fiestas de la Hermandad (Festa de la Hermandat)','Patronal / Cultural / Etnográfica. Se celebra en Septiembre. Festejos de rango comarcal muy populares en el área metropolitana de Pamplona, caracterizados por el desfile de su colla de gigantes tradicionales, dantzas populares, calderetes y orquestas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31124','fiesta','Fiestas de San Pedro en Idocin','Patronal. Se celebra en Junio. Festejos de escala estrictamente local a las faldas de la Higa de Monreal, basados en la santa misa tradicional, juegos infantiles, comidas populares y música nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90936','fiesta','Fiestas Patronales de San Miguel','Patronal / Etnográfica. Se celebra en Septiembre. Festejos tradicionales de Bortziriak que destacan por la espectacular ejecución de sus dantzas sobre el puente, una arraigada joya folclórica local respaldada por el vecindario comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31126','fiesta','Fiestas Patronales de Etxaleku','Patronal. Se celebra en Agosto. Festejos de reencuentro estival que unifican la identidad de los núcleos del valle pirenaico, con tradicionales misas solemnes tradicionales, comidas populares y música de acordeón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31127','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Pequeñas fiestas de marcado ambiente familiar en la comarca de Sakana, basadas en el encendido de hogueras tradicionales de San Juan, comidas colectivas de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31904','fiesta','Fiestas Patronales de Irurtzun','Patronal / Cultural / Etnográfica. Se celebra en Julio. Festejos mayores de rango comarcal de gran vitalidad en el cruce de caminos del Plazaola, célebres por su espectacular comparsa de gigantes tradicionales, festivales de dantzas y conciertos masivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31128','fiesta','Fiestas de Santiago Apóstol y el Tributo de las Tres Vacas','Etnográfica / Histórica / Pacto Tradicional. Se celebra en Julio. El Tributo de las Tres Vacas en la Piedra de San Martín está declarado Fiesta de Interés Turístico de Navarra. Es el tratado de paz internacional vigente más antiguo de Europa, un hito etnográfico masivo e histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31129','fiesta','Carnaval de Ituren y Zubieta i Fiestas de San Martín','Etnográfica / Carnaval Tradicional / Mascarada. Se celebra en Enero (Carnaval) y Noviembre (Fiestas). Declarado Fiesta de Interés Turístico de Navarra de forma conjunta. Hito etnográfico absoluto e histórico de la cultura vasco-navarra, célebre por el rito masivo de los "Joaldunak" con sus cencerros gigantes espantando espíritus.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31130','fiesta','Fiestas Patronales de la Virgen del Carmen','Patronal / Etnográfica. Se celebra en Julio. Celebración tradicional del corredor de la Sakana con pasacalles musicales con agrupaciones, exhibiciones de corte de troncos, dantzas tradicionales de plaza y cenas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31131','fiesta','Fiestas Patronales de Erice de Iza','Patronal. Se celebra en Septiembre. Celebración local que unifica las costumbres tradicionales de los numerosos núcleos dispersos del término en el llano, articulada sobre verbenas, comidas populares y ritos religiosos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31132','fiesta','Romería al Santuario de San Miguel de Izaga','Romería / Etnográfica / Patronal. Se celebra en Mayo y Septiembre. Concurrida festividad de gran devoción tradicional en la comarca que asciende hasta la ermita románica en lo alto del monte Izaga, aunando el fervor popular serrano con comidas camperas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31133','fiesta','Fiestas de San Vicente y el Misterio de Gartxot','Patronal / Etnográfica / Cultural. Se celebra en Noviembre (San Vicente) y Enero (Gartxot). Festejos en el Pirineo salacenco que reviven la memoria histórica de Gartxot, el bardo de Izalzu, mediante representaciones tradicionales literarias, jotas de la tierra y encuentros vecinales). Hemos completado el Bloque 3 de la Comunidad Foral de Navarra, abarcando de forma exhaustiva todos los municipios de la lista oficial hasta la letra I de forma rigurosa y sin omitir ningún hito patrimonial o etnográfico. ¿Deseas continuar con el Bloque 4 de Navarra (Letras de la J a la P.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31134','fiesta','Fiestas Patronales de la Virgen de la Blanca','Patronal / Etnográfica. Se celebra en Agosto. Festejos tradicionales del Valle de Salazar, célebres por la espectacular y solemne ejecución de la "Axuri Beltza", una danza ancestral cantada de alto valor folclórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31135','fiesta','Las Javieradas y Fiestas de San Francisco Javier','Romería / Religiosa / Cultural. Se celebra en Marzo (Javieradas) y Diciembre (Patronal). Hito religioso absoluto y masivo a nivel autonómico y nacional; las multitudinarias peregrinaciones a pie hacia el castillo congregan a decenas de miles de fieles de toda España.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31136','fiesta','Fiestas Patronales de Ollacarizqueta','Patronal. Se celebra en Agosto. Festejos de ámbito local que aglutinan a los pequeños núcleos dispersos del valle, centrados en comidas populares de hermandad, partidos de pelota y música nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31139','fiesta','Fiestas de la Virgen de la Asunción en Galbarra','Patronal. Se celebra en Agosto. Festejos de escala estrictamente local y vecinal en el recóndito valle de Lana, condicionados por la baja demografía, con cenas populares y campeonatos de mus.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31140','fiesta','Carnaval de Lantz','Etnográfica / Carnaval Tradicional / Mitológica. Se celebra en Febrero. Declarada Fiesta de Interés Turístico de Navarra. Uno de los carnavales históricos más puros de Europa, famoso por el juicio masivo y quema del gigante de paja Miel Otxin.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31141','fiesta','Fiestas en Honor a San Roque','Patronal. Se celebra en Agosto. Pequeña celebración rural vecinal bajo el imponente "León Dormido", sustentada en el retorno veraniego de familias, comidas comunitarias y música lúdica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31142','fiesta','Fiestas Patronales de San Miguel Arcángel','Patronal / Taurina. Se celebra en Agosto. Festejos de gran arraigo en la Navarra Media, caracterizados por sus espectaculares encierros de vacas por las empinadas calles, desfiles de carrozas, gigantes y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31143','fiesta','Fiestas en Honor a San Cristóbal','Patronal. Se celebra en Agosto. Pequeñas fiestas estivales de marcado carácter vecinal y familiar en las estribaciones de Urbasa, con torneos lúdicos de naipes y comidas colectivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31144','fiesta','Fiestas Patronales del Valle de Larraun en Mugiro','Patronal / Etnográfica. Se celebra en Octubre. Festejos que unifican la rica identidad cultural de los numerosos concejos del valle, con exhibiciones de herri kirolak, música de trikitixas y cenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31145','fiesta','Fiestas de Nuestra Señora del Rosario','Patronal. Se celebra en Agosto. Festejos de ámbito local en la Ribera Alta, consistentes en pasacalles, campeonatos de mus, tradicionales actos litúrgicos y verbenas nocturnas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31146','fiesta','Fiestas en Honor a San Martín','Patronal. Se celebra en Agosto. Mínimos festejos de marcado carácter familiar condicionados por el declive demográfico de la comarca de Sangüesa, centrados en una misa tradicional y vermut vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31147','fiesta','Fiestas Patronales de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Festejos estivales tradicionales en el Camino de Santiago, basados en la hermandad vecinal, ritos religiosos, comidas en la plaza y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31148','fiesta','Fiestas en Honor a San Bartolomé','Patronal. Se celebra en Agosto. Pequeña festividad local en Valdega que congrega a los habitantes y veraneantes en torno a campeonatos lúdicos, música en directo y una cena comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31149','fiesta','Fiestas de San Tiburcio','Patronal / Etnográfica / Deporte Rural. Se celebra en Agosto. Grandes fiestas de la montaña navarra de enorme raigambre; famosas a nivel provincial por albergar las exhibiciones más puras de harrijasotzailes (levantadores de piedras) y la solemne Ingurutxo dantza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33009','fiesta','Fiestas Patronales de la Virgen del Pilar','Patronal / Cultural. Se celebra en Octubre. Festejos de rango comarcal muy consolidados en el área del Plazaola, con un dinámico programa que incluye conciertos, desfiles folclóricos, feria de artesanía y deporte rural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31150','fiesta','Fiestas de San Esteban en Iracheta','Patronal / Histórica. Se celebra en Agosto. Festejos veraniegos que dinamizan el Valle de Leoz junto a su célebre hórreo románico, combinando misas tradicionales con comidas de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31152','fiesta','Fiestas de la Virgen de la Blanca','Patronal / Taurina. Se celebra en Agosto. Festejos con notable concurrencia y raigambre taurina en la Ribera Alta, célebres por sus encierros, la suelta de vacas en el término del río Ega y populosos almuerzos populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90728','fiesta','Fiestas de San Fermín de Lesaka (Zubigaineko Dantza)','Patronal / Etnográfica / Danza Única. Se celebra en Julio. Declarada Fiesta de Interés Turístico de Navarra. Hito etnográfico espectacular donde los dantzaris ejecutan de forma masiva y arriesgada un baile equilibrista sobre los pretiles del río Onín.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31155','fiesta','Fiestas en Honor a la Virgen del Rosario','Patronal. Se celebra en Agosto. Celebración de escala local junto a la foz de Lumbier, vertebrada sobre el regreso de veraneantes, partidos de pelota, comidas vecinales y sesiones de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31157','fiesta','Fiesta del Toro con Soga de Lodosa y Fiestas de las Angustias','Taurina / Etnográfica / Gastronómica. Se celebra en Septiembre. Declarada Fiesta de Interés Turístico de Navarra. Espectacular y tradicional rito taurino de gran arraigo autonómico donde el toro recorre las calles guiado por una soga sujeta por los mozos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31158','fiesta','Fiestas Patronales de Aos','Patronal. Se celebra en Agosto. Pequeña celebración vecinal con núcleos de población muy dispersos en el valle, centrada en ritos litúrgicos tradicionales, juegos infantiles y cenas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31159','fiesta','Fiestas Patronales en Honor a San Ramón Nonato','Patronal / Etnográfica / Taurina. Se celebra en Agosto / Septiembre. Festejos con gran arraigo comarcal que destacan provincialmente por sus encierros de vaquillas, los pasacalles de su mítica e histórica comparsa de gigantes y la música de txistularis.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31160','fiesta','Fiestas de la Virgen de los Remedios y San Crispín','Patronal. Se celebra en Septiembre. Festejos tradicionales en Tierra Estella basados en la hermandad vecinal, con tradicionales misasSolemnes, campeonatos de mus y verbenas lúdicas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31248','fiesta','Día de los Bolantes de Valcarlos (Bolant Eguna)','Etnográfica / Danza Tradicional / Histórica. Se celebra en Marzo / Abril (Domingo de Resurrección). Declarada Fiesta de Interés Turístico de Navarra. Hito etnográfico monumental e histórico en el Pirineo fronterizo jacobeo, célebre por el espectacular desfile de los Bolantes danzando con cascabeles y vistosas cintas teñidas de seda.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31161','fiesta','Fiestas en Honor a la Virgen del Rosario *','Patronal / Enológica *. Se celebra en Septiembre *. Festejos tradicionales vinculados al Valle de Mañeru y su arraigo vinícola, caracterizados por comidas populares al aire libre, jotas de la tierra y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31162','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Mínimos festejos de carácter vecinal debido a la reducida población residente, limitados a actos litúrgicos y un almuerzo popular comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31163','fiesta','Fiestas Patronales de San Bartolomé y Feria del Caballo de Marcilla','Patronal / Taurina / Feria Tradicional. Se celebra en Agosto (Patronales) y Octubre (Feria). Su feria de ganado caballar de origen medieval posee gran relevancia comarcal e histórica, transformando el ferial junto al imponente castillo fortificado con exhibiciones hípicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31164','fiesta','Fiestas Patronales de la Virgen de las Nieves','Patronal / Taurina. Se celebra en Agosto. Festejos de la Ribera Alta a orillas del río Aragón, caracterizados por el desfile de gigantes de la comarca, suelta de vaquillas populares en la plaza y cenas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31165','fiesta','Fiestas en Honor a San Juan Bautista y Fiestas de las Almendreras','Patronal / Taurina / Gastronómica. Se celebra en Agosto. Festejos de rango comarcal muy populares; su puesta en valor de los productos de la huerta con Denominación de Origen destaca provincialmente por sus populosas degustaciones y encierros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31166','fiesta','Romería al Santuario de la Virgen de Codés','Romería / Etnográfica / Patronal. Se celebra en Mayo y Septiembre. Festividad de gran fervor comarcal en la Berrueza, caracterizada por la concurrida procesión mariana hacia la sierra arropada por comidas camperas y folklore local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31167','fiesta','Fiestas Patronales de San Pedro y Festival Romano de Andelo','Patronal / Taurina / Recreación Histórica. Se celebra en Agosto (Patronales) y Junio (Andelo). Destaca a nivel provincial por su festival romano de Andelo, hito cultural que recrea de forma masiva la vida colonial antigua mediante talleres, desfiles y mercados artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31168','fiesta','Fiestas Patronales de Zufía','Patronal / Gastronómica. Se celebra en Septiembre. Festejos tradicionales de Tierra Estella que aprovechan el entorno del valle y la trufa para dinamizar el reencuentro de vecinos con comidas populares y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31169','fiesta','Fiestas de San Blas y Fiesta de la Cereza de Milagro','Patronal / Gastronómica / Taurina. Se celebra en Febrero (San Blas) y Junio (Cereza). Su gran certamen agrícola dedicado a la cereza de Milagro atrae provincialmente a numeroso público gastronómico mediante exposiciones, mercados artesanales y encierros de vaquillas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31170','fiesta','Fiestas de San Román','Patronal. Se celebra en Agosto. Festejos rurales mínimos en la comarca de Estella Occidental, basados en comidas de hermandad, juegos populares y actos religiosos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31171','fiesta','Fiestas de la Virgen del Castillo y el Día del Mundo Rural','Patronal / Cultural / Feria Tradicional. Se celebra en Agosto. Celebración de la Navarra Media que destaca por su jornada de exaltación del mundo rural, rememorando antiguos oficios artesanales con pasacalles y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31172','fiesta','Fiestas Patronales en Honor a Nuestra Señora de la Natividad','Patronal / Romería. Se celebra en Septiembre. Festejos estivales en el Camino de Santiago aragonés a los pies de la Higa, centrados en tradicionales romerías, comidas populares, partidos de pelota y sesiones de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31173','fiesta','Fiestas Patronales de San Roque','Patronal / Taurina. Se celebra en Agosto. Festejos de fuerte arraigo en la Ribera Baja, caracterizados por los tradicionales encierros de reses bravas por las calles, el chupinazo y el ambiente lúdico de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31174','fiesta','Fiestas en Honor a San Andrés','Patronal. Se celebra en Agosto. Pequeñas fiestas estivales de marcado ambiente familiar trasladadas de fecha para captar la afluencia de veraneantes, con orquestas de plaza y campeonatos de mus.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31175','fiesta','Romería de la Virgen de la Vega','Romería / Patronal. Se celebra en Septiembre. Celebración de escala estrictamente local en el valle de la Berrueza, con la tradicional misa solemne y comida de hermandad vecinal al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31176','fiesta','Fiestas Patronales de San Roque','Patronal / Taurina / Enológica. Se celebra en Agosto. Festejos de gran vitalidad en la Ribera Baja, célebres por sus multitudinarios encierros, el dinámico recinto de peñas y la degustación de sus reconocidos vinos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31178','fiesta','Fiestas Patronales de Rada y de Murillo','Patronal / Taurina. Se celebra en Agosto. Festejos tradicionales que unifican las costumbres de sus diferentes núcleos de población en el llano de la Zona Media, con suelta de vaquillas y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31179','fiesta','Fiestas Patronales de la Virgen del Rosario','Patronal / Taurina. Se celebra en Septiembre. Celebración junto al río Aragón que cuenta con tradicionales encierros, pasacalles folclóricos de gigantes y una activa participación vecinal en las verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31180','fiesta','Fiestas de San Esteban y Romería a Santa María de Eunate','Patronal / Romería / Jacobea. Se celebra en Agosto (Fiestas) y Septiembre (Romería). Festejos en Valdizarbe marcados por la espectacular y concurrida romería a la mítica e histórica iglesia templaria octogonal de Eunate, uniendo fe e identidad jacobea.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31181','fiesta','Fiestas Patronales de San Cristóbal y de la Virgen del Campo','Patronal / Romería. Se celebra en Agosto (Fiestas) y Septiembre (Romería). Pequeñas fiestas del Almiradío de fuerte identidad pirenaica, estructuradas en torno a la romería tradicional a la ermita, comidas de hermandad y música local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31182','fiesta','Fiestas de San Pedro y la Virgen de Loreto','Patronal. Se celebra en Agosto. Mínima expresión festiva de carácter estrictamente familiar en el valle de la Berrueza debido a la baja demografía, limitada a una misa y merienda vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90730','fiesta','Fiestas Patronales de Noáin (San Miguel)','Patronal / Cultural / Etnográfica. Se celebra en Agosto. Festejos de gran rango en el área metropolitana de Pamplona, caracterizados por un potente programa lúdico de conciertos, desfile de su espectacular comparsa de gigantes y activos correfocs.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31183','fiesta','Misterio de Obanos i Fiestas de San Juan','Teatral / Recreación Histórica / Jacobea / Bienal. Se celebra en Julio (Misterio) y Agosto (San Juan). Declarada Fiesta de Interés Turístico Nacional. Colosal representación teatral itinerante en su monumental plaza que escenifica la leyenda medieval jacobea de Santa Felicia y San Guillén.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31185','fiesta','Fiestas de la Virgen de Muskilda (Danzas de Ochagavía)','Patronal / Etnográfica / Danza Ancestral. Se celebra en Septiembre. Declarada de gran relevancia etnográfica autonómica. Espectacular hito folclórico del Pirineo navarro donde los dantzaris con sombreros de cintas y el Bobo ejecutan danzas de palos milenarias en el santuario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31184','fiesta','Fiestas en Honor a San Vitores','Patronal. Se celebra en Mayo y Agosto. Festejos patronales de arraigo estrictamente local en la comarca de Estella Oriental, caracterizados por el retorno estival de familias, misas solemnes, comidas populares y verbenas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31186','fiesta','Fiestas de San Juan en Ostiz','Patronal. Se celebra en Junio. Celebración vecinal y tradicional que congrega a los núcleos de este valle prepirenaico, centrada en el encendido de hogueras, juegos infantiles y sesiones lúdicas en el local social.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31188','fiesta','Fiestas de San Juan en Olave','Patronal. Se celebra en Junio. Festejos de ámbito local en el valle, estructurados en torno al encendido de la hoguera tradicional de San Juan, pasacalles infantiles y comidas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31189','fiesta','Fiestas de Santa Ana y la Bajada del El rústico','Patronal / Etnográfica. Se celebra en Julio. Festejos con notable arraigo en la Sakana, destacados por el singular acto etnográfico de la bajada del "Rústico" con disfraces, acompañada de partidos de pelota a mano, dantzas y música de txistularis.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31190','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Pequeña celebración veraniega de marcado carácter vecinal condicionada por la baja demografía, basada en ritos religiosos tradicionales, comidas comunitarias al aire libre y música de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33013','fiesta','Fiestas Patronales de la Santa Cruz y Fiesta de la Vendimia de Navarra','Enológica / Gastronómica / Patronal / Histórica. Se celebra en Septiembre. La Fiesta de la Vendimia está declarada Fiesta de Interés Turístico de Navarra. Gran hito enológico y cultural que exalta la producción del vino con la pisada de uva, desfiles de cofradías y la monumental estampa de su palacio real medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31195','fiesta','Fiestas de San Pedro y el recuerdo de la Real Fábrica de Armas','Patronal / Histórica / Etnográfica. Se celebra en Junio y Agosto. Festejos en el Valle de Aezkoa de hondo carácter pirenaico, que combinan las dantzas tradicionales y trajes típicos del valle con visitas y mercados artesanales en las históricas ruinas de su fábrica de armas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31196','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Mínima expresión festiva de carácter familiar en el Pirineo navarro debido a la reducida población, limitada a ritos religiosos tradicionales y un almuerzo de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31197','fiesta','Fiestas de San Martín y Feria del de la Trufa de la Valdorba','Gastronómica / Feria Tradicional / Patronal. Se celebra en Agosto (Patronales) y Diciembre (Feria). Su histórica feria invernal dedicada a la trufa negra posee un notable arraigo provincial en la Valdorba, atrayendo a numeroso público gastronómico con demostraciones de recogida con perros y mercado gourmet.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90733','fiesta','Fiestas Patronales de Orkoien','Patronal / Cultural. Se celebra en Junio. Festejos que han crecido exponencialmente en paralelo a su desarrollo residencial e industrial metropolitano, con un potente programa lúdico, desfiles de gigantes tradicionales y orquestas masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31198','fiesta','Fiestas de San Cosme y San Damián','Patronal. Se celebra en Agosto. Pequeña celebración rural que unifica la escasa población de este núcleo del Valle de Salazar, centrada en comidas comunitarias de hermandad y ritos religiosos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31199','fiesta','Fiestas de San Adrián','Patronal / Etnográfica. Se celebra en Agosto. Festejos de montaña en el Pirineo oriental junto al río Irati, caracterizados por el regreso estival de familias, tradicionales misas cántabras solemnes tradicionales, dantzas y música de acordeón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31200','fiesta','Fiestas en Honor a San Salvador y la Virgen de la Asunción','Patronal / Taurina. Se celebra en Agosto. Festejos tradicionales de la comarca de Estella con notable concurrencia, destacados por sus tradicionales encierros y espectáculos de vaquillas en la plaza, pasacalles de gigantes y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33014','fiesta','Fiestas de San Fermín (Sanfermines)','Patronal / Taurina / Etnográfica / Cultural. Se celebra en Julio (Del 6 al 14 de julio). Declarada Fiesta de Interés Turístico Internacional. Uno de los macrofestejos masivos globales más famosos del mundo, célebre por el Chupinazo, los espectaculares y multitudinarios encierros diarios de toros, la comparsa de Gigantes y Cabezudos y un colosal despliegue cultural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31203','fiesta','Fiestas Patronales de San Antonio y Santiago Apóstol','Patronal / Histórica. Se celebra en Julio. Festejos en este singular enclave navarro rodeado de territorio aragonés, condicionados por su baja demografía, centrados en el recuerdo histórico de Ramón y Cajal, misas tradicionales y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31204','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Pequeñas fiestas veraniegas con un programa lúdico y religioso mínimo adaptado a la reducida población residente en el valle de Berrueza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31205','fiesta','Fiestas en Honor a San Ramón Nonato','Patronal / Taurina. Se celebra en Agosto. Festejos tradicionales de la Navarra Media junto a su célebre laguna, destacados por los espectáculos taurinos callejeros de vaquillas populares, jotas de la tierra, cenas populares y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33015','fiesta','Fiestas de Santiago Apóstol y Ferias de las Cofradías (Fiesta de las Layas)','Patronal / Jacobea / Etnográfica / Deportiva. Se celebra en Julio (Santiago) y Septiembre (Ferias). Declarada Fiesta de Interés Turístico de Navarra. Hito jacobeo absoluto en el cruce de caminos del Camino de Santiago, famosa por la espectacular e histórica carrera sobre layas y sus encierros de vaquillas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31207','fiesta','Fiestas del Apóstol Santiago','Patronal. Se celebra en Julio. Celebración tradicional de la Valdorba de carácter local, articulada con procesión solemne tradicional, campeonatos de mus, orquestas de noche en la plaza mayor y actividades infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31208','fiesta','Fiestas en Honor a San Bartolomé y San Blas','Patronal / Taurina / Etnográfica. Se celebra en Agosto (San Bartolomé) y Febrero (San Blas). Festejos de gran arraigo en la Ribera Baja, destacados por su espectacular e histórico Dance de Ribaforada con mudanzas de palos, encierros de vaquillas populares y una altísima participación de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31209','fiesta','Fiestas de Domeño','Patronal. Se celebra en Agosto. Pequeña celebración rural que congrega a los habitantes de sus caseríos dispersos en el entorno de la Foz de Arbayún en torno a ritos religiosos tradicionales y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31210','fiesta','Fiestas en Honor a Nuestra Señora del Castillo *','Patronal / Etnográfica *. Se celebra en Agosto *. Celebración de la capital del Valle de Roncal, de fuerte identidad pirenaica, destacada por sus danzas al son del txistu, la puesta en valor de la indumentaria típica y la exaltación de su famoso queso con D.O.P.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31211','fiesta','Fiestas de la Virgen de Roncesvalles y Romerías de los Valles (Cruces de Mayo)','Romería / Jacobea / Religiosa / Etnográfica. Se celebra en Mayo y Septiembre. Declaradas Fiestas de Interés Turístico de Navarra. Hito religioso y jacobeo de primer orden en Europa, célebre por la impresionante llegada en romería de los penitentes del Valle de Aezkoa y el Valle de Erro vestidos de negro portando grandes cruces.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31212','fiesta','Fiestas en Honor a San Vicente','Patronal. Se celebra en Agosto. Festejos estivales en la comarca de Sangüesa orientados al reencuentro de veraneantes, basados en comidas de hermandad tradicionales, campeonatos de mus y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31213','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Pequeñas fiestas de montaña en Malerreka de marcado ambiente familiar, con encendido de hogueras tradicionales, comidas comunitarias de hermandad y partidos de pelota a mano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31214','fiesta','Fiestas de San Miguel y Jornada de las Salinas','Patronal / Feria Etnográfica / Gastronómica. Se celebra en Agosto. Festejos tradicionales que ponen en valor la extracción artesanal de sus históricas salinas de manantial interior, arropados por ferias tradicionales, folclore local y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31215','fiesta','Fiestas de las Santas Reliquias','Patronal / Taurina / Etnográfica. Se celebra en Julio. Grandes fiestas mayores en la Ribera Alta, célebres por sus masivos encierros de novillos por las calles, la procesión de las Santas Reliquias acompañada por el gigante local y su potente recinto de peñas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31217','fiesta','Fiestas en Honor a San Martín y Día del Rosado','Patronal / Enológica / Gastronómica. Se celebra en Junio (Rosado) y Agosto (Patronales). Festejos que destacan provincialmente por su Día del Vino Rosado, hito enológico que atrae a numeroso público hacia sus bodegas medievales artesanales con degustaciones masivas, jotas y folclore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31216','fiesta','Fiestas en Honor a San Sebastián (El Misterio de Reyes) i Festes de Setembre','Patronal / Teatral / Etnográfica / Taurina. Se celebra en Enero (Misterio) y Septiembre (Festes). Declarada Fiesta de Interés Turístico de Navarra. Su representación sacra e itinerante del Auto de los Reyes Magos posee un alto e histórico valor etnográfico, sumándose a sus populosas fiestas de septiembre con encierros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31219','fiesta','Fiestas de San Zoilo','Patronal / Jacobea. Se celebra en Agosto. Festejos tradicionales en el Camino de Santiago navarro, caracterizados por el regreso estival de familias asociadas al municipio, misas solemnes tradicionales y verbenas lúdicas familiares en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31220','fiesta','Fiestas Patronales de Nuestra Señora de la Asunción y el Día de la Cara Romana','Patronal / Recreación Histórica / Taurina. Se celebra en Agosto (Patronales) y Septiembre (Cara Romana). Festejos que destacan en la Comunidad de Bardenas por su notable recreación histórica de la antigua ciudad romana de Cara, atrayendo numerosa concurrencia provincial con mercados de época y encierros de vaquillas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31222','fiesta','Fiestas de San Esteban','Patronal. Se celebra en Agosto. Pequeños festejos tradicionales de alta montaña y carácter puramente familiar en el Valle de Salazar, condicionados por su baja demografía, con ritos religiosos tradicionales mínimos y almuerzo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31223','fiesta','Fiestas de la Virgen del Rosario y Fiesta del Melocotón de Sartaguda','Gastronómica / Feria Tradicional / Patronal. Se celebra en Agosto (Melocotón) y Octubre (Patronales). Festejos tradicionales de la Ribera Alta orientados a la promoción de su huerta, famosa por la fira del melocotón de regadío, sumando encierros de vaquillas populares y folclore local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31224','fiesta','Fiestas de la Virgen de la Alborada y el Día del Esparto','Patronal / Etnográfica / Feria Tradicional. Se celebra en Agosto (Patronales) y Noviembre (Esparto). Destacan provincialmente por el singular hito etnográfico del Día del Esparto, donde se revive el histórico oficio artesanal de trenzar el esparto, combinado en verano con tradicionales capeas taurinas y desfiles populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31226','fiesta','Fiestas Patronales de San Juan Bautista y los Carnavales de Sunbilla','Patronal / Carnaval Tradicional / Etnográfica. Se celebra en Enero (Carnaval) y Junio (San Juan). Festejos tradicionales de la comarca de Malerreka, destacados por sus animados desfiles de carrozas humorísticas en carnaval y las dantzas tradicionales a orillas del río Bidasoa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31227','fiesta','Fiestas Patronales de Nuestra Señora de la Asunción y San Sebastián','Patronal / Taurina / Etnográfica. Se celebra en Agosto (Del 14 al 20). Declarada Fiesta de Interés Turístico de Navarra. Grandes fiestas de la capital de la Zona Media, famosas a nivel regional por la extraordinaria pureza de sus tradicionales encierros, corridas de toros, el desfile de gigantes monumentales y sus activas peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31228','fiesta','Fiestas Patronales de la Invención de la Santa Cruz en Tiebas','Patronal / Histórica. Se celebra en Agosto. Festejos que dinamizan el piedemonte de la Higa de Monreal alrededor de su castillo-palacio real fortificado medieval, con verbenas de plaza, campeonatos de mus y tradicionales comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31229','fiesta','Fiestas de la Virgen de la O','Patronal. Se celebra en Mayo. Mínimos festejos rurales en Valdizarbe condicionados por la baja demografía del municipio, limitados a ritos religiosos tradicionales en su templo, comidas familiares y un vermut popular vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31230','fiesta','Fiestas de Nuestra Señora de Codés (Baile de la de la Balsa)','Patronal / Romería / Etnográfica. Se celebra en Septiembre. Festejos en la sierra de Codés célebres por la concurrida romería tradicional al santuario y el histórico hito etnográfico del "Baile de la Balsa", una danza catalogada ejecutada por los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31231','fiesta','Fiestas del Santo Sepulcro','Patronal / Jacobea. Se celebra en Septiembre. Festejos locales al pie de su monumental e histórica iglesia del Santo Sepulcro del siglo XII en el Camino de Santiago, estructurados con verbenas al aire libre y comidas populares de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31232','fiesta','Fiestas de Santa Ana de Tudela (El Volatín y la Bajada del Ángel)','Patronal / Etnográfica / Religiosa / Taurina. Se celebra en Julio (Semana Santa para los autos sacros y Julio para las patronales). La Bajada del Ángel y El Volatín en Semana Santa ostentan la declaración de Fiesta de Interés Turístico Nacional. En julio, sus macrofiestas mayores patronales atraen a miles de personas con su Revoltijo, peñas masivas y feria taurina de la Ribera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31233','fiesta','Fiestas Patronales de la Virgen de la Cama','Patronal. Se celebra en Agosto. Festejos de ámbito estrictamente local vinculados al entorno histórico del Monasterio de Santa María de la Caridad, basados en actos litúrgicos tradicionales, juegos infantiles y cenas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31234','fiesta','Fiestas en Honor a la Virgen de la Asunción','Patronal. Se celebra en Agosto. Pequeñas fiestas estivales de marcado ambiente familiar en el valle de Ilzarbe, organizadas por la población para juegos infantiles tradicionales de la zona y cenas colectivas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31235','fiesta','Romería de los Cruceros a la Virgen de Ujué','Romería / Etnográfica / Religiosa / Gastronómica. Se celebra en Abril / Mayo (Primer domingo posterior a San Marcos). Declarada de gran relevancia etnográfica autonómica. Impresionante e histórico hito religioso donde los penitentes entunicados de los valles vecinos ascienden de madrugada cargando cruces de madera hacia el santuario-fortaleza medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31236','fiesta','Fiesta del Día del Valle de Ultzama (Ultzamako Eguna) y Fiesta de la Cuajada','Etnográfica / Gastronómica / Valle. Se celebra en Septiembre. Hito tradicional de gran renombre provincial en los valles húmedos del norte, célebre por la exaltación y demostración artesanal de la elaboración de la cuajada tradicional con piedras incandescentes en recipientes de madera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31239','fiesta','Fiestas Patronales de San Juan Bautista','Patronal / Etnográfica. Se celebra en Junio. Festejos en el entorno del histórico monasterio y cuevas aborígenes, destacados por el encendido de hogueras tradicionales vasconavarras, música de txistularis y danzas tradicionales locales en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31240','fiesta','Fiestas Patronales de San Pedro','Patronal / Etnográfica / Danza Tradicional. Se celebra en Junio. Celebración de la comarca de Sakana, famosa provincialmente por la pureza de sus dantzas folclóricas de plaza ejecutadas por las mujeres del pueblo vistiendo trajes regionales tradicionales de alta raigambre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31241','fiesta','Fiestas de San Pedro en Irurozqui','Patronal. Se celebra en Junio. Mínima expresión festiva distribuida entre sus pequeños caseríos dispersos en el Prepirineo debido a la extrema despoblación del valle, centrada en comidas familiares y ritos religiosos tradicionales mínimos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31242','fiesta','Fiestas de San Martín en Artieda','Patronal. Se celebra en Agosto. Pequeña festividad local de la comarca de Aoiz que congrega a los habitantes de los caseríos en torno a comidas populares de hermandad al aire libre, campeonatos de cartas y música de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31243','fiesta','Fiestas Patronales de la Virgen de la Asunción y Feria de Urroz','Patronal / Feria Tradicional. Se celebra en Agosto (Patronales) y Noviembre (Feria) *. Festejos que conservan el arraigo de su secular mercado e inmensa plaza del mercado, combinando en verano el desfile de gigantes de la comarca con conciertos, calderetes y actividades infantiles locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90937','fiesta','Fiestas Patronales de San Miguel','Patronal. Se celebra en Agosto. Pequeñas fiestas de montaña en Malerreka adaptadas a su baja demografía, sustentadas en ritos litúrgicos tradicionales en su templo, partidos de pelota en el frontón y comidas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31245','fiesta','Fiestas Patronales de San Martín','Patronal / Etnográfica. Se celebra en Agosto. Festejos tradicionales de alta montaña en el Valle de Roncal, orientados al regreso estival de familias asociadas al municipio, con música de txistularis, bailes tradicionales y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31246','fiesta','Fiestas en Honor a Nuestra Señora de la Asunción','Patronal / Jacobea. Se celebra en Agosto. Celebración de carácter puramente local en Valdizarbe en la ruta del Camino de Santiago, estructurada en torno a ritos religiosos tradicionales, comidas populares de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31247','fiesta','Fiestas Patronales de Santa Engracia','Patronal / Etnográfica. Se celebra en Agosto. Festejos veraniegos serranos del Valle de Roncal de marcado sabor pirenaico, caracterizados por pasacalles musicales con agrupaciones, exhibiciones folclóricas locales de herri kirolak y comidas de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31249','fiesta','Fiestas Patronales de San Ireneo','Patronal / Taurina. Se celebra en Agosto. Festejos tradicionales de la Ribera con notable concurrencia junto a las Bardenas, destacados por sus tradicionales encierros y capeas de reses bravas por las calles, el chupinazo y desfile de peñas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31251','fiesta','Fiestas Patronales en Honor a Santa María y San Felices','Patronal / Taurina / Etnográfica. Se celebra en Julio. Grandes fiestas de rango comarcal muy populares en la mítica frontera con La Rioja. Destacan por sus históricos encierros taurinos nocturnos, la suelta de vaquillas por su monumental trazado amurallado colonial y un potente ambiente de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31252','fiesta','Fiestas Patronales de San Agustín (La Bajada de la Bruja)','Patronal / Etnográfica / Mitológica. Se celebra en Agosto. Destaca a nivel provincial por el singular e histórico hito tradicional de la "Bajada de la Bruja Marimartatxo" de madrugada desde el cerro rocoso, una representación que recrea antiguos aquelarres mitológicos roncaleses.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31254','fiesta','Fiestas Patronales de Santa Eufemia','Patronal / Taurina. Se celebra en Septiembre. Festejos de rango comarcal tradicionales en la Ribera Alta, caracterizados por sus masivos encierros de vaquillas populares en plaza portátil, desfiles de carrozas populares, chupinazo y un activo recinto de peñas juveniles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31255','fiesta','Fiestas de San Andrés','Patronal / Romería. Se celebra en Agosto. Festejos locales bajo las murallas de su castillo fortificado románico, caracterizados por las romerías tradicionales a las ermitas de la comarca, campeonatos de mus y verbenas de noche.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31257','fiesta','Fiestas Patronales de San Veremundo','Patronal / Jacobea / Cultural. Se celebra en Septiembre. Festejos de arraigo local tradicionales en la comarca de Estella, caracterizados por el desfile de gigantes de la comarca, pasacalles musicales con agrupaciones y verbenas lúdicas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31258','fiesta','Fiestas de la Virgen del Rosario de Villava','Patronal / Cultural / Etnográfica. Se celebra en Octubre. Festejos de gran rango comarcal muy populares en la Cuenca de Pamplona, con un potente programa lúdico, espectaculares desfiles de su comparsa de gigantes tradicionales, ferias y encierros de vaquillas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31194','fiesta','Fiestas Patronales del Valle de Ollo','Patronal / Romería. Se celebra en Agosto. Festejos tradicionales que unifican a los pequeños núcleos de este valle prepirenaico mediante romerías a ermitas locales, bailes de plaza, comidas populares y música de acordeón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31202','fiesta','Fiestas Patronales de la Virgen de la Nieva','Patronal / Taurina. Se celebra en Septiembre. Festejos de rango comarcal muy populares en la Ribera Alta, célebres por sus populosos encierros de toros, capeas en la plaza portátil, vistosos desfiles de peñas y un potente recinto de verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31225','fiesta','Romería al Basílica de la San Gregorio Ostiense','Romería / Religiosa / Etnográfica. Se celebra en Mayo. Gran basílica barroca de rango comarcal en Tierra Estella que congrega a miles de peregrinos de numerosos valles para el tradicional rito de pasar el agua bendita por la cabeza de plata del santo contra las plagas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31260','fiesta','Fiestas de la Virgen de la Asunción en Arizala','Patronal / Enológica. Se celebra en Agosto. Festejos que unifican las tradiciones de los numerosos núcleos dispersos del valle de Yerri al lado del embalse de Alloz, con degustaciones de vinos locales y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31261','fiesta','Fiestas de la Virgen de la Asunción y Romería a San Salvador de Leyre','Patronal / Romería / Histórica. Se celebra en Agosto (Patronales) y Mayo (Leyre). Festejos vinculados al monumental e histórico Monasterio de San Salvador de Leyre, atrayendo a numerosos peregrinos por su concurrida romería tradicional y fervor regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31262','fiesta','Fiestas de la Inmaculada Concepción en Ubani','Patronal. Se celebra en Septiembre. Festejos de escala estrictamente local en el valle de Echauri, basados en ritos tradicionales litúrgicos de final de verano, actividades infantiles locales y comidas populares vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90938','fiesta','Fiestas Patronales en Honor a la Virgen de la Asunción','Patronal. Se celebra en Agosto. Pequeñas fiestas veraniegas al límite con Álava en el corredor de la Sakana, caracterizadas por partidos de pelota a mano en el frontón, comidas populares al aire libre y música nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31907','fiesta','Fiestas Patronales de la Santa Cruz de Zizur Mayor','Patronal / Cultural / Etnográfica. Se celebra en Septiembre. Grandes fiestas de rango comarcal muy consolidadas en la periferia de Pamplona, célebres por el espectacular despliegue de su comparsa de gigantes tradicionales locales, activos correfocs, conciertos y ferias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31263','fiesta','Carnaval de Ituren y Zubieta i Fiestas de la Virgen de la Asunción','Etnográfica / Carnaval Tradicional / Mascarada. Se celebra en Enero (Carnaval) y Agosto (Fiestas). Declarado Fiesta de Interés Turístico de Navarra de forma conjunta. Hito etnográfico absoluto e histórico en Malerreka, famoso por el desfile masivo de los "Joaldunak" agitando cencerros y portando hisopos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31264','fiesta','Fiesta de las Brujas de Zugarramurdi (Cueva del Aquelarre) y Fiestas de la Virgen de la Asunción','Etnográfica / Mitológica / Gastronómica / Patronal. Se celebra en Agosto (El "Zikiro Jate" el 18 de agosto). Declarada de gran relevancia etnográfica autonómica y nacional. Famosa a nivel internacional por su mítica comida popular multitudinaria ("Zikiro Jate" o cordero asado al estilo tradicional) en el interior de las colosales Cuevas de las Brujas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31265','fiesta','Fiestas en Honor a la Virgen de la O','Patronal. Se celebra en Agosto. Festejos trasladados al mes estival para captar la afluencia de veraneantes en la frontera con Álava, consistentes en cenas de hermandad al aire libre y música en la plaza). Hemos completado al 100% todos los municipios de la Comunidad Foral de Navarra, finalizando así por completo esta Comunidad Autónoma uniprovincial de forma exhaustiva. ¿Procedemos a abrir la siguiente Comunidad Autónoma según el estricto orden alfabético global, que corresponde al País Vasco (comenzando por la provincia de Álava)?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50001','fiesta','Fiestas en Honor a Nuestra Señora de Aiala','Patronal / Etnográfica. Se celebra en Septiembre. Festejos de fuerte arraigo local en la Llanada Alavesa, caracterizados por el tradicional txupinazo, pasacalles de la comparsa de cabezudos, competiciones de pelota mano y las concurridas verbenas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50002','fiesta','Fiestas Patronales de Nuestra Señora de la Asunción y San Roque','Patronal / Etnográfica / Gastronómica. Se celebra en Agosto. Festejos de rango comarcal de gran vitalidad en la cuadrilla de Ayala, célebres por el desfile de carrozas de las cuadrillas, exhibiciones de herri kirolak, el tradicional aurresku de honor y degustaciones de txakoli local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01049','fiesta','Fiesta del Sapo y Fiestas de Nuestra Señora de la Asunción','Etnográfica / Tradicional / Patronal. Se celebra en Agosto. Destacan por la singularidad de la "Fiesta del Sapo" en Gesaltza Añana, hito etnográfico local vinculado a la historia y leyendas de su monumental Valle Salado, arropado por música de trikitixas y cenas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90263','fiesta','Fiestas de San Martín y de Nuestra Señora de Vicente','Patronal / Etnográfica. Se celebra en Julio. Celebración de la denominada "Suiza alavesa", con fuerte identidad euskaldun, destacada por sus solemnes bailes tradicionales al son de los txistularis, campeonatos de mus y el reencuentro veraniego familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90264','fiesta','Fiestas en Honor a San Andrés','Patronal. Se celebra en Noviembre. Mínima expresión festiva de carácter estrictamente vecinal en la Ribera Baja debido a su reducida demografía, limitada a ritos religiosos tradicionales, comidas de hermandad y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50004','fiesta','Fiestas Patronales de Maeztu en Honor a la Virgen de la Asunción','Patronal. Se celebra en Agosto. Festejos que unifican las costumbres tradicionales de los pequeños núcleos dispersos de la Montaña Alavesa mediante verbenas de plaza, misas solemnes tradicionales y actividades infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50005','fiesta','Fiestas de Durana en Honor a San Esteban','Patronal. Se celebra en Diciembre. Pequeñas fiestas invernales junto al embalse de Ullibarri-Gamboa, sustentadas en ritos litúrgicos tradicionales en su templo, competiciones lúdicas locales y cenas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50006','fiesta','Fiestas de la Virgen de la Encina y Mercado Medieval de Artziniega','Patronal / Recreación Histórica / Etnográfica. Se celebra en Septiembre. Su mercado medieval posee rango comarcal y provincial de alta popularidad, transformando por completo el casco histórico fortificado con puestos de artesanía tradicional, juglares y representaciones de época.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50007','fiesta','Fiestas de San Pedro en Araia y Fiesta del Pastoreo','Patronal / Etnográfica / Gastronómica. Se celebra en Junio (San Pedro) y Agosto (Pastoreo). Festejos en la Llanada Oriental destacados por la puesta en valor de la cultura pastoril de la Sierra de Urbasa, incluyendo ferias de queso tradicional de Idiazabal y folclore local vasco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50008','fiesta','Fiestas de Respaldiza en Honor a San Esteban','Patronal. Se celebra en Agosto. Festejos unificados de la cuenca que dinamizan los pequeños barrios y caseríos del término, centrados en tradicionales misas solemnes tradicionales, comidas populares y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50010','fiesta','Fiestas en Honor a San Cristóbal y San Roque','Patronal / Enológica. Se celebra en Julio y Agosto. Celebración de la Rioja Alavesa fuertemente vinculada al sector vinícola de la D.O.Ca. Rioja, caracterizada por las catas populares, el tradicional pisado de uva y verbenas veraniegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50009','fiesta','Fiestas de Ozaeta en Honor a San Juan Bautista','Patronal. Se celebra en Junio. Pequeñas fiestas estivales de marcado ambiente familiar basadas en el encendido de hogueras tradicionales de San Juan, comidas colectivas de hermandad y música tradicional de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90939','fiesta','Fiestas en Honor a Nuestra Señora of la Asunción','Patronal. Se celebra en Septiembre. Festejos de ámbito estrictamente local en la Cuadrilla de Añana, marcados por la misa solemne tradicional, partidos de pelota a mano en el frontón y comidas de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50011','fiesta','Fiestas de la Virgen de Okon','Patronal / Romería. Se celebra en Septiembre. Concurrida festividad de gran devoción en la Montaña Alavesa que asciende en romería tradicional hasta el santuario homónimo en las faldas de la sierra, aunando fervor mariano con comidas camperas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50012','fiesta','Fiestas de Santa Cruz de Santa Cruz de Campezo','Patronal / Etnográfica. Se celebra en Septiembre. Festejos de gran arraigo en la Montaña Alavesa, destacados por la bajada de "El Babas", pasacalles de txistularis, campeonatos de mus y verbenas populares multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50013','fiesta','Fiestas de San Pedro y de la Natividad de Nuestra Señora','Patronal. Se celebra en Junio y Septiembre. Festejos de escala estrictamente local en el llano, orientados a la convivencia comunitaria de sus pequeños núcleos dispersos, con verbenas de plaza y ritos tradicionales religiosos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01022','fiesta','Fiestas de la Virgen de la Plaza','Patronal / Enológica / Etnográfica. Se celebra en Septiembre. Hito tradicional de gran renombre en la Rioja Alavesa, célebre por la espectacular danza de sus "Danzantes de Elciego" acompañando a la virgen con mudanzas y castañuelas, sumado a la cata de vinos locales de solera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01023','fiesta','Fiestas en Honor a Nuestra Señora de la Asunción y San Roque','Patronal / Enológica. Se celebra en Agosto. Festejos tradicionales al abrigo de su monumental dolmen de la Hechicera, caracterizados por pasacalles de cooperativa, catas populares de vinos locales y verbenas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01056','fiesta','Fiestas de San Vicente de Arana','Patronal. Se celebra en Agosto. Pequeña celebración rural que unifica la escasa población de los pequeños caseríos del valle, centrada en comidas comunitarias de hermandad y ritos religiosos tradicionales mínimos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01901','fiesta','Fiestas Patronales de Nanclares de la Oca en Honor a San Roque','Patronal / Etnográfica / Cultural. Se celebra en Agosto. Festejos que destacan en la cuadrilla de Añana por la célebre bajada de "El Brujo" desde la torre de la iglesia de Nanclares, arropada por un gran ambiente de cuadrillas locales y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01027','fiesta','Fiestas de Acilu en Honor a San Martín','Patronal. Se celebra en Noviembre. Festejos rurales mínimos distribuidos entre los pequeños caseríos dispersos de la Llanada Alavesa, centrados en comidas familiares y ritos religiosos tradicionales). Hemos completado el Bloque 1 de la provincia de Álava, abarcando de forma exhaustiva todos los municipios de la lista oficial hasta la letra I de forma rigurosa y sin omitir ningún dato patrimonial o folclórico. ¿Deseas continuar con el Siguiente Bloque de la provincia de Álava (Letras de la L a la Z.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01028','fiesta','Fiestas de Nuestra Señora de la Asunción y de San Ginés','Patronal / Enológica / Etnográfica. Se celebra en Agosto y Noviembre. Festejos de gran arraigo en la Rioja Alavesa, destacados por la espectacular ronda de las cuadrillas por las bodegas subterráneas medievales y la tradicional danza de los pastores de Labastida el día de Nochebuena.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01030','fiesta','Fiestas en Honor a la Virgen de la Natividad','Patronal / Romería. Se celebra en Septiembre. Festejos tradicionales de la Montaña Alavesa con una concurrida romería a la ermita de San Bartolomé, combinando comidas populares de hermandad y campeonatos de mus.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01031','fiesta','Fiestas de San Juan y San Pedro','Patronal / Enológica / Etnográfica. Se celebra en Junio. Declaradas de gran interés regional. Célebres por el tradicional tremolado de la bandera en la Plaza Mayor, la vistosa comparsa de gigantes de solera y el masivo toro de fuego por las angostas calles de la villa amurallada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01032','fiesta','Fiestas de Nuestra Señora del Campo','Patronal / Enológica. Se celebra en Septiembre. Festejos vinculados estrechamente a la recogida de la uva de la Rioja Alavesa y la molienda tradicional del aceite en su trujal artesanal, amenizados por verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01902','fiesta','Fiestas de Comunión en Honor a San Cornelio','Patronal. Se celebra en Septiembre. Pequeña celebración que unifica las costumbres tradicionales de los numerosos núcleos rurales dispersos a orillas del río Ebro, basada en comidas vecinales y ritos litúrgicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90940','fiesta','Fiestas en Honor a San Roque','Patronal / Cultural. Se celebra en Agosto. Festejos junto al embalse de Urrunaga con notable participación comarcal, caracterizados por competiciones de regatas de traineras, partidos de pelota mano y música tradicional de trikitixas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01034','fiesta','Fiestas de San Martín','Patronal. Se celebra en Noviembre. Mínimos festejos de invierno condicionados por la baja demografía del municipio, limitados a actos religiosos en su templo renacentista y un vermut popular comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01039','fiesta','Fiestas de Santa María de la Asunción y Fiesta del Aceite de Oliva','Patronal / Gastronómica. Se celebra en Agosto (Patronales) y Marzo (Aceite). Festejos que combinan la devoción estival con la renombrada feria gastronómica del aceite de oliva virgen extra de la variedad local Arróniz, atrayendo a numeroso público provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01041','fiesta','Fiestas en Honor a San Juan Ortega','Patronal / Enológica. Se celebra en Junio. Celebración de escala estrictamente local en la comarca vitivinícola, vertebrada sobre el tradicional reparto de sarmientos, catas populares de vino y sesiones de baile nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50030','fiesta','Fiestas en Honor a San Bartolomé','Patronal / Etnográfica. Se celebra en Agosto. Festejos de fuerte arraigo en el Valle de Ayala, destacados por el tradicional desfile de disfraces de las cuadrillas locales, exhibiciones de corte de troncos y comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50031','fiesta','Fiestas de San Vicente y San Anastasio','Patronal / Etnográfica / Singular. Se celebra en Enero. Destacan provincialmente por los antiquísimos e históricos hitos etnográficos de la "Danza de los Santos Patronos", el tremolado de la bandera bajo el volteo de campanas y el popular "Revoltijo".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01044','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal / Histórica. Se celebra en Agosto. Festejos veraniegos que reviven el patrimonio de su casco amurallado medieval, combinando ritos litúrgicos tradicionales con música tradicional de txistularis y cenas vecinales al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50015','fiesta','Fiestas de Pobes en Honor a la Virgen del Rosario','Patronal / Feria Tradicional. Se celebra en Octubre. Festejos en la Cuadrilla de Añana que albergan la histórica y concurrida Feria de la Alubia de Pobes, hito tradicional que exalta la gastronomía y los mercados artesanos de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01047','fiesta','Fiestas de Rivabellosa en Honor a Nuestra Señora del Rosario','Patronal. Se celebra en Agosto. Festejos de carácter local trasladados de época estival para favorecer el retorno, consistentes en pasacalles musicales con agrupaciones, torneos lúdicos y sesiones de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01052','fiesta','Fiestas de la Virgen del Valle','Patronal / Enológica. Se celebra en Septiembre. Celebración tradicional de la Rioja Alavesa basada en el fin de la campaña vitivinícola, estructurada con el popular "Juicio a Judas" en Semana Santa y catas populares en el ferial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01053','fiesta','Fiestas de Salvatierra-Agurain y de San Millán','Patronal. Se celebra en Noviembre. Festejos rurales mínimos en una de las zonas agrícolas del llano, condicionados por la dispersión vecinal, basados en comidas familiares y ritos religiosos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50036','fiesta','Fiestas de Izarra en Honor a Nuestra Señora de la Antigua','Patronal / Etnográfica. Se celebra en Agosto. Festejos en la comarca de Zuia que destacan por sus tradicionales pasacalles de cabezudos, exhibiciones folclóricas de herri kirolak y verbenas lúdicas familiares en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50037','fiesta','Fiestas de Villanueva de Valdegovía y Fiesta de la Patata','Patronal / Gastronómica. Se celebra en Octubre. Festejos de fuerte arraigo por la tradicional e histórica Feria de la Patata de Valdegovía, cita de gran calado comarcal dedicada a la promoción agrícola y artesanal de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01057','fiesta','Fiestas en Honor a San Torcuato','Patronal / Enológica. Se celebra en Mayo. Pequeñas fiestas tradicionales en la zona de mayor densidad de bodegas por habitante, centradas en catas populares de vino de cooperativa, folclore y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','fiesta','Fiestas de la Virgen Blanca','Patronal / Etnográfica / Cultural. Se celebra en Agosto (Del 4 al 9). Fiesta de gran rango e impacto nacional. Célebre por el multitudinario hito etnográfico de la "Bajada de Celedón" paraguas en mano desde la torre de San Miguel, abriendo unas macrofiestas de enorme participación popular de cuadrillas de blusas y neskas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01060','fiesta','Fiestas de Santo Domingo y de la Virgen de Bercijana','Patronal / Etnográfica. Se celebra en Agosto. Destacan en la comarca por la espectacular e histórica marcha en romería hacia la ermita, donde los danzantes ejecutan la ancestral "Cadena de Yécora" al son de gaitas de solera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01062','fiesta','Fiestas de Santa Lucía','Patronal. Se celebra en Agosto. Festejos estivales de marcado carácter familiar en el confín con Burgos, basados en comidas de hermandad, partidos de pelota mano en el frontón y verbenas lúdicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50041','fiesta','Fiestas del Valle de Zigoitia (Zigoitiako Jaiak)','Patronal / Etnográfica / Valle. Se celebra en Septiembre. Celebración que unifica las costumbres tradicionales de los numerosos núcleos a las faldas del monte Gorbea, arropada por partidos de pelota vasca, música de trikitixas y cenas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50042','fiesta','Fiestas de Murgia en Honor a San Miguel Arcángel','Patronal / Etnográfica. Se celebra en Septiembre *. Festejos patronales tradicionales del valle de Zuia con amplia participación juvenil, pasacalles de cabezudos, música de txistularis y tradicionales comidas populares de hermandad). Hemos completado al 100% de forma exhaustiva todos los municipios de la provincia de Álava. ¿Deseas que continuemos de inmediato abriendo la segunda provincia del País Vasco en orden alfabético, que corresponde a Guipúzcoa (comenzando por su primer bloque de municipios de la A hasta la I)?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90669','fiesta','Fiestas Patronales de San Juan Bautista','Patronal / Etnográfica. Se celebra en Junio. Festejos tradicionales de fuerte identidad euskaldun en Tolosaldea, a las faldas del monte Txindoki, caracterizados por el encendido de la hoguera, exhibiciones de herri kirolak y verbenas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90670','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal / Etnográfica. Se celebra en Agosto. Celebración de escala local en el valle del Oria, centrada en la música de txistularis, campeonatos de pelota a mano en el frontón y el tradicional baile de la "Axeri Dantza" ejecutado por los jóvenes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90247','fiesta','Fiestas Patronales de San Donato y San Lorenzo','Patronal / Etnográfica. Se celebra en Agosto. Festejos de fuerte arraigo en Urola Kosta, destacados por sus populosas pruebas de bueyes (idi probak), música de trikitixas y verbenas que atraen a numerosa concurrencia comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90248','fiesta','Fiestas en Honor a San Miguel Arcángel','Patronal. Se celebra en Septiembre. Festejos tradicionales de marcado carácter familiar en el valle del Urola, fundamentados en comidas comunitarias de hermandad, bertsolaris y sesiones lúdicas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90249','fiesta','Fiestas de la Virgen del Rosario','Patronal / Gastronómica. Se celebra en Octubre. Festejos de arraigo local que ponen en valor la identidad de la villa mediante ritos litúrgicos y la tradicional degustación de sus famosas alubias negras con sacramentos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90250','fiesta','Fiestas de San Juan Bautista','Patronal / Cultural. Se celebra en Julio. Festejos patronales consolidados a nivel local y comarcal a orillas del Oria, caracterizados por el pasacalles de cabezudos, competiciones de pelota y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90251','fiesta','Fiestas Patronales de Santiago Apóstol','Patronal. Se celebra en Julio. Pequeña celebración de marcado carácter vecinal en las laderas de la sierra de Hernio, centrada en comidas de hermandad, música en directo de trikitixa y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20906','fiesta','Fiestas de San Miguel','Patronal. Se celebra en Septiembre. Mínima expresión festiva debido a la baja demografía de este pequeño municipio de Goierri, limitada a ritos religiosos tradicionales, una comida popular y música tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90252','fiesta','Fiestas Patronales de San Ignacio de Loyola','Patronal / Etnográfica. Se celebra en Julio. Festejos locales marcados por la hermandad vecinal, con tradicionales misas solemnes, partidos de pelota mano y competiciones tradicionales de deporte rural vasco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90253','fiesta','Fiestas de San Bartolomé','Patronal / Etnográfica. Se celebra en Agosto. Festejos de fuerte tradición pelotazale en Tolosaldea, destacados por las exhibiciones de herri kirolak, música de txistularis y danzas folclóricas locales en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90254','fiesta','Fiestas de San Juan Bautista','Patronal / Cultural / Etnográfica. Se celebra en Junio. Festejos de rango comarcal muy populares, célebres por el encendido de la monumental hoguera, el pasacalles de la comparsa de gigantes y cabezudos, tamborradas infantiles y conciertos multitudinarios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90695','fiesta','Fiestas en Honor al Corpus Christi','Patronal / Cultural. Se celebra en Mayo / Junio. Festejos patronales tradicionales del valle con pasacalles musicales, exhibiciones de danzas vascas tradicionales, espectáculos infantiles y orquestas populares en el pabellón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90255','fiesta','Fiestas de la Virgen de la Piedad (Mairuaren Alardea)','Etnográfica / Recreación Histórica / Patronal. Se celebra en Julio. Destaca a nivel provincial por el monumental hito etnográfico del Alarde del Moro, representación histórica catalogada que conmemora batallas medievales con trajes de época y salvas de pólvora.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90256','fiesta','Fiestas de San Martín','Patronal. Se celebra en Noviembre. Pequeña celebración rural invernal en el municipio menos poblado de Guipúzcoa, centrada en ritos religiosos tradicionales, una comida de hermandad y música local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21001','fiesta','Fiestas de Andra Mari y los "Atorrak" de Carnaval','Patronal / Carnaval / Etnográfica. Se celebra en Febrero (Carnaval) y Agosto (Andra Mari). Festejos de rango comarcal en Debagoiena; destaca el gran valor de su Carnaval tradicional con la parodia de los "Atorrak" y los bailes satíricos populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21002','fiesta','Fiestas de San Juan y el Día de los "Maritxu Kajoi"','Patronal / Cultural / Singular. Se celebra en Junio (San Juan) y Octubre (Maritxu Kajoi). Su singular fiesta de "Maritxu Kajoi", dedicada a los amantes del vino y los disfraces elegantes, posee un masivo impacto regional y atrae a miles de jóvenes de toda la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90257','fiesta','Fiestas en Honor a San Pedro','Patronal / Etnográfica. Se celebra en Junio. Celebración de arraigo local tradicionales en el valle de Aiztondo, caracterizada por las demostraciones de deporte rural vasco, bertsolaris y verbenas lúdicas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20903','fiesta','Fiestas de Santiago Apóstol y la Apertura del Txotx (Sagardo Berria)','Patronal / Enológica / Gastronómica. Se celebra en Enero (Txotx) y Julio (Santiago). La apertura de la temporada de sidrerías vascas es un hito cultural y gastronómico de rango nacional absoluto, congregando en el epicentro de la sidra a miles de visitantes para probar el primer mosto.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90258','fiesta','Fiestas de San Martín y el Día del Mito (Mitologia Eguna)','Patronal / Mitológica / Etnográfica. Se celebra en Noviembre. Destaca en Goierri por la espectacular representación de leyendas mitológicas vascas basada en la obra de Barandiaran, transformando la localidad con personajes mágicos ancestrales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21003','fiesta','Fiestas de Andra Mari (Andramariak)','Patronal / Etnográfica. Se celebra en Agosto. Festejos mayores de rango comarcal en el valle del Urola, muy populares por sus solemnes procesiones, monumentales partidos de pelota mano en sus históricos frontones y espectáculos folclóricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21004','fiesta','Fiestas de San Ignacio de Loyola y la Euskal Herriko Antzerki Topaketak','Patronal / Cultural / Taurina. Se celebra en Julio (San Ignacio) y Noviembre (Teatro). Festejos de enorme arraigo regional vinculados al Santuario de Loyola, célebres por su feria taurina de solera, los multitudinarios toros ensogaos (sokamuturra) y pasacalles folclóricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20904','fiesta','Fiestas en Honor a San Juan Bautista','Patronal. Se celebra en Agosto. Festejos rurales mínimos de carácter estrictamente familiar en Tolosaldea debido a la bajísima demografía, limitados a ritos religiosos y un almuerzo de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21005','fiesta','Fiestas de Loinatz (Loinatz Jaiak)','Patronal / Cultural / Etnográfica. Se celebra en Mayo / Junio. Grandes fiestas de uno de los motores económicos de Goierri, caracterizadas por la tradicional bajada de Mari, populosas tamborradas, festivales de danzas y macroconciertos públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20020','fiesta','Fiestas de San Lorenzo','Patronal. Se celebra en Agosto. Festejos rurales mínimos condicionados por la despoblación en el centro geográfico de la provincia, basados en una misa mayor tradicional y encuentros vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20021','fiesta','Fiestas en Honor a San Juan Bautista','Patronal *. Se celebra en Junio *. Pequeña festividad local de marcado ambiente familiar e infantil adaptada al vecindario del núcleo rural, con partidos de pelota y música en directo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20023','fiesta','Fiestas Patronales de San Andrés','Patronal. Se celebra en Agosto. Festejos veraniegos de carácter local trasladados de época para captar la afluencia de veraneantes, consistentes en comidas colectivas de hermandad y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90696','fiesta','Fiestas de San Bartolomé en Bidania','Patronal / Etnográfica. Se celebra en Agosto. Festejos de montaña en el interior guipuzcoano que destacan por sus tradicionales exhibiciones de deporte rural vasco, bertsolaris locales y comidas populares al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21007','fiesta','Fiestas de San Roque (Sanroqueak)','Patronal / Taurina / Etnográfica. Se celebra en Agosto. Grandes fiestas costeras de rango comarcal célebres por su histórica tradición taurina, con encierros matutinos playeros, capeas de reses bravas en la plaza e históricos bailes tradicionales como la "Esku Dantza".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21008','fiesta','Fiestas de San Juan y Fiesta de San Andrés','Patronal / Cultural / Feria Tradicional. Se celebra en Junio (San Juan) y Noviembre (San Andrés). Grandes celebraciones de la capital industrial de Debabarrena, destacando la inmensa feria agrícola tradicional de San Andrés con concursos de queso e Idiazabal, ganado y folklore vasco masivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90697','fiesta','Fiestas en Honor a Santa Catalina','Patronal. Se celebra en Septiembre. Pequeña celebración rural que unifica la escasa población del término en torno a actos religiosos tradicionales, partidos de pelota mano en el frontón y comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20033','fiesta','Fiestas de Ferixa Nausia','Patronal / Feria Tradicional. Se celebra en Septiembre. Festejos tradicionales marcados por la concurrida feria agrícola de origen medieval de la villa, combinando el fervor local con exhibiciones folclóricas de trikitixas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20032','fiesta','Fiestas de San Bartolomé','Patronal / Etnográfica. Se celebra en Agosto. Festejos de gran personalidad en Debabarrena, famosos por el Día de las Cuadrillas, exhibiciones de herri kirolak de primer nivel, pasacalles de la comparsa de gigantes y la tradicional sokamuturra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20067','fiesta','Madalenas (Fiestas de Santa María Magdalena)','Patronal / Cultural / Etnográfica. Se celebra en Julio (Del 21 al 25). Grandes festejos de rango comarcal en Oarsoaldea con masiva participación vecinal, célebres por el emotivo txupinazo con la "Centenaria", tamborradas multitudinarias, conciertos públicos y pasacalles de gigantes de solera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90698','fiesta','Fiestas de San Martín','Patronal / Gastronómica. Se celebra en Noviembre. Festejos de montaña en el valle del Urola, caracterizados por ritos tradicionales religiosos, folclore vasco y la gran promoción agrícola de sus famosas manzanas reinetas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21009','fiesta','Fiestas de San Pedro y el Baile de la Era (Eskoriatzako Larrain Dantza)','Patronal / Etnográfica / Danza Tradicional. Se celebra en Junio. Festejos de arraigo en Debagoiena que destacan por la multitudinaria y vistosa ejecución popular de la Larrain Dantza en la plaza del ayuntamiento, arropada por un gran ambiente de cuadrillas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90699','fiesta','Fiestas de San Miguel en Ezkio y del Santo Cristo en Itsaso','Patronal / Etnográfica. Se celebra en Mayo y Septiembre. Festejos unificados de ámbito rural guipuzcoano que ponen en valor la identidad de sus caseríos, con demostraciones artesanales de sidra en el caserío Igartubeiti y deporte rural vasco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90941','fiesta','Fiestas de Andra Mari y el Certamen de Bertsolaris de Goierri','Patronal / Cultural / Tradición Oral. Se celebra en Agosto. Festividad de gran peso identitario en Goierri, célebre por albergar un consolidado e histórico concurso de versificadores tradicionales vascos que congrega a numerosos amantes de la cultura oral.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20037','fiesta','Fiestas en Honor a San Miguel','Patronal. Se celebra en Septiembre. Festejos rurales mínimos en una de las localidades de menor demografía de la sierra de Aralar, limitados a actos litúrgicos religiosos, juegos populares infantiles y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20907','fiesta','Fiestas de San Ignacio','Patronal. Se celebra en Julio. Pequeña celebración vecinal de alta montaña en Tolosaldea, basada en ritos litúrgicos tradicionales, partidos de pelota mano en el frontón y cenas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21010','fiesta','Fiestas de San Salvador y la Desembarco de Elcano','Patronal / Recreación Histórica / Marinera / Cuatrienal. Se celebra en Agosto (Desembarco cada 4 años). Declarada Fiesta de Interés Turístico del rango regional. Su espectacular y masiva recreación del regreso de Juan Sebastián Elcano tras dar la vuelta al mundo transforma por completo el puerto y casco histórico medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20040','fiesta','Fiestas de San Juan (Sanjoanak) y la "Azeri Dantza"','Patronal / Etnográfica / Danza Tradicional. Se celebra en Junio. Grandes fiestas del área metropolitana, muy populares por la espectacular e histórica "Azeri Dantza" (baile del zorro) que recorre las calles interactivamente, sumando macroconciertos y tamborradas masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20041','fiesta','Fiestas en Honor a la Virgen de la Asunción','Patronal. Se celebra en Agosto. Pequeña festividad local de marcado carácter familiar para el vecindario del núcleo rural, estructurada sobre una misa mayor, comidas populares al aire libre y música tradicional de trikitixa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21011','fiesta','Fiestas de la Virgen de Guadalupe y el Alarde de Hondarribia','Patronal / Cívico-Militar / Recreación Histórica. Se celebra en Septiembre (Del 6 al 10). Declarada Fiesta de Interés Turístico Nacional. Espectacular hito cívico-militar de impacto masivo, donde miles de vecinos armados y uniformados marchan en compañías de infantería celebrando el fin del asedio de 1638.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20042','fiesta','Fiestas de San Bartolomé','Patronal / Gastronómica. Se celebra en Agosto. Festejos de fuerte arraigo comarcal que ponen en valor la identidad hortícola local mediante la promoción de sus afamados guindillas o "piparras" de Ibarra, arropados por danzas vascas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20043','fiesta','Fiestas de San Blas y el Día del Queso de Idiazabal','Patronal / Gastronómica / Etnográfica. Se celebra en Febrero (San Blas) y Mayo (Día del Queso). Hito gastronómico provincial de enorme prestigio que promociona el queso artesano de oveja latxa con D.O. de la localidad, reuniendo mercados tradicionales de pastores, folklore y catas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20044','fiesta','Fiestas en Honor a San Lorenzo','Patronal. Se celebra en Agosto. Festejos tradicionales del valle del Oria con comidas populares de hermandad vecinal, partidos de pelota mano y música en la plaza mayor del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21012','fiesta','Fiestas de San Pedro y San Marcial (Alarde de San Marcial)','Patronal / Cívico-Militar / Histórica. Se celebra en Junio (Día de San Marcial el 30 de junio). Fiesta de gran rango e impacto masivo de la segunda urbe guipuzcoana. Célebre por su monumental Alarde, donde miles de soldados organizados por compañías desfilan rememorando la victoria de 1522 ante tropas franco-navarras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20046','fiesta','Fiestas de San Miguel','Patronal. Se celebra en Septiembre *. Festejos locales de carácter familiar en Tolosaldea, basados en juegos infantiles tradicionales, misas solemnes tradicionales y sesiones lúdicas de trikitixa para el vecindario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20047','fiesta','Fiestas en Honor a San Juan Bautista','Patronal. Se celebra en Junio. Festejos tradicionales del llano de Goierri basados en comidas de hermandad, partidos de pelota en el frontón municipal, encendido de la hoguera y música de plaza). ¿Deseas continuar con el Siguiente Bloque de la provincia de Guipúzcoa (Letras de la L en adelante.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20048','fiesta','Fiestas Patronales de San Esteban','Patronal. Se celebra en Agosto. Festejos estivales de marcado arraigo vecinal en la comarca de Tolosaldea, condicionados por su baja demografía, sustentados en misas solemnes tradicionales, partidos de pelota y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90700','fiesta','Fiestas de San Prudencio y el Auto Sacramental del Día de Reyes','Patronal / Etnográfica / Teatral. Se celebra en Enero (Reyes) y Abril (San Prudencio). Festejos que destacan en el Goierri por la monumental y secular representación teatral de la Huida a Egipto por sus calles medievales, atrayendo a numerosa concurrencia provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20050','fiesta','Fiestas Patronales de San Pedro','Patronal. Se celebra en Junio. Pequeños festejos de montaña de carácter puramente familiar compartidos con el núcleo de Txarama, con ritos religiosos tradicionales, competiciones infantiles y almuerzo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20051','fiesta','Fiestas de Santikutz (Santacruces) y el Día de la Ezpata Dantza','Patronal / Etnográfica / Danza Tradicional. Se celebra en Mayo. Festejos de gran personalidad en el Alto Urola, célebres por la espectacular y antiquísima ejecución de la Ezpata Dantza de Legazpi por parte de los dantzaris locales, un hito folclórico de alta raigambre regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20052','fiesta','Fiestas de San Salvador (Ascensión)','Patronal / Etnográfica. Se celebra en Mayo. Festejos de arraigo tradicional en el Goierri central, caracterizados por el desfile del "Sorgin" o personaje mitológico local, exhibiciones de herri kirolak, trikitixas y verbenas lúdicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20053','fiesta','Fiestas del Santo Cristo (Santacruces)','Patronal / Etnográfica. Se celebra en Septiembre. Destacan provincialmente en Oarsoaldea por el fervor hacia su Basílica del Santo Cristo, hito tradicional que congrega a numerosos visitantes con masivas tamborradas, danzas vascas y conciertos populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20054','fiesta','Fiestas en Honor a la Virgen del Rosario y la Lizartzako Ezpata Dantza','Patronal / Etnográfica / Danza Tradicional. Se celebra en Septiembre. Festejos en el valle del Araxes famosos provincialmente por la pureza de sus dantzaris al bailar la Ezpata Dantza tradicional de Carnaval y de fiestas mayores, una joya folclórica local de alta raigambre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90942','fiesta','Fiestas Patronales de San Pedro','Patronal. Se celebra en Junio. Pequeña celebración rural en el Goierri profundo adaptada a su baja demografía, centrada en comidas comunitarias de hermandad, desafíos de herri kirolak y música tradicional en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90039','fiesta','Fiestas de las Magdalenas y el Día de las "Berdel Jaiak"','Patronal / Marinera / Gastronómica. Se celebra en Abril (Berdel Jai) y Julio (Magdalenas). Grandes fiestas costeras de rango comarcal; su fiesta gastronómica dedicada a la exaltación del verdel destaca provincialmente por el reparto masivo de pinchos artesanales en los muelles de la villa marinera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20058','fiesta','Fiestas en Honor a San Juan Bautista','Patronal. Se celebra en Junio. Festejos locales en el denominado "Balcón de Goierri", orientados al reencuentro de familias, con encendido de hogueras de San Juan, partidos de pelota mano en el frontón y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21014','fiesta','Fiestas del Corpus Christi de Oñati y Fiestas de San Miguel (Sanmiguelak)','Religiosa / Etnográfica / Patronal. Se celebra en Junio (Corpus) y Septiembre (San Miguel). Su procesión y danzas del Corpus Christi ostentan una altísima consideración etnográfica nacional por la espectacular e histórica marcha de los dantzaris guiados por el capitán vestido de San Miguel, un rito milenario masivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90262','fiesta','Fiestas de Santa Ana y la Euskal Jaiak (Fiesta Vasca de Ordizia)','Patronal / Gastronómica / Feria Tradicional. Se celebra en Julio (Santa Ana) y Septiembre (Euskal Jaiak). Su gran mercado tradicional de la Fiesta Vasca alberga el histórico y mundialmente famoso Concurso de Quesos de Idiazabal de Ordizia, hito agroalimentario que atrae masiva afluencia y prensa nacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20905','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Mínima expresión festiva de carácter vecinal en Tolosaldea debido a la baja demografía del municipio, limitada a actos litúrgicos tradicionales, deportes rurales vascos mínimos y comidas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90701','fiesta','Fiestas Patronales de Santa Cruz','Patronal. Se celebra en Mayo. Pequeñas fiestas de montaña de carácter puramente vecinal en la Guipúzcoa más profunda, condicionadas por su reducida población, basadas en comidas de hermandad y música de trikitixa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20061','fiesta','Fiestas de San Pedro y el Día del Besugo (Bisiguaren Festa)','Patronal / Marinera / Gastronómica. Se celebra en Junio (San Pedro) y Julio (Besugo). Festejos en la ría de Urola Kosta muy populares, célebres por exaltar el arte del asado tradicional del besugo en las parrillas callejeras de la villa pesquera, arropados por regatas de traineras y folklore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20062','fiesta','Fiestas de San Andrés y la Fira de la Morcilla (Buszkantz Festa)','Patronal / Gastronómica. Se celebra en Noviembre. Festejos de Goierri destacados por la feria tradicional dedicada a la morcilla de oveja o "buskantz", hito tradicional que atrae provincialmente a numeroso público gastronómico y mercados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21015','fiesta','Fiestas de Santiago en Pasai Donibane y el Pasaia Itsas Festibala','Marinera / Cultural / Romería / Bienal. Se celebra en Julio (Santiago) y Mayo (Itsas Festibala). Su Festival Marítimo Internacional posee rango e impacto masivo a nivel de toda la cornisa cantábrica, reuniendo en la histórica bahía a cientos de embarcaciones tradicionales de todo el mundo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20070','fiesta','Fiestas de San Juan y Campeonato de Baile al Suelto de Euskal Herria','Patronal / Cultural / Etnográfica. Se celebra en Junio (San Juan) y Octubre (Campeonato). De enorme relevancia cultural en la provincia por albergar el monumental concurso de baile tradicional al suelto de Euskadi en su histórico casco amurallado medieval, un hito del folclore vasco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90702','fiesta','Fiestas de Santiago y Santa Ana','Patronal / Cultural. Se celebra en Julio. Festejos tradicionales de la cuenca del Deba, caracterizados por el desfile de las cuadrillas locales, exhibiciones de corte de troncos, pasacalles de la comparsa de cabezudos y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20071','fiesta','Carnaval de Tolosa (Iñauteriak) y Fiestas de San Juan','Etnográfica / Carnaval Tradicional / Patronal. Se celebra en Febrero (Carnaval) y Junio (San Juan). Su Carnaval está declarado de rango nacional y gran relevancia etnográfica por ser uno de los pocos supervivientes a las prohibiciones históricas, congregando masivamente a la provincia con carrozas satíricas y charangas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20072','fiesta','Fiestas de San Miguel Arcángel','Patronal / Etnográfica. Se celebra en Septiembre. Festejos patronales tradicionales del área metropolitana, caracterizados por el tradicional pasacalles, partidos de pelota mano, bailes tradicionales y activa participación de las peñas de jóvenes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90703','fiesta','Festes de Santa Anastasia (Euskal Jaiak)','Patronal / Etnográfica / Valle. Se celebra en Septiembre. Hito tradicional de gran renombre en el Alto Urola, célebre por su espectacular Desfile de Carrozas artesanales tiradas por bueyes, construidas por las cuadrillas del pueblo, acompañadas de trikitixas y jotas vascas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20073','fiesta','Fiestas de San Esteban y el Día de la Sidra (Sagardo Eguna) *','Patronal / Gastronómica / Enológica *. Se celebra en Mayo (Sagardo Eguna) y Julio (San Esteban) *. Su Sagardo Eguna posee rango comarcal muy consolidado en el valle del Oria, hito pionero en Guipúzcoa que reúne la degustación masiva de sidra artesanal de los caseríos de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20075','fiesta','Fiestas de Santiago (Santioak) en Amasa-Villabona','Patronal / Etnográfica. Se celebra en Julio. Celebración tradicional del corredor del Oria con notables desafíos tradicionales de rebote (modalidad de pelota vasca antigua), pasacalles de gigantes comarcales y verbenas lúdicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20078','fiesta','Fiestas en Honor a Santa Fe y el Día del "Mondeju"','Patronal / Gastronómica. Se celebra en Octubre. Festejos a los pies del Aralar que destacan por la exaltación gastronómica del "mondeju", un embutido artesanal de oveja latxa milenario de la montaña, arropado por bertsolaris y folklore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21018','fiesta','Festes de la Virgen de la Asunción (San Pelaio y Euskal Jaiak)','Patronal / Etnográfica / Costera. Se celebra en Junio (San Pelaio) y Septiembre (Euskal Jaiak). La Euskal Astea y su Fiesta Vasca de septiembre poseen rango e impacto masivo de carácter regional en toda la costa, famosa por la mítica e histórica reunión de miles de personas luciendo de gala el traje tradicional de casero vasco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90943','fiesta','Fiestas de San Bartolomé y Romería de San Adrián','Patronal / Romería / Etnográfica. Se celebra en Mayo (Romería) y Agosto (San Bartolomé). Festejos de montaña en el paso de las Parzonerías, famosos por la romería tradicional a la ermita rupestre del túnel de San Adrián, sumando el folclore pastoril de la sierra y la masiva afluencia comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90944','fiesta','Fiestas Patronales de Santiago Apóstol','Patronal / Etnográfica. Se celebra en Julio. Festejos que ensalzan la vida rural del caserío y su pasado minero en Goierri, combinando las verbenas populares con competiciones de deporte rural vasco tradicionales artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90945','fiesta','Fiestas de la Virgen de la Natividad (Amabirjinak)','Patronal / Taurina / Etnográfica. Se celebra en Septiembre. Festejos de rango comarcal tradicionales en el valle del Urola, famosos provincialmente por sus históricas capeas de reses bravas en la plaza del ayuntamiento forrada de madera, con aurresku y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90946','fiesta','Fiestas de la Virgen de la Asunción y San Millán','Patronal. Se celebra en Agosto y Noviembre. Festejos tradicionales de Tolosaldea que unifican las costumbres de la plaza y de la zona baja industrial, con verbenas al aire libre, partidos de pelota mano y espectáculos lúdicos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21019','fiesta','Fiestas de San Pedro y Fiestas de San Telmo','Patronal / Marinera / Costera. Se celebra en Abril (San Telmo) y Junio (San Pedro). Festejos de gran sabor marinero junto al Flysch, célebres por las procesiones marítimas a la ermita de San Telmo vistiendo los marineros camisas tradicionales de color azul marino, entre regatas y folklore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21020','fiesta','Fiestas de Santa Isabel y la Ezpata Dantza de la Antigua','Patronal / Romería / Etnográfica / Danza Tradicional. Se celebra en Julio (Día de Santa Isabel el 2 de julio). Declarada de gran relevancia etnográfica nacional. Espectacular hito folclórico e histórico de los Pirineos vascos, célebre por la impresionante procesión hacia la mítica Ermita de La Antigua, donde los dantzaris ejecutan la Ezpata Dantza frente al altar mayor). Hemos completado al 100% de forma exhaustiva todos los municipios de la provincia de Guipúzcoa, finalizando así por completo la segunda provincia del País Vasco. ¿Deseas que continuemos de inmediato abriendo la tercera y última provincia del País Vasco según el orden oficial, que corresponde a Vizcaya (comenzando por su primer bloque de municipios de la A hasta la I.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90667','fiesta','Fiestas de San Pedro en Las Carreras y Fiesta de la Trinidad en Gallarta','Patronal / Etnográfica / Histórica. Se celebra en Junio. Festejos vinculados al pasado minero de Las Encartaciones, destacados por las exhibiciones de barrenadores (barrenatzaileak) cortando bloques de piedra y desfiles populares de cuadrillas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48911','fiesta','Fiestas en Honor a la Ascensión','Patronal. Se celebra en Mayo / Junio. Festejos rurales de arraigo estrictamente local en Busturialdea, condicionados por su baja demografía, sustentados en misas solemnes, partidos de pelota mano en el frontón y verbenas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48912','fiesta','Fiestas Patronales de San Antolín','Patronal. Se celebra en Septiembre. Celebración de escala local en el valle del Cadagua que congrega a los vecinos del municipio en torno a pasacalles con txistularis, campeonatos de mus, concursos gastronómicos de paellas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90947','fiesta','Fiestas de Santiago Apóstol (Karmenak)','Patronal / Cultural / Etnográfica. Se celebra en Julio. Grandes fiestas mayores de rango comarcal, muy populares en Zornotza por sus populosos desfiles de cuadrillas con disfraces, la tamborrada local, exhibiciones de herri kirolak de primer nivel y macroconciertos públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90668','fiesta','Fiestas de San Martín','Patronal. Se celebra en Julio. Pequeña celebración vecinal en Lea-Artibai de fuerte identidad euskaldun, estructurada con ritos religiosos tradicionales en la parroquia, bertsolaris y pequeñas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47002','fiesta','Fiestas en Honor a Santa Marina','Patronal. Se celebra en Julio. Mínima expresión festiva de carácter familiar en el municipio menos poblado de Vizcaya, limitada a una misa mayor tradicional, partidos de pelota infantil en el frontón y una comida compartida entre los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90683','fiesta','Fiestas Patronales de San Pedro','Patronal. Se celebra en Junio. Pequeñas fiestas de arraigo puramente local en el valle de Arratia, caracterizadas por comidas de hermandad vecinal al aire libre, música de trikitixa y competiciones deportivas municipales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90684','fiesta','Fiestas de San Vicente y de San Pedro','Patronal / Etnográfica. Se celebra en Junio. Festejos unificados de ámbito rural en las faldas del monte Oiz, centrados en tradicionales misas solemnes, campeonatos locales de mus, exhibiciones de deporte rural vasco y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90685','fiesta','Fiestas de San Antolín en Traslaviña','Patronal. Se celebra en Septiembre. Celebración tradicional de las Encartaciones basada en el reencuentro de familias, estructurada con procesiones tradicionales a la ermita, comidas populares y verbenas lúdicas familiares en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48009','fiesta','Fiestas Patronales de Nuestra Señora de la Asunción','Patronal / Etnográfica. Se celebra en Agosto. Festejos locales que combinan las actividades infantiles y juveniles en el valle del Nervión, destacando los concursos de tortilla de patatas y marmitako, exhibiciones de danzas vascas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90948','fiesta','Fiestas en Honor a Santo Tomás','Patronal. Se celebra en Diciembre. Festejos rurales invernales de carácter vecinal en la Reserva de la Biosfera de Urdaibai, basados en ritos litúrgicos tradicionales, piteros y mercados menores de productos artesanos del caserío.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48010','fiesta','Fiestas Patronales de San Martín','Patronal. Se celebra en Noviembre. Celebración puramente vecinal a las faldas del monte Sollube, fundamentada en actos religiosos tradicionales en el templo parroquial, campeonatos de mus y comidas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48011','fiesta','Fiestas Patronales de Santa María Magdalena','Patronal / Cultural / Etnográfica. Se celebra en Julio (Del 21 al 25). Festejos de rango comarcal en el área metropolitana de Bilbao, caracterizados por la tradicional bajada de la "Madalena", desfiles de cuadrillas locales muy activos, grandes verbenas nocturnas y competiciones de pelota.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90949','fiesta','Fiestas de San Juan en Axpe y Fiestas de San Pedro en Apatamonasterio','Patronal / Etnográfica. Se celebra en Junio. Festejos tradicionales bajo la impresionante mole caliza de la crestería de Anboto, célebres por la plantación del "Doniene Atxa" (árbol de San Juan) y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90055','fiesta','Fiestas de San Juan Dolozak y Fiesta del Txakoli','Patronal / Enológica / Costera. Se celebra en Agosto (Patronales) y Marzo (Txakoli). Festejos de gran personalidad costera en Uribe Kosta; su feria dedicada a la exaltación del txakoli de Bakio posee un notable peso comarcal, atrayendo a numeroso público y surfistas de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47001','fiesta','La Pasión Viviente de Balmaseda y Fiestas de San Severino','Teatral / Religiosa / Gastronómica / Patronal. Se celebra en Marzo / Abril (Semana Santa) y Octubre (San Severino). Su impresionante vía crucis y Pasión Viviente está declarada Fiesta de Interés Turístico Nacional. En octubre, destaca a nivel regional por el célebre y multitudinario Concurso de Putxeras de San Severino (olla ferroviaria tradicional).','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47002','fiesta','Fiestas del Carmen (Karmenak)','Patronal / Cultural / Urbana. Se celebra en Julio. Grandes fiestas mayores de la segunda ciudad más populosa de la provincia. Destacan por la multitudinaria bajada de la mascota "Jolín", conciertos públicos masivos, populosos recintos de txosnas y desfiles de cuadrillas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90950','fiesta','Fiestas en Honor a San Juan Bautista','Patronal / Costera. Se celebra en Junio. Festejos tradicionales de la costa que combinan el encendido de las tradicionales hogueras con pasacalles musicales, comidas vecinales y orquestas veraniegas dinamizadas por el turismo residencial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48015','fiesta','Fiestas de San Fausto','Patronal / Etnográfica / Cultural. Se celebra en Octubre (Alrededor del 13 de octubre). Festejos de gran peso y trascendencia comarcal, célebres por la multitudinaria bajada de la "Eskarabilera", los concurridos lonjas de las 16 cuadrillas locales y un impresionante desfile folclórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48092','fiesta','Fiestas Patronales de San Juan Bautista','Patronal. Se celebra en Junio. Festejos de ámbito estrictamente local en el valle de Arratia, consistentes en pasacalles tradicionales con txistularis, partidos de pelota mano en el frontón y verbenas lúdicas familiares en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48016','fiesta','Fiestas de Santa Ana y de Santo Domingo','Patronal. Se celebra en Julio y Agosto. Festejos con notable raigambre y crecimiento en el área metropolitana bilbaína, destacados por sus pasacalles, campeonatos de deporte rural vasco, paelladas masivas y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48017','fiesta','Fiestas de Andra Mari (Andramariak) y Día de San Juan en San Juan de Gaztelugatxe','Patronal / Marinera / Etnográfica. Se celebra en Junio (San Juan) y Septiembre (Andra Mari) *. Declaradas de gran interés regional y costero. Destacan por la procesión marítima tradicional a Izaro en la festividad de Santa María Magdalena y la masiva peregrinación a la mítica e histórica ermita de Gaztelugatxe.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48018','fiesta','Fiestas en Honor a San Pedro','Patronal / Etnográfica. Se celebra en Junio. Celebración de la comarca de Lea-Artibai con tradicionales pasacalles de dantzaris locales, competiciones de pelota mano y una activa participación vecinal en las comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48019','fiesta','Fiestas de San Pedro y de Santa Isabel','Patronal / Etnográfica / Danza Tradicional. Se celebra en Junio y Julio. Festejos que destacan en Durangaldea por la espectacular ejecución de la histórica "Dantzari Dantza" de Berriz frente a la iglesia, una joya del folclore vasco de altísima raigambre local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48020','fiesta','Semana Grande de Bilbao (Aste Nagusia)','Patronal / Etnográfica / Cultural / Urbana. Se celebra en Agosto (Comienza el primer sábado siguiente al 15 de agosto). Declarada Fiesta de Interés Turístico Internacional de forma consolidada. Macrocelebración masiva de primer orden mundial; famosa por el txupinazo con Marijaia, el colosal recinto de txosnas junto a la ría y los conciertos masivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48021','fiesta','Fiestas de San Cristóbal y del Rosario','Patronal / Etnográfica. Se celebra en Julio y Octubre. Festejos tradicionales en el corazón de Urdaibai, caracterizados por pasacalles de txistularis, tradicionales desafíos de deporte rural vasco en el ferial y comidas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48901','fiesta','Fiestas de San Isidro y de Santiago Apóstol','Patronal / Cultural. Se celebra en Mayo y Julio. Festejos en la comarca de Txorierri muy dinámicos, caracterizados por los concursos gastronómicos de sukalki, pasacalles tradicionales vascos, eventos infantiles y orquestas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48026','fiesta','Fiestas Patronales de San Pedro','Patronal / Etnográfica. Se celebra en Junio. Festejos de gran personalidad en el valle de Arratia, célebres por la conservación del folclore vasco, exhibiciones de arrastre de piedra por bueyes y ferias tradicionales menores de artesanía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48027','fiesta','Festes de San Fausto (Sanfaustoak)','Patronal / Etnográfica / Cultural. Se celebra en Octubre (Alrededor del 13 de octubre). Grandes fiestas de la capital de Durangaldea, muy populares por sus históricas diadas de dantzaris bailando la dantzari-dantza y el gorulari-dantza, acompañados de gigantes, zezenak dira (toros ensogaos) y conciertos masivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48028','fiesta','Fiestas de San Juan Bautista','Patronal / Marinera. Se celebra en Junio. Festejos tradicionales de hondo calado marinero en esta estrecha ría costera, caracterizados por el encendido de la hoguera a la orilla del mar, pasacalles de trikitixas y cenas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47006','fiesta','Fiesta de las Madalenas (Madalenak)','Etnográfica / Marinera / Singular. Se celebra en Julio (22 de julio). Hito tradicional de gran relevancia costera coorganizado con Bermeo y Mundaka. Espectacular y multitudinaria fiesta donde la comitiva del alcalde de Bermeo lanza una teja al mar certificando los límites marinos del peñón, inundando el puerto de jóvenes vestidos de azul y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48032','fiesta','Fiestas de la Virgen de la Purísima Concepción (Ferixa Nausia) i Errebonbilloak','Patronal / Etnográfica / Histórica / CívicoMilitar. Se celebra en Septiembre (Ferixa Nausia) y Octubre (Errebonbilloak). Su singular hito etnográfico militar de los "Errebonbilloak" en octubre ostenta gran fama autonómica, recreando una histórica milicia civil armada que realiza salvas de fusilería por su monumental casco antiguo protegido.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48902','fiesta','Fiestas de San Agustín en Altzaga y de San Lorenzo en Astrabudua','Patronal / Cultural / Urbana. Se celebra en Agosto. Festejos de rango comarcal integrados en el área metropolitana de la ría del Nervión, dotados de un potente programa que incluye populosas txosnas, conciertos públicos de primer nivel y desfiles de cuadrillas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48033','fiesta','Fiestas Patronales de San Miguel','Patronal. Se celebra en Septiembre. Pequeña celebración rural en una de las zonas altas de Busturialdea junto a sus históricas canteras de mármol rojo, con ritos religiosos tradicionales, partidos de pelota y vermut popular vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48034','fiesta','Fiestas de Santiago Apóstol (Santiagotiak)','Patronal / Cultural / Etnográfica. Se celebra en Julio. Festejos mayores de gran vitalidad al límite con Guipúzcoa, célebres por los populosos pasacalles de txarangas locales, el txupinazo de cuadrillas muy ruidoso, exhibiciones folclóricas de danzas tradicionales y conciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90951','fiesta','Fiestas en Honor a San Lorenzo','Patronal. Se celebra en Agosto. Pequeñas fiestas de marcado ambiente vecinal en el interior de Busturialdea, organizadas por la población para partidos de pelota mano en el frontón de piedra y comidas colectivas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90686','fiesta','Fiestas Patronales de San Esteban','Patronal / Cultural. Se celebra en Diciembre (Oficial) y Julio (Festejos estivales). Festejos en el área periurbana de Bilbao muy concurridos por la población juvenil, caracterizados por un amplio programa lúdico de conciertos en el ferial, concursos de paellas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90687','fiesta','Fiestas Patronales de San Andrés','Patronal / Etnográfica. Se celebra en Noviembre. Celebración de montaña en LeaArtibai de fuerte identidad rural, caracterizada por las demostraciones tradicionales de herri kirolak, música de trikitixas locales y cenas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48906','fiesta','Fiestas Patronales de San Martín','Patronal. Se celebra en Noviembre. Festejos de escala estrictamente local a orillas de la ría de Gernika, estructurados sobre la misa tradicional solemnizada por el coro local, campeonatos de mus y comidas comunitarias de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90671','fiesta','Festes de Santa Cruz (Santakurtzak)','Patronal / Cultural / Etnográfica. Se celebra en Septiembre. Festejos mayores con gran peso comarcal en el valle del Ibaizabal, caracterizados por los concursos gastronómicos tradicionales de cazuelas de sukalki con leña, desfiles de cuadrillas masivos y conciertos públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48037','fiesta','Fiestas de San Pedro y Fiesta del Pan del Santo','Patronal / Etnográfica / Gastronómica. Se celebra en Junio. Festejos tradicionales en el interior serrano de Las Encartaciones, destacados por el tradicional reparto del pan bendecido, desafíos rurales de arrastre de piedra y comidas al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48038','fiesta','Fiestas en Honor a San Andrés de Gamiz y San Martín de Fika','Patronal. Se celebra en Noviembre. Festejos rurales unificados que dinamizan los caseríos de la comarca de Mungialdea, consistentes en pasacalles tradicionales vascos, bertsolaris de la zona y cenas vecinales de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90688','fiesta','Fiestas de Santiago y de Santa Ana','Patronal / Etnográfica / Danza Tradicional. Se celebra en Julio. Destacan en Durangaldea por la pureza de sus dantzaris al bailar la histórica Ezpata Dantza de Gari frente a la ermita, hito folclórico de alta consideración regional apoyado por los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90689','fiesta','Fiestas Patronales de San Bartolomé','Patronal / Etnográfica. Se celebra en Agosto. Celebración tradicional de la comarca de Uribe con vistosas exhibiciones de deporte rural de tronzalaris y aizcolaris, parrilladas populares y verbenas lúdicas junto al castillo de Butrón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48041','fiesta','Fiestas en Honor a San Policarpo *','Patronal *. Se celebra en Enero y Septiembre (Festejos estivales) *. Festejos locales de carácter tradicional y familiar en Urdaibai, basados en la misa tradicional en la iglesia histórica, comidas populares de hermandad al aire libre y música de parrandas vascas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90690','fiesta','Fiestas en Honor a San Juan y San Roque','Patronal / Feria Ganadera Tradicional. Se celebra en Agosto y Septiembre. Festejos en las Encartaciones orientados a ensalzar las costumbres agrícolas y ganaderas de sus valles coloniales, albergando ferias tradicionales de reses de montaña y mercados artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48043','fiesta','Fiestas de Santiago Apóstol (Santiagotiak)','Patronal / Costera / Cultural. Se celebra en Julio. Festejos costeros de rango comarcal muy populares, célebres por su concurso tradicional de marmitako en las campas de la playa, atrayendo a miles de personas de la provincia a sus verbenas masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47008','fiesta','Fiestas de San Ignacio en Algorta y Concurso Internacional de Paellas de Aixerrota','Patronal / Gastronómica / Etnográfica / Cultural. Se celebra en Julio (Paellas el 25 de julio). Su Concurso Internacional de Paellas de Aixerrota en los acantilados de la costa está considerado un hito multitudinario de rango nacional absoluto, congregando de forma festiva a decenas de miles de personas en cabañas construidas en la campa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48045','fiesta','Fiestas de San Pedro y Feria de San José de Güeñes','Patronal / Feria de Sector / Tradicional. Se celebra en Marzo (San José) y Junio (San Pedro). Festejos que destacan en las Encartaciones por su histórica y concurrida Feria de San José de rango comarcal, famosa por el concurso de perro pastor vasco, muestras ganaderas y mercados verdes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90691','fiesta','Fiestas de San Antonio (Sanantonak)','Patronal / Cultural / Etnográfica. Se celebra en Junio. Grandes fiestas mayores de la capital del valle de Arratia, muy populares por su activa implicación vecinal en las txosnas, campeonatos de pelota vasca de solera, aurresku y conciertos multitudinarios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48049','fiesta','Fiestas Patronales de Santiago Apóstol','Patronal / Etnográfica. Se celebra en Julio. Celebración de la costa de LeaArtibai con notable arraigo por la conservación de ritos tradicionales de deporte vasco, comidas populares de hermandad vecinal en las campas y música de trikitixa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90952','fiesta','Festes de San Miguel de Iurreta','Patronal / Etnográfica / Danza Tradicional. Se celebra en Septiembre. Festejos de hondo calado tradicional en Durangaldea, famosos provincialmente por la magnífica ejecución de la ancestral e histórica "Dantzari Dantza" y el baile tradicional de las banderas locales frente a la parroquia). Hemos finalizado de forma exhaustiva el Bloque 1 de la provincia de Vizcaya, cubriendo todos los municipios hasta la letra I de forma rigurosa y scannable. ¿Deseas continuar con el Siguiente Bloque de la provincia de Vizcaya (Letras de la L en adelante) para dar por cerrada la base de datos del País Vasco?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48051','fiesta','Fiestas de Nuestra Señora de las Nieves (Danza de los Arcos)','Patronal / Etnográfica / Danza Tradicional. Se celebra en Agosto. Festejos en el municipio más pequeño de la provincia que destacan por la Danza de los Arcos florales, un hito etnográfico de origen medieval ejecutado con gran pureza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48052','fiesta','Fiestas en Honor a San Emeterio y San Celedonio','Patronal / Etnográfica. Se celebra en Agosto. Festejos de fuerte arraigo identitario en el Txorierri, caracterizados por los concursos de marmitako en la plaza, bertsolaris locales, exhibiciones de danzas vascas y conciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90692','fiesta','Fiestas Patronales de San Martín','Patronal. Se celebra en Noviembre. Festejos de escala estrictamente local en Uribe Kosta, sustentados en misas solemnes tradicionales, campeonatos de mus en las tabernas y parrilladas vecinales de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47009','fiesta','Fiestas de San Juan Bautista y Umore Azoka (Feria de Artistas de Calle)','Patronal / Cultural / Festival Urbano. Se celebra en Mayo (Umore Azoka) y Junio (San Juan). La Umore Azoka ostenta el rango de Feria de Artistas de Calle de gran relevancia autonómica y nacional, transformando la localidad con cientos de espectáculos teatrales y circenses.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47010','fiesta','Fiestas de San Antolín (Fiesta de los Gansos / Antzar Eguna)','Patronal / Marinera / Etnográfica / Singular. Se celebra en Septiembre (Día de los Gansos el 5 de septiembre). Declarada Fiesta de Interés Turístico del rango regional. Espectacular hito etnográfico milenario donde los jóvenes se lanzan desde barcas para colgarse del cuello de un ganso suspendido en el puerto.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48055','fiesta','Fiestas en Honor a San Ignacio de Loyola','Patronal. Se celebra en Julio. Festejos de carácter local y familiar en el valle de Arratia, consistentes en pasacalles tradicionales vascos de txistularis, partidos de pelota mano en el frontón y verbenas lúdicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48056','fiesta','Fiestas de Arminza en Honor a Santiago Apóstol (Sukalki Eguna)','Patronal / Costera / Gastronómica. Se celebra en Julio. Festejos en el puerto pesquero de Arminza que destacan provincialmente por el multitudinario concurso gastronómico de sukalki (guisado tradicional de carne con patatas) en las campas de la costa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48081','fiesta','Fiestas Patronales de San Antolín','Patronal / Gastronómica. Se celebra en Septiembre. Festejos de la comarca del Txorierri que complementan los actos tradicionales religiosos con ferias agrícolas menores de productos del caserío, catas de txakoli local y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90953','fiesta','Fiestas de San Pedro y Gastronómica de las Alubias','Patronal / Gastronómica. Se celebra en Junio (San Pedro) y Octubre (Alubias). Celebración de la llanura metropolitana famosa por la tradicional e inmensa alubiada popular de otoño en el ferial, amenizada por folklore vasco y música de trikitixas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48058','fiesta','Fiestas Patronales de la Asunción de la Virgen','Patronal / Etnográfica. Se celebra en Agosto. Pequeña celebración vecinal en Durangaldea de fuerte arraigo euskaldun, centrada en exhibiciones de herri kirolak, arrastre de piedra por bueyes y música en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48059','fiesta','Fiestas en Honor a la Virgen de la Asunción','Patronal. Se celebra en Agosto. Festejos tradicionales de alta montaña y marcado carácter familiar al pie de Urkiola, basados en ritos religiosos tradicionales, bertsolaris locales y comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90259','fiesta','Fiestas del Carmen (Karmenak) y la Danza de las Espadas (Xemeingo Ezpata Dantza)','Patronal / Etnográfica / Danza Tradicional. Se celebra en Julio. Festejos de rango comarcal en Lea-Artibai; destaca el gran valor de su antiquísima Ezpata Dantza ejecutada en la ermita de Arretxinaga con trajes tradicionales de alta raigambre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48061','fiesta','Fiestas en Honor a San Lorenzo','Patronal. Se celebra en Agosto. Festejos de escala estrictamente local en Mungialdea, marcados por la misa solemne tradicional, partidos de pelota vasca en el frontón y comidas comunitarias de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90693','fiesta','Fiestas Patronales de San Roque','Patronal. Se celebra en Agosto. Pequeñas fiestas estivales de marcado ambiente familiar e infantil organizadas por el vecindario del caserío rural, con tradicionales misas solemnes y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48062','fiesta','Fiestas de San Miguel','Patronal. Se celebra en Septiembre. Festejos de ámbito local condicionados por la baja demografía en la Reserva de Urdaibai, basados en un mercado menor artesanal de hortalizas, folklore y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90954','fiesta','Fiestas de San Pedro y Kresala Eguna','Patronal / Marinera. Se celebra en Junio y Agosto. Festejos costeros de marcado acento vecinal junto a la playa de Karraspio, orientados a juegos tradicionales infantiles, comidas populares al aire libre y música de parrandas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48066','fiesta','Fiestas Patronales de San Esteban','Patronal. Se celebra en Agosto. Mínimos festejos de carácter vecinal en el interior de Busturialdea, limitados a actos litúrgicos tradicionales, campeonatos de mus en las tabernas y un almuerzo de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47011','fiesta','Fiestas de San Pedro y el Día de los Txistus (Arranegi Eguna)','Patronal / Marinera / Costera. Se celebra en Junio. Festejos marineros de gran popularidad en la desembocadura de Urdaibai, célebres por los tradicionales pasacalles costeros, regatas de bateles artesanales, tamborradas y verbenas masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48069','fiesta','Fiestas de San Pedro (Sanpedroak) y la Fiesta del Sukalki','Patronal / Gastronómica / Cultural. Se celebra en Junio. Grandes fiestas mayores de la capital de Mungialdea, muy populares por albergar el monumental concurso gastronómico de sukalki en Uriguen, con comparsas de gigantes tradicionales, ferias y conciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48908','fiesta','Fiestas Patronales de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Pequeña celebración de marcado carácter familiar en las marismas de la ría de Gernika, con ritos tradicionales religiosos y cenas comunitarias de hermandad al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90056','fiesta','Fiestas de San Juan Bautista y de San Antolín','Patronal / Cultural / Etnográfica. Se celebra en Junio y Septiembre. Festejos de rango comarcal consolidados al pie de la refinería, caracterizados por el encendido de monumentales hogueras costeras, desfiles de carrozas tradicionales y conciertos multitudinarios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47012','fiesta','Fiestas de Andra Mari (Andramariak) y el Día de las Alamedas','Patronal / Marinera / Etnográfica. Se celebra en Agosto (Del 14 al 17 de agosto). Festejos costeros de rango comarcal muy consolidados al límite con Guipúzcoa, célebres por la presencia del mítico personaje marinero "Leako Aitxitxa", tamborradas marítimas y regatas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48083','fiesta','Fiestas Patronales de San Félix de Cantalicio','Patronal / Etnográfica. Se celebra en Mayo. Festejos de la Zona Minera de fuerte arraigo obrero, destacados por los espectaculares campeonatos tradicionales de barrenadores perforando roca con pesadas barras de hierro.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90694','fiesta','Fiestas de Santa Marina (Andramariak)','Patronal / Etnográfica. Se celebra en Julio *. Festejos tradicionales de alta montaña al límite con Álava, caracterizados por el tradicional txupinazo, exhibiciones folclóricas de danzas vascas en la plaza y deporte rural vasco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90057','fiesta','Fiestas de San Antolín y de la Virgen del Carmen','Patronal / Marinera / Costera. Se celebra en Julio y Septiembre. Festejos costeros de gran peso comarcal en la ría, célebres por el tradicional concurso de marmitako en los muelles de la villa pesquera, desfiles tradicionales y verbenas nocturnas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48078','fiesta','Fiestas de San Roque y Fiesta de la Virgen de la Guía','Patronal / Marinera / Cultural / Urbana. Se celebra en Julio (Guía) y Agosto (San Roque). Grandes fiestas de la villa del Puente Colgante con rango comarcal y masiva afluencia provincial, célebres por la tradicional bajada de la Virgen de la Guía y los masivos bailes de la jota portugaleteña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90058','fiesta','Fiestas de la Virgen del Carmen (Karmenak)','Patronal / Marinera / Cultural / Gastronómica. Se celebra en Julio (Alrededor del 16 de julio). Grandes celebraciones de la histórica urbe pesquera de la ría, destacando el masivo hito etnográfico de la Procesión Marítima de la Virgen y la multitudinaria degustación de sardinas asadas en las parrillas del puerto.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48084','fiesta','Fiestas Patronales de San Pedro','Patronal / Cultural / Urbana. Se celebra en Junio. Festejos en la cuenca siderúrgica de la ría del Nervión con notable participación juvenil, caracterizados por grandes conciertos públicos de primer nivel en la plaza, pasacalles de cuadrillas y txosnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90955','fiesta','Fiestas de San Juan Bautista y de San Roque','Patronal / Cultural. Se celebra en Junio y Agosto. Festejos periurbanos muy concurridos en el Txorierri, caracterizados por campeonatos lúdicos locales de naipes, concursos de paella y sesiones de orquestas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90956','fiesta','Fiestas de San Pedro y de la Virgen del Carmen','Patronal / Costera / Cultural. Se celebra en Junio y Julio. Festejos costeros potenciados por el turismo surfero masivo en Uribe Kosta, arropados por grandes conciertos de rock, competiciones deportivas de playa tradicionales y verbenas lúdicas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48086','fiesta','Fiestas en Honor a Santa Ana y San Roque','Patronal. Se celebra en Julio y Agosto. Celebración de las Encartaciones occidentales de carácter local, con desfiles folclóricos tradicionales de gigantes de la comarca, parrilladas comunitarias y música de acordeón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90059','fiesta','Fiestas Patronales de San Andrés','Patronal / Costera. Se celebra en Noviembre (Oficial) y Agosto (Festejos estivales). Pequeña festividad local en la isla de Txatxarramendi que congrega a los habitantes de los caseríos costeros en torno a comidas populares al aire libre y música tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48080','fiesta','Fiestas de San Ramón Nonato','Patronal / Etnográfica. Se celebra en Agosto. Festejos de rango comarcal de alta raigambre obrera en la Zona Minera, célebres por la espectacular bajada de los carretones por las empinadas cuestas históricas, sumando deporte rural vasco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48087','fiesta','Fiestas de San Pedro y Feria Ganadera de Trucios','Patronal / Feria Ganadera Tradicional. Se celebra en Junio (San Pedro) y Noviembre (Feria). Festejos en el valle encartado que ensalzan la cría ganadera tradicional de las razas bovinas de montaña de la comarca, arropados por mercados artesanal y mercados verdes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48088','fiesta','Fiestas en Honor a San Juan Bautista','Patronal. Se celebra en Junio. Festejos rurales mínimos en la localidad menos poblada de la provincia al pie del Gorbea, limitados a actos litúrgicos religiosos, partidos de pelota mano en el frontón y almuerzo de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90957','fiesta','Fiestas de la Virgen de Udiarraga','Patronal / Etnográfica / Cultural. Se celebra en Septiembre (Alrededor del 8 de septiembre). Celebración tradicional del corredor del Nervión de gran calado comarcal, famosa por la masiva judiada popular cocinada en grandes calderas en la plaza de la villa amurallada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48089','fiesta','Fiestas de Andra Mari (Andramariak)','Patronal / Cultural. Se celebra en Septiembre. Festejos tradicionales de la comarca de Uribe con notable arraigo juvenil, caracterizados por los pasacalles de la comparsa de cabezudos, torneos de pelota mano y verbenas lúdicas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48074','fiesta','Festes de la Coronación de la Virgen de la Antigua (Otxomaio)','Patronal / Histórica / Etnográfica. Se celebra en Mayo (Alrededor del 8 de mayo). Grandes fiestas del único enclave con título de ciudad en la provincia. Célebres por el tradicional desfile del personaje folclórico "Bihotza", populosos encierros de vaquillas por el trazado medieval y ferias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48095','fiesta','Fiestas Patronales de San Andrés','Patronal. Se celebra en Julio (Festejos trasladados al verano). Celebración tradicional de Durangaldea oriental, caracterizada por ritos tradicionales religiosos, partidos de pelota mano en el frontón municipal y cenas comunitarias de hermandad al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48096','fiesta','Fiestas de Nuestra Señora de la Guía y Feria de Gangas de Zalla','Patronal / Feria Tradicional / Gastronómica. Se celebra en Octubre (Gangas). Su histórica Feria de Gangas de otoño posee rango de hito agrícola de gran calado comarcal en las Encartaciones, famoso por la exaltación y concurso de la cebolla morada de Zalla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48905','fiesta','Fiestas de San Martín y Feria Agrícola de Zamudio','Patronal / Feria de Sector. Se celebra en Noviembre. Festejos vinculados al parque tecnológico y rural del Txorierri, destacados por albergar una inmensa e histórica muestra agrícola comarcal dedicada al queso de Idiazabal y ganado de montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48097','fiesta','Fiestas Patronales de San Vicente','Patronal. Se celebra en Agosto. Festejos locales de carácter tradicional y familiar en el valle del Ibaizabal, basados en juegos infantiles tradicionales, tradicionales misas solemnes y sesiones lúdicas de trikitixa para los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90958','fiesta','Fiestas de Andra Mari y Romería de San Justo','Patronal / Romería / Etnográfica. Se celebra en Agosto. Festejos serranos al pie del Gorbea de gran valor identitario, famosos por la tradicional romería a la ermita de San Justo, las exhibiciones de arrastre de piedra por bueyes y el folclore pastoril.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90959','fiesta','Fiestas Patronales de San Antolín','Patronal. Se celebra en Septiembre. Celebración de escala estrictamente local en el interior rural de la provincia, vertebrada sobre concursos gastronómicos tradicionales de paellas, música de trikitixa y tradicionales ritos litúrgicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90060','fiesta','Fiestas de San Ignacio en el Puerto y el Día del Marisco','Patronal / Marinera / Gastronómica. Se celebra en Julio (San Ignacio) y Octubre (Marisco). Festejos costeros de fuerte arraigo marinero, célebres por su feria gastronómica otoñal dedicada a la degustación masiva de marisco artesanal en el puerto deportivo, arropada por regatas de traineras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90960','fiesta','Fiestas de Santo Tomás en Bolibar y Romería a la Colegiata de Zenarruza','Patronal / Romería / Jacobea. Se celebra en Diciembre (Santo Tomás) y Agosto (Romería). Festejos vinculados al monumental e histórico conjunto jacobeo de la Colegiata de Zenarruza, atrayendo a numerosos peregrinos por su concurrida romería tradicional y fervor comarcal en LeaArtibai). Hemos completado al 100% todos los municipios de la provincia de Vizcaya, finalizando así por completo la totalidad de la Comunidad Autónoma del País Vasco de forma exhaustiva. ¿Procedemos a abrir la última Comunidad Autónoma de la base de datos jerárquica global siguiendo el estricto orden alfabético, que corresponde a la Región de Murcia (procesando su primer bloque de municipios de la A hasta la I)?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90402','fiesta','Fiestas Patronales de la Santísima Cruz y Desfiles de Moros y Cristianos','Patronal / Moros y Cristianos / Etnográfica. Se celebra en Abril y Mayo. Declaradas de Interés Turístico Regional. Festejos de gran empaque comarcal célebres por la espectacularidad de sus kábilas y mesnadas en un vistoso desfile, y la histórica romería a la ermita de Mahoya.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30002','fiesta','Fiestas Patronales en Honor a San Cosme y San Damián','Patronal / Taurina / Etnográfica. Se celebra en Septiembre. Festejos de fuerte arraigo en el Valle de Ricote, caracterizados por su tradicional corrida de toros en su centenaria plaza, pasacalles de gigantes y cabezudos, verbenas populares y la procesión de los santos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30003','fiesta','Carnaval de Águilas','Etnográfica / Carnaval / Singular. Se celebra en Febrero. Declarado Fiesta de Interés Turístico Internacional. Macrofestejo costero de impacto masivo global, célebre por la espectacular "Suelta de la Mussona", el lanzamiento de cascarones de huevo rellenos de confeti y sus monumentales desfiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30004','fiesta','Fiestas Patronales en Honor a San Isidro Labrador y los Remedios','Patronal. Se celebra en Mayo. Festejos tradicionales de marcado carácter local en la comarca del Río Mula, fundamentados en ritos religiosos tradicionales, comidas comunitarias de hermandad y verbenas lúdicas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30005','fiesta','Fiestas de la Bruja (Fiestas de Mayo)','Patronal / Etnográfica / Cultural. Se celebra en Mayo. Declaradas Fiesta de Interés Turístico Regional. Gran celebración de rango comarcal muy popular en el área metropolitana, famosa por el tradicional juicio y quema de la Bruja, desfiles de carrozas y festivales folclóricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30902','fiesta','Fiestas de la Mar (Incursiones Berberiscas) y Fiesta de la Almeja','Recreación Histórica / Costera / Gastronómica. Se celebra en Abril (Berberiscas) y Octubre (Fiestas del Mar). Festejos costeros en el Mar Menor que destacan provincialmente por la recreación de las incursiones de los piratas berberiscos de los siglos XVI y XVII, transformando el municipio con campamentos de época y mercados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30006','fiesta','Fiestas Patronales de San Agustín y Santa María la Real (Auto de los Reyes Magos)','Patronal / Etnográfica / Teatral / Histórica. Se celebra en Enero (Auto de Reyes) y Agosto (Patronales). Su Auto de los Reyes Magos está declarado Fiesta de Interés Turístico Regional, siendo una representación teatral sacra que data del siglo XVIII interpretada en su casco antiguo medieval bajo la Torre del Homenaje.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30007','fiesta','Fiestas Patronales en Honor a San Onofre y la Virgen del Rosario','Patronal / Taurina. Se celebra en Junio. Festejos tradicionales de carácter local en la Vega Media del Segura, consistentes en pasacalles musicales, suelta de vaquillas populares en plaza portátil, procesiones tradicionales y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30008','fiesta','Fiestas de Los Mayos (Fiesta de los Corremayos)','Etnográfica / Tradicional / Carnavalicio. Se celebra en Mayo (Primer fin de semana de mayo). Declarada Fiesta de Interés Turístico Regional. Hito etnográfico de gran renombre a los pies de Sierra Espuña, célebre por la colocación de peleles o "mayos" satíricos y el masivo pasacalles de los "corremayos" vestidos con trajes de arlequín de cascabeles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30009','fiesta','Fiestas Patronales del Corpus Christi y la Virgen de la Salud','Patronal / Religiosa / Cultural. Se celebra en Junio. Festejos de gran personalidad en el Valle de Ricote, célebres por la confección de monumentales y artísticas alfombras de sal teñida que cubren las calles de la villa termal, arropadas por desfiles de moros y cristianos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30010','fiesta','Fiestas Patronales en Honor a San Bartolomé y la Fiesta de la Candelaria','Patronal / Huerta. Se celebra en Febrero y Agosto. Festejos tradicionales de la huerta al límite con Alicante, articulados sobre verbenas nocturnas al aire libre, desfiles de carrozas de peñas huertanas, ritos litúrgicos tradicionales y comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30011','fiesta','Fiestas Patronales de San Roque (Encierros de Blanca)','Patronal / Taurina / Etnográfica. Se celebra en Agosto. Festejos en el Valle de Ricote declarados de gran interés taurino regional por albergar los únicos e históricos encierros tradicionales de la Región de Murcia, arrastrando una masiva afluencia comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30012','fiesta','Fiesta del Vino de Bullas y Fiestas Patronales de la Virgen del Rosario','Enológica / Gastronómica / Patronal. Se celebra en Octubre. Festejos de hondo calado en el Noroeste dedicados a la campaña vitivinícola de la D.O. Bullas, célebres por la tradicional bendición del primer mosto, la apertura de bodegas tradicionales y el folclore huertano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30013','fiesta','Fiestas de los Santos Mártires Abdón y Senén (Encierros de Calasparra)','Patronal / Taurina / Etnográfica. Se celebra en Septiembre (Del 3 al 8 de septiembre). Declaradas de Interés Turístico Regional. Su prestigiosa feria taurina del arroz es un hito de rango nacional absoluto en las novilladas, famosa por sus espectaculares encierros matutinos por el casco urbano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30014','fiesta','Fiestas Patronales de San Juan Bautista','Patronal. Se celebra en Junio. Pequeñas fiestas estivales de marcado ambiente vecinal en la comarca del Río Mula, organizadas para el encendido de hogueras tradicionales, ritos litúrgicos en el templo parroquial y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30015','fiesta','Fiestas de la Santísima Vera Cruz (Caballos del Vino y Moros y Cristianos)','Etnográfica / Caballos / Patrimonio Humanidad / Moros y Cristianos. Se celebra en Mayo (Del 1 al 5 de mayo). Los Caballos del Vino están declarados Patrimonio Cultural Inmaterial de la Humanidad por la UNESCO. Espectacular y multitudinario hito global donde caballos engalanados con ricas piezas de oro y seda corren a contrarreloj una empinada cuesta flanqueada por miles de personas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30016','fiesta','Fiestas de Carthagineses y Romanos y la Semana Santa de Cartagena','Recreación Histórica / Religiosa / Etnográfica / Cultural. Se celebra en Marzo / Abril (Semana Santa) y Septiembre (Carthagineses y Romanos). Ambas ostentan de forma consolidada la declaración de Fiesta de Interés Turístico Internacional. Destacan por el monumental orden cronométrico de sus procesiones y los masivos desfiles históricos de legiones y tropas que reviven las Guerras Púnicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30017','fiesta','Fiestas Patronales de la Virgen de las Maravillas','Patronal / Taurina / Etnográfica. Se celebra en Septiembre. Festejos en el Noroeste que complementan los cultos solemnes con sus tradicionales corridas de toros, el Día de los Huertanos con trajes tradicionales de baturro huertano, parrandas y verbenas lúdicas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30018','fiesta','Fiestas Patronales de San Roque y Santa María Magdalena','Patronal / Cultural. Se celebra en Agosto. Festejos tradicionales de la Vega Media que dinamizan el término municipal con su tradicional desfile de carrozas populares, competiciones lúdicas locales y verbenas públicas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30021','fiesta','Fiestas Patronales de San Agustín','Patronal / Etnográfica. Se celebra en Agosto. Festejos de arraigo local tradicionales en el Campo de Cartagena, caracterizados por el tradicional concurso de migas ruleiras, pasacalles de cuadrillas con trovos locales y verbenas estivales). ¿Deseas continuar con el Siguiente Bloque de la Región de Murcia (Letras de la J en adelante.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30022','fiesta','Fiesta de la Vendimia de Jumilla y Semana Santa de Jumilla','Enológica / Gastronómica / Religiosa / Patronal. Se celebra en Marzo / Abril (Semana Santa) y Agosto (Vendimia). Ambas de enorme arraigo; su Semana Santa y su Fiesta de la Vendimia ostentan la declaración de Fiesta de Interés Turístico Nacional. Destaca la monumental Gran Cabalgata del Vino, donde se reparten miles de litros de vino con D.O.P. Jumilla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30023','fiesta','Fiestas Patronales en Honor a San Bartolomé (Las Pitanzas)','Patronal / Etnográfica / Singular. Se celebra en Agosto. Destaca a nivel provincial por el singular hito etnográfico medieval de "Las Pitanzas", donde miles de panecillos bendecidos son arrojados desde los balcones del ayuntamiento a la multitud.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30024','fiesta','Semana Santa de Lorca y Feria de Lorca','Religiosa / Etnográfica / Histórica / Caballos. Se celebra en Marzo / Abril (Semana Santa) y Septiembre (Feria). Declarada Fiesta de Interés Turístico Internacional. Colosal y multitudinario hito global famoso por sus espectaculares desfiles bíblicopasionales, donde compiten los bandos Azul y Blanco con bordados en seda y oro únicos en el mundo y exhibiciones ecuestres monumentales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30025','fiesta','Fiestas Patronales de Santiago Apóstol','Patronal. Se celebra en Julio. Festejos de arraigo local tradicionales en la Vega Media, caracterizados por los pasacalles populares, verbenas nocturnas al aire libre, cenas de hermandad y la tradicional procesión de la imagen del apóstol.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30026','fiesta','Fiestas Patronales de la Purísima Concepción y Romería de la Virgen del Milagro','Patronal / Romería / Costera. Se celebra en Noviembre y Diciembre. Festejos de rango comarcal muy populares, célebres por la concurrida romería que traslada la imagen de la virgen desde el Puerto hasta el pueblo, rememorando el milagro de los piratas berberiscos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30027','fiesta','Fiestas Patronales de la Virgen de la Consolación y Festival de Teatro de Molina','Patronal / Cultural / Festival Urbano. Se celebra en Septiembre. Grandes fiestas mayores de la capital de la Vega Media, muy populares por albergar su prestigioso e histórico Festival Internacional de Teatro de Calle, sumado a conciertos públicos masivos y populosos desfiles de carrozas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30028','fiesta','Semana Santa de Moratalla (Fiesta de los Tambores) y Fiestas de San Zenón','Religiosa / Etnográfica / Tamborradas / Taurina. Se celebra en Marzo / Abril (Semana Santa) y Julio (San Zenón). Su Fiesta de los Tambores posee rango de Interés Turístico Regional y está integrada en el Patrimonio de la Humanidad de la UNESCO, destacando por las multitudinarias y libres "tamboradas" por su casco antiguo medieval, sumándose en julio sus encierros taurinos por veredas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30029','fiesta','Semana Santa de Mula (La Noche de los Tambores) y Fiestas de San Isidro','Religiosa / Etnográfica / Tamborradas / Huerta. Se celebra en Marzo / Abril (Semana Santa) y Mayo (San Isidro). La Noche de los Tambores ostenta la declaración de Fiesta de Interés Turístico Internacional, hito etnográfico masivo absoluto donde miles de tamboristas rompen la hora en la medianoche del Martes Santo inundando la plaza del ayuntamiento.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30030','fiesta','Fiestas de Primavera (Bando de la Huerta y Entierro de la Sardina) y Feria de Murcia','Etnográfica / Huerta / Carnavalicio / Cultural. Se celebra en Marzo / Abril (Primavera) y Septiembre (Feria). Tanto el Bando de la Huerta como el Entierro de la Sardina ostentan la máxima declaración de Fiesta de Interés Turístico Internacional. Macrofestejo masivo global de primer orden que exalta la cultura huertana más pura mediante desfiles monumentales de barracas y carrozas mitológicas de fuego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30031','fiesta','Fiestas Patronales de San Agustín y la Virgen de la Cabeza','Patronal / Etnográfica. Se celebra en Agosto. Pequeña celebración en el corazón del Valle de Ricote de hondo sabor morisco, estructurada con ritos litúrgicos tradicionales, la clásica tirada de cohetes tradicionales locales de solera y verbenas íntimas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30032','fiesta','Fiestas Patronales en Honor a la Virgen de los Remedios','Patronal / Romería. Se celebra en Septiembre. Festejos locales tradicionales de la comarca de la Cuenca de Mula, caracterizados por la concurrida bajada y procesión de la virgen, cantos de cuadrillas con trovos tradicionales y verbenas lúdicas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30033','fiesta','Fiestas Patronales de la Virgen del Rosario y Baile de la Reina','Patronal / Gala Tradicional / Cultural. Se celebra en Octubre (Alrededor del 7 de octubre). Festejos de rango comarcal destacados por el monumental e histórico Baile de la Reina, una de las galas tradicionales de sociedad más antiguas y populosas del sureste peninsular que atrae numerosa prensa provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30034','fiesta','Fiestas Patronales de San Sebastián','Patronal. Se celebra en Enero. Festejos invernales de ámbito estrictamente local en el valle, basados en misas solemnes tradicionales en su templo barroco, pasacalles de música tradicional y comidas vecinales de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30035','fiesta','Fiestas Patronales de San Javier y Carnaval de Santiago de la Ribera','Patronal / Costera / Carnaval / Cultural. Se celebra en Febrero/Marzo (Carnaval) y Diciembre (Patronales). Festejos costeros de rango comarcal muy consolidados en el Mar Menor, caracterizados por un potente programa lúdico que une la tradición aeronáutica local, desfiles, conciertos y fuegos de artificio masivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30036','fiesta','Fiestas de la Virgen del Carmen y Fiestas Patronales de San Pedro','Patronal / Marinera / Costera / Etnográfica. Se celebra en Junio y Julio (Día del Carmen el 16 de julio). Declarada de gran interés marinero regional. Destaca de forma monumental por su histórica Procesión Marítima de la Virgen del Carmen por el Mar Menor, flanqueada por cientos de barcos engalanados y salvas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30901','fiesta','Fiestas Patronales de la Virgen del Rosario y Desfiles de Moros y Cristianos','Patronal / Moros y Cristianos / Huerta. Se celebra en Septiembre y Octubre. Festejos tradicionales de la Huerta de Murcia con desfiles folclóricos tradicionales de moros y cristianos locales, concursos gastronómicos de migas y alta participación juvenil en las verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30037','fiesta','Fiestas Patronales de la Virgen del Rosario y Fiesta Trinitario-Berberisca','Patronal / Recreación Histórica / Campo. Se celebra en Octubre. Festejos del Campo de Cartagena que combinan la recreación histórica de la defensa agraria medieval ante corsarios berberiscos con desfiles de peñas locales, conciertos y verbenas lúdicas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30038','fiesta','Fiestas Patronales en Honor a la Virgen de la Salceda','Patronal / Cultural. Se celebra en Agosto. Festejos tradicionales de la Vega Media con notable arraigo juvenil, caracterizados por su tradicional desfile de carrozas populares, la popular quema del Raspajo como hito de clausura y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30039','fiesta','Fiestas de Santiago Apóstol y Romería de Santa Eulalia de Mérida','Patronal / Romería / Etnográfica / Alfarera. Se celebra en Julio (Santiago) y Diciembre (La Santa). Su multitudinaria e histórica romería de la bajada de "La Santa" desde Sierra Espuña posee rango comarcal muy popular, arropada por los tradicionales cantos de los Auroros locales de solera, música y comidas campestres.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30040','fiesta','Festividades de la Santa Cruz y de San Bartolomé','Patronal / Etnográfica. Se celebra en Mayo (Cruz) y Agosto (San Bartolomé) *. Celebración tradicional del Valle de Ricote famosa provincialmente por el rito tradicional del baño de la Santa Cruz en las aguas de riego del Segre para bendecir las cosechas hortícolas, con verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30042','fiesta','Fiestas Patronales de la Virgen de la Asunción y la Fiesta de San Roque','Patronal / Huerta. Se celebra en Agosto. Festejos locales de carácter tradicional y familiar en el corazón del valle baturro huertano, basados en juegos infantiles tradicionales, la santa procesión de la patrona y sesiones lúdicas de baile públicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30043','fiesta','Fiestas de la Virgen del Castillo de Yecla','Patronal / Etnográfica / Histórica / Pólvora. Se celebra en Diciembre (Del 5 al 8 de diciembre). Declarada Fiesta de Interés Turístico Nacional. Hito etnográfico absoluto e histórico del Altiplano, célebre por las Compañías de Arcabuceros que inundan de forma masiva la ciudad quemando toneladas de pólvora con sus arcabuces tradicionales al son del paso de la virgen.','inventario_fiestas_pdf');
